--  
-- CREATE DATABASE ktd_sl
-- WITH 
-- ENCODING = 'UTF8'          -- 字符集编码为UTF8，支持中文、特殊字符，避免乱码
-- TEMPLATE = template0       -- 使用纯净系统模板template0，防止继承旧库配置，PostGIS建库必用
-- LC_COLLATE = ''            -- 排序规则使用模板默认（不指定则自动适配）
-- LC_CTYPE = ''             -- 字符分类规则使用模板默认
-- CONNECTION LIMIT = -1;     -- 数据库最大连接数不限制（-1代表无上限）
-- ktd_lx_2026gis;

-- \c  ktd_lx_2026gis;
-- 开启必须扩展
 -- 加载PL/pgSQL过程语言（PostgreSQL默认内置函数语言，必装）
CREATE EXTENSION IF NOT EXISTS plpgsql;
-- PostGIS 空间地理扩展（Cesium三维GIS、地图、几何计算核心依赖）
CREATE EXTENSION IF NOT EXISTS postgis;          -- 基础PostGIS（点线面、坐标、空间索引）
CREATE EXTENSION IF NOT EXISTS postgis_topology; -- 拓扑结构支持（地理数据校验、空间关系）
CREATE EXTENSION IF NOT EXISTS postgis_sfcgal;    -- 高级3D几何运算（Cesium 3D模型、体积计算）
-- TimescaleDB 时序数据库扩展（无人机、物联网高频采集数据存储、查询优化）
CREATE EXTENSION IF NOT EXISTS timescaledb;
 
 
-- 只查询 plpgsql、postgis、timescaledb 等核心扩展
SELECT 
  extname AS 扩展名称,
  extversion AS 版本号,
  CASE WHEN extname IS NOT NULL THEN '已安装' ELSE '未安装' END AS 状态
FROM pg_extension
WHERE extname IN (
  'plpgsql',
  'postgis',
  'postgis_topology',
  'postgis_sfcgal',
  'timescaledb'
)
ORDER BY extname;

 



--   gis_error_log                        创建PG相关GIS错误日志

-- =============================================================================
-- PG相关GIS错误日志
-- =============================================================================
DROP TABLE IF EXISTS public.gis_error_log;

CREATE TABLE IF NOT EXISTS public.gis_error_log (
    id bigserial PRIMARY KEY,
    code integer,
    msg text,
    sqlstring text,
    create_time timestamp without time zone DEFAULT now()
);
COMMENT ON TABLE public.gis_error_log IS 'PG相关GIS错误日志';
COMMENT ON COLUMN public.gis_error_log.id IS '日志主键ID';
COMMENT ON COLUMN public.gis_error_log.code IS '错误状态码：400=参数/业务错误，500=系统异常';
COMMENT ON COLUMN public.gis_error_log.msg IS '错误提示信息';
COMMENT ON COLUMN public.gis_error_log.sqlstring IS '触发错误时的SQL语句';
COMMENT ON COLUMN public.gis_error_log.create_time IS '日志创建时间';

CREATE INDEX IF NOT EXISTS idx_gis_error_log_create_time
ON public.gis_error_log(create_time DESC);
COMMENT ON INDEX public.idx_gis_error_log_create_time IS 'PG相关GIS错误日志创建时间倒序查询索引';



-- =============================================================================
-- 删除函数
-- =============================================================================
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (SELECT oid, proname, pg_get_function_identity_arguments(oid) as args
              FROM pg_proc
              WHERE proname = 'gis_drop_function')
    LOOP
        EXECUTE 'DROP FUNCTION ' || r.oid::regproc || '(' || r.args || ') CASCADE';
    END LOOP;
END;
$$;
-- =============================================================================
-- 函数名称：gis_drop_function
-- 函数功能：按函数名删除同名函数及其所有重载
-- 入参说明：
--   1. p_function_name 支持不带 schema 的函数名，例如 'gis_geojson_to_geom'。
--   2. p_function_name 也支持 schema.function_name，例如 'public.gis_geojson_to_geom'。
-- 返回说明：无返回值；匹配到的函数会通过 DROP FUNCTION IF EXISTS ... CASCADE 删除。
-- 处理规则：
--   1. 入参为空时抛出异常。
--   2. 不带 schema 时删除所有 schema 下同名函数。
--   3. 带 schema 时只删除指定 schema 下的同名函数。
-- 逻辑步骤：
--   1. 校验 p_function_name 是否为空。
--   2. 判断入参是否包含 schema，并拆分 schema_name/function_name。
--   3. 查询 pg_proc 和 pg_namespace，找出匹配的函数及参数签名。
--   4. 循环执行 DROP FUNCTION IF EXISTS schema.function(args) CASCADE。
-- 使用示例：
--   SELECT public.gis_drop_function('gis_geojson_to_geom');
--   SELECT public.gis_drop_function('public.gis_geojson_to_geom');
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_drop_function(p_function_name text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    r RECORD;
    v_schema_name text;
    v_function_name text;
BEGIN
    -- 步骤 1：校验入参，函数名不能为空。
    IF p_function_name IS NULL OR trim(p_function_name) = '' THEN
        RAISE EXCEPTION 'Function name cannot be empty';
    END IF;

    -- 步骤 2：判断是否传入 schema，并拆分 schema 与函数名。
    IF position('.' IN p_function_name) > 0 THEN
        v_schema_name := split_part(p_function_name, '.', 1);
        v_function_name := split_part(p_function_name, '.', 2);
    ELSE
        v_function_name := p_function_name;
    END IF;

    -- 步骤 3：从系统目录查询所有匹配的函数重载。
    FOR r IN (
        SELECT
            n.nspname AS schema_name,
            p.proname AS function_name,
            pg_get_function_identity_arguments(p.oid) AS function_args
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE p.proname = v_function_name
          AND (v_schema_name IS NULL OR n.nspname = v_schema_name)
    )
    LOOP
        -- 步骤 4：逐个重载函数执行 DROP FUNCTION。
        EXECUTE format(
            'DROP FUNCTION IF EXISTS %I.%I(%s) CASCADE',
            r.schema_name,
            r.function_name,
            r.function_args
        );
    END LOOP;
END;
$$;
COMMENT ON FUNCTION gis_drop_function(text) IS '按名称删除同名重载函数';
 
-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_geojson_to_geom');
 

CREATE OR REPLACE FUNCTION public.gis_geojson_to_geom(
    p_geojson text
)
RETURNS geometry
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_json jsonb;
    v_geom_json jsonb;
    v_geom_type text;
    v_geom geometry;
    v_closed_coordinates jsonb;
    v_features jsonb;
    v_feature_count integer;
    v_bad_ring_count integer;
BEGIN
    -- 步骤 1：清理并校验输入文本，空文本直接返回 NULL。
    IF p_geojson IS NULL OR btrim(p_geojson) = '' THEN
        RETURN NULL;
    END IF;

    -- 步骤 2：将 GeoJSON 文本转换为 jsonb，非法 JSON 会由 PostgreSQL 抛出异常。
    v_json := p_geojson::jsonb;

    -- 步骤 3：按 Geometry / Feature / FeatureCollection 三种输入形式提取 geometry JSON。
    IF v_json ->> 'type' = 'FeatureCollection' THEN
        v_features := CASE
            WHEN jsonb_typeof(v_json -> 'features') = 'array' THEN v_json -> 'features'
            ELSE '[]'::jsonb
        END;

        -- 步骤 3.1：单次遍历 FeatureCollection，同时完成有效 geometry 统计和合并结果生成。
        WITH valid_features AS (
            SELECT
                f.feature -> 'geometry' AS geom_json,
                feature_ord
            FROM jsonb_array_elements(v_features) WITH ORDINALITY AS f(feature, feature_ord)
            WHERE jsonb_typeof(f.feature -> 'geometry') = 'object'
        ),
        feature_stats AS (
            SELECT
                count(*) AS feature_count,
                CASE
                    WHEN count(*) = 0 THEN NULL::jsonb
                    WHEN count(*) = 1 THEN (array_agg(geom_json ORDER BY feature_ord))[1]
                    WHEN bool_and(geom_json ->> 'type' = 'Point')
                        THEN jsonb_build_object(
                            'type', 'MultiPoint',
                            'coordinates', jsonb_agg(geom_json -> 'coordinates' ORDER BY feature_ord)
                        )
                    WHEN bool_and(geom_json ->> 'type' = 'LineString')
                        THEN jsonb_build_object(
                            'type', 'MultiLineString',
                            'coordinates', jsonb_agg(geom_json -> 'coordinates' ORDER BY feature_ord)
                        )
                    WHEN bool_and(geom_json ->> 'type' = 'Polygon')
                        THEN jsonb_build_object(
                            'type', 'MultiPolygon',
                            'coordinates', jsonb_agg(geom_json -> 'coordinates' ORDER BY feature_ord)
                        )
                    ELSE jsonb_build_object(
                        'type', 'GeometryCollection',
                        'geometries', jsonb_agg(geom_json ORDER BY feature_ord)
                    )
                END AS merged_geom_json
            FROM valid_features
        )
        SELECT feature_count, merged_geom_json
        INTO v_feature_count, v_geom_json
        FROM feature_stats;

        IF v_feature_count = 0 THEN
            RETURN NULL;
        END IF;
    ELSIF v_json ->> 'type' = 'Feature' THEN
        v_geom_json := v_json -> 'geometry';
    ELSE
        v_geom_json := v_json;
    END IF;

    -- 步骤 4：没有提取到 geometry 时返回 NULL。
    IF v_geom_json IS NULL THEN
        RETURN NULL;
    END IF;

    -- 步骤 5：读取 geometry 类型，只有面类型需要额外闭合处理。
    v_geom_type := v_geom_json ->> 'type';

    -- 步骤 6：Polygon 校验坐标结构、坏 ring，并自动补闭合点。
    IF v_geom_type = 'Polygon' THEN
        IF jsonb_typeof(v_geom_json -> 'coordinates') IS DISTINCT FROM 'array' THEN
            RETURN NULL;
        END IF;

        IF jsonb_array_length(v_geom_json -> 'coordinates') = 0 THEN
            RETURN NULL;
        END IF;

        SELECT
            count(*) FILTER (
                WHERE CASE
                    WHEN jsonb_typeof(ring) = 'array' THEN jsonb_array_length(ring) < 3
                    ELSE true
                END
            ),
            COALESCE(
                jsonb_agg(
                    CASE
                        WHEN jsonb_typeof(ring) = 'array' THEN
                            CASE
                                WHEN jsonb_array_length(ring) > 0
                                     AND ring -> 0 <> ring -> (jsonb_array_length(ring) - 1)
                                    THEN ring || jsonb_build_array(ring -> 0)
                                ELSE ring
                            END
                        ELSE ring
                    END
                    ORDER BY ring_ord
                ),
                '[]'::jsonb
            )
        INTO v_bad_ring_count, v_closed_coordinates
        FROM jsonb_array_elements(v_geom_json -> 'coordinates') WITH ORDINALITY AS r(ring, ring_ord);

        IF v_bad_ring_count > 0 THEN
            RETURN NULL;
        END IF;

        v_geom_json := jsonb_set(v_geom_json, '{coordinates}', v_closed_coordinates, false);

    -- 步骤 7：MultiPolygon 逐 polygon、逐 ring 校验并自动补闭合点。
    ELSIF v_geom_type = 'MultiPolygon' THEN
        IF jsonb_typeof(v_geom_json -> 'coordinates') IS DISTINCT FROM 'array' THEN
            RETURN NULL;
        END IF;

        IF jsonb_array_length(v_geom_json -> 'coordinates') = 0 THEN
            RETURN NULL;
        END IF;

        WITH polygons AS (
            SELECT poly, poly_ord
            FROM jsonb_array_elements(v_geom_json -> 'coordinates') WITH ORDINALITY AS p(poly, poly_ord)
        ),
        closed_polygons AS (
            SELECT
                p.poly_ord,
                CASE
                    WHEN jsonb_typeof(p.poly) IS DISTINCT FROM 'array' THEN 1
                    WHEN jsonb_array_length(p.poly) = 0 THEN 1
                    ELSE COALESCE(sum(
                        CASE
                            WHEN jsonb_typeof(r.ring) = 'array' THEN
                                CASE WHEN jsonb_array_length(r.ring) < 3 THEN 1 ELSE 0 END
                            ELSE 1
                        END
                    ), 0)::integer
                END AS bad_ring_count,
                CASE
                    WHEN jsonb_typeof(p.poly) IS DISTINCT FROM 'array' THEN NULL::jsonb
                    WHEN jsonb_array_length(p.poly) = 0 THEN NULL::jsonb
                    ELSE COALESCE(
                        jsonb_agg(
                            CASE
                                WHEN jsonb_typeof(r.ring) = 'array' THEN
                                    CASE
                                        WHEN jsonb_array_length(r.ring) > 0
                                             AND r.ring -> 0 <> r.ring -> (jsonb_array_length(r.ring) - 1)
                                            THEN r.ring || jsonb_build_array(r.ring -> 0)
                                        ELSE r.ring
                                    END
                                ELSE r.ring
                            END
                            ORDER BY r.ring_ord
                        ),
                        '[]'::jsonb
                    )
                END AS poly_closed
            FROM polygons p
            LEFT JOIN LATERAL jsonb_array_elements(
                CASE WHEN jsonb_typeof(p.poly) = 'array' THEN p.poly ELSE '[]'::jsonb END
            ) WITH ORDINALITY AS r(ring, ring_ord)
                ON jsonb_typeof(p.poly) = 'array'
            GROUP BY p.poly_ord, p.poly
        )
        SELECT
            COALESCE(sum(bad_ring_count), 0)::integer,
            COALESCE(jsonb_agg(poly_closed ORDER BY poly_ord), '[]'::jsonb)
        INTO v_bad_ring_count, v_closed_coordinates
        FROM closed_polygons;

        IF v_bad_ring_count > 0 THEN
            RETURN NULL;
        END IF;

        v_geom_json := jsonb_set(v_geom_json, '{coordinates}', v_closed_coordinates, false);
    END IF;

    -- 步骤 8：将最终 GeoJSON 交给 PostGIS 转为 geometry，并统一按 EPSG:4326 返回。
    v_geom := ST_GeomFromGeoJSON(v_geom_json::text);
    RETURN ST_SetSRID(v_geom, 4326);
END;
$$;

COMMENT ON FUNCTION public.gis_geojson_to_geom(text) IS '解析 GeoJSON 为空间 geometry，支持 Feature/FeatureCollection，修补Polygon数据，并统一返回SRID=4326'; 
 
 -- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_refresh_all_tables');

 
CREATE OR REPLACE FUNCTION public.gis_refresh_all_tables()
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE
    r RECORD;
    v_count integer := 0;
BEGIN
    -- 步骤 1：从 pg_tables 获取所有需要刷新统计信息的用户表。
    FOR r IN (
        SELECT schemaname, tablename
        FROM pg_tables
        WHERE schemaname NOT IN ('pg_catalog', 'information_schema')
          AND schemaname NOT LIKE 'pg_%'
        ORDER BY schemaname, tablename
    )
    LOOP
        -- 步骤 2：对当前用户表执行 ANALYZE。
        EXECUTE format('ANALYZE %I.%I', r.schemaname, r.tablename);
        -- 步骤 3：输出处理进度，并累加刷新数量。
        RAISE NOTICE '已分析: %.%', r.schemaname, r.tablename;
        v_count := v_count + 1;
    END LOOP;

    -- 步骤 4：返回本次完成 ANALYZE 的用户表数量。
    RETURN v_count;
END;
$$;
COMMENT ON FUNCTION public.gis_refresh_all_tables() IS '刷新所有用户表统计信息';
 
SELECT gis_refresh_all_tables();
 

-- ====================================================================================
-- 9. 飞行路径记录表 gis_flight_paths
-- ====================================================================================
DROP INDEX IF EXISTS idx_gis_flight_paths_project_id;
DROP INDEX IF EXISTS idx_gis_flight_paths_del_flag;
DROP INDEX IF EXISTS idx_gis_flight_paths_project_del;
DROP INDEX IF EXISTS idx_gis_flight_paths_start_point;
DROP INDEX IF EXISTS idx_gis_flight_paths_end_point;
DROP TABLE IF EXISTS gis_flight_paths CASCADE;

CREATE TABLE IF NOT EXISTS gis_flight_paths (
    id SERIAL PRIMARY KEY,
    project_id char(32) DEFAULT NULL,
    create_user varchar(32) DEFAULT NULL,
    create_time timestamp NOT NULL DEFAULT NOW(),
    update_user varchar(32) DEFAULT NULL,
    update_time timestamp NOT NULL DEFAULT NOW(),
    del_flag boolean DEFAULT false NOT NULL,
    start_point geometry(PointZ,4326),
    end_point geometry(PointZ,4326),
    safe_altitude double precision,
    path_line geometry(LineStringZ,4326),
    smooth_path_line geometry(LineStringZ,4326),
    waypoints jsonb,
    smooth_waypoints jsonb,
    total_distance double precision,
    smooth_ratio double precision DEFAULT 0
);

COMMENT ON TABLE gis_flight_paths IS '无人机3D规划飞行路径记录表';
COMMENT ON COLUMN gis_flight_paths.id IS '自增主键ID';
COMMENT ON COLUMN gis_flight_paths.project_id IS '项目ID';
COMMENT ON COLUMN gis_flight_paths.create_user IS '创建者';
COMMENT ON COLUMN gis_flight_paths.create_time IS '创建时间';
COMMENT ON COLUMN gis_flight_paths.update_user IS '更新者';
COMMENT ON COLUMN gis_flight_paths.update_time IS '更新时间';
COMMENT ON COLUMN gis_flight_paths.del_flag IS '是否删除：true=删除，false=未删除';
COMMENT ON COLUMN gis_flight_paths.start_point IS '航线起点3D空间坐标（经纬度+高度）';
COMMENT ON COLUMN gis_flight_paths.end_point IS '航线终点3D空间坐标（经纬度+高度）';
COMMENT ON COLUMN gis_flight_paths.safe_altitude IS '规划安全飞行高度，单位：米';
COMMENT ON COLUMN gis_flight_paths.path_line IS '原始规划3D路径线几何';
COMMENT ON COLUMN gis_flight_paths.smooth_path_line IS '处理后3D路径线几何';
COMMENT ON COLUMN gis_flight_paths.waypoints IS '原始规划航点JSON数组';
COMMENT ON COLUMN gis_flight_paths.smooth_waypoints IS '处理后航点JSON数组';
COMMENT ON COLUMN gis_flight_paths.total_distance IS '处理后航线总长度，单位：米';
COMMENT ON COLUMN gis_flight_paths.smooth_ratio IS '高度平滑比例：0=直升-平飞-直降，0<ratio<1=爬升-平飞-降落';

-- 按项目查询历史航线、项目航线列表。
CREATE INDEX IF NOT EXISTS idx_gis_flight_paths_project_id ON gis_flight_paths (project_id);
COMMENT ON INDEX idx_gis_flight_paths_project_id IS '按项目ID查询飞行路径记录';

-- 按逻辑删除状态过滤有效航线。
CREATE INDEX IF NOT EXISTS idx_gis_flight_paths_del_flag ON gis_flight_paths (del_flag);
COMMENT ON INDEX idx_gis_flight_paths_del_flag IS '按逻辑删除标识过滤飞行路径记录';

-- 高频组合条件：项目 + 未删除。
CREATE INDEX IF NOT EXISTS idx_gis_flight_paths_project_del ON gis_flight_paths (project_id, del_flag);
COMMENT ON INDEX idx_gis_flight_paths_project_del IS '按项目ID和删除标识组合查询飞行路径记录';

-- 起点空间索引，用于起点附近航线检索。
CREATE INDEX IF NOT EXISTS idx_gis_flight_paths_start_point ON gis_flight_paths USING GIST (start_point);
COMMENT ON INDEX idx_gis_flight_paths_start_point IS '航线起点空间索引，用于起点附近查询';

-- 终点空间索引，用于终点附近航线检索。
CREATE INDEX IF NOT EXISTS idx_gis_flight_paths_end_point ON gis_flight_paths USING GIST (end_point);
COMMENT ON INDEX idx_gis_flight_paths_end_point IS '航线终点空间索引，用于终点附近查询';

