-- ----------------------------
-- Table structure for wrj_jfq_dj
-- ----------------------------
DROP TABLE IF EXISTS "public"."wrj_jfq_dj";
CREATE TABLE "public"."wrj_jfq_dj" (
  "gid" int4 NOT NULL GENERATED BY DEFAULT AS IDENTITY (
INCREMENT 1
MINVALUE  1
MAXVALUE 2147483647
START 1
CACHE 1
),
  "area_id" int8,
  "name" varchar(254) COLLATE "pg_catalog"."default",
  "type" numeric,
  "level" numeric,
  "color" varchar(254) COLLATE "pg_catalog"."default",
  "country" varchar(254) COLLATE "pg_catalog"."default",
  "city" varchar(254) COLLATE "pg_catalog"."default",
  "address" varchar(254) COLLATE "pg_catalog"."default",
  "descriptio" varchar(254) COLLATE "pg_catalog"."default",
  "height" numeric,
  "radius" numeric,
  "begin_at" numeric,
  "end_at" numeric,
  "data_sourc" numeric,
  "url" varchar(254) COLLATE "pg_catalog"."default",
  "shiid" varchar(10) COLLATE "pg_catalog"."default",
  "shicode" varchar(10) COLLATE "pg_catalog"."default",
  "shiname" varchar(30) COLLATE "pg_catalog"."default",
  "shengcode" varchar(10) COLLATE "pg_catalog"."default",
  "shengid" varchar(10) COLLATE "pg_catalog"."default",
  "shengname" varchar(24) COLLATE "pg_catalog"."default",
  "type_name" varchar(254) COLLATE "pg_catalog"."default",
  "level_name" varchar(254) COLLATE "pg_catalog"."default",
  "geom" "public"."geometry"
)
;
COMMENT ON COLUMN "public"."wrj_jfq_dj"."area_id" IS '禁飞区唯一标识';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."name" IS '禁飞区名称';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."type" IS '禁飞区类型';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."level" IS '禁飞级别(0-机场禁飞区,1-机场限飞区,2-国家级机场禁飞区,3-临时限飞区,7-干扰源区域,8-军事管理区,10-特殊管控区)';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."color" IS '显示颜色';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."country" IS '国家';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."city" IS '城市';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."address" IS '详细地址';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."descriptio" IS '描述信息';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."height" IS '高度限制(米)';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."radius" IS '半径(米)';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."begin_at" IS '开始时间(时间戳)';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."end_at" IS '结束时间(时间戳)';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."data_sourc" IS '数据源标识';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."url" IS '详情链接';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."shiid" IS '市级ID';
COMMENT ON COLUMN "public"."wrj_jfq_dj"."shicode" IS '市级编码';
