  "update_user" varchar(32) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT now(),
  "del_flag" bool NOT NULL DEFAULT false,
  "start_point" "public"."geometry",
  "end_point" "public"."geometry",
  "safe_altitude" float8,
  "path_line" "public"."geometry",
  "smooth_path_line" "public"."geometry",
  "waypoints" jsonb,
  "smooth_waypoints" jsonb,
  "total_distance" float8,
  "smooth_ratio" float8 DEFAULT 0
)
;
COMMENT ON COLUMN "public"."gis_flight_paths"."id" IS '自增主键ID';
COMMENT ON COLUMN "public"."gis_flight_paths"."project_id" IS '项目ID';
COMMENT ON COLUMN "public"."gis_flight_paths"."create_user" IS '创建者';
COMMENT ON COLUMN "public"."gis_flight_paths"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."gis_flight_paths"."update_user" IS '更新者';
COMMENT ON COLUMN "public"."gis_flight_paths"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."gis_flight_paths"."del_flag" IS '是否删除：true=删除，false=未删除';
COMMENT ON COLUMN "public"."gis_flight_paths"."start_point" IS '航线起点3D空间坐标（经纬度+高度）';
COMMENT ON COLUMN "public"."gis_flight_paths"."end_point" IS '航线终点3D空间坐标（经纬度+高度）';
COMMENT ON COLUMN "public"."gis_flight_paths"."safe_altitude" IS '规划安全飞行高度，单位：米';
COMMENT ON COLUMN "public"."gis_flight_paths"."path_line" IS '原始规划3D路径线几何';
COMMENT ON COLUMN "public"."gis_flight_paths"."smooth_path_line" IS '处理后3D路径线几何';
COMMENT ON COLUMN "public"."gis_flight_paths"."waypoints" IS '原始规划航点JSON数组';
COMMENT ON COLUMN "public"."gis_flight_paths"."smooth_waypoints" IS '处理后航点JSON数组';
COMMENT ON COLUMN "public"."gis_flight_paths"."total_distance" IS '处理后航线总长度，单位：米';
COMMENT ON COLUMN "public"."gis_flight_paths"."smooth_ratio" IS '高度平滑比例：0=直升-平飞-直降，0<ratio<1=爬升-平飞-降落';
COMMENT ON TABLE "public"."gis_flight_paths" IS '无人机3D规划飞行路径记录表';

