-- ===== BEGIN FILE: 10-hanshu.sql =====
-- =============================================================================
-- 2.1电子围栏创建-函数.sql
--   gis_electric_fence_project              生成项目电子围栏表
--   gis_get_electric_fence_project          查询项目电子围栏数据
--
-- =============================================================================

-- ============================================================
-- 函数名称： gis_electric_fence_project
-- 函数功能： 动态创建项目专属电子围栏表，并自动导入相交的禁飞区、试飞区数据
-- 函数描述：  1. 根据传入项目ID，自动创建电子围栏独立表
--            2. 自动抽取与项目地理范围相交的禁飞区、各省试飞区数据
--            3. 兼容源表字段缺失，不会因字段不存在报错
--            4. 保留完整原始几何，不做相交裁剪，只做相交筛选
--            5. 返回统一标准结果集，方便前端/业务系统直接使用
-- 函数说明： 依赖PostGIS空间扩展，坐标系使用WGS84(4326)
-- 函数注意：
--   1. 依赖基础表：wrj_jfq_dj（禁飞区）、jc_sheng（省份）、各省试飞区表
--   2. 空间判断使用ST_Intersects，仅筛选相交，保留完整原始几何
--   3. 每次执行会先删除旧表再重建，保证数据最新
--   4. 自动创建空间索引，提升查询效率
-- 适用场景： 按项目生成独立电子围栏库，用于无人机飞行区域合规校验
-- ============================================================

-- ==================================================
-- gis_electric_fence_project 动态创建项目专属电子围栏表
-- ==================================================
-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_electric_fence_project');

-- ============================================================
-- 函数名称： gis_electric_fence_project
-- 函数功能： 动态创建项目专属电子围栏表，并自动导入相交的禁飞区、试飞区数据
-- 参数说明：
--   p_project_id    text        输入参数：项目唯一ID（用于生成表名）
--   p_geom_json     text        输入参数：项目范围的GeoJSON多边形字符串
-- 返回值： 标准TABLE结构
--   code        integer     状态码：200=执行成功 400=参数错误/无数据 500=执行异常
--   msg         varchar     状态描述信息
--   tablename   varchar     生成的项目电子围栏表名
--   count       bigint      导入围栏数据总条数
-- 注意事项：执行前会删除同名项目围栏表后重建；依赖PostGIS和源围栏、省份试飞区数据表。
-- ============================================================
CREATE OR REPLACE FUNCTION gis_electric_fence_project(
    p_project_id text,  -- 输入：项目唯一ID
    p_geom_json text    -- 输入：项目范围GeoJSON字符串
)
RETURNS TABLE (
    code integer,       -- 返回：状态码
    msg varchar,        -- 返回：状态信息
    table_name varchar, -- 返回：生成的表名
    count bigint        -- 返回：数据条数
)
LANGUAGE plpgsql
AS $$
DECLARE
  -- 说明：
    -- 1. 本函数按项目ID动态生成一张独立电子围栏表，表名规则为 gis_electric_fence_{项目ID}。
    -- 2. 查询数据来源包含固定禁飞区表 wrj_jfq_dj，以及项目范围相交省份对应的试飞区表。
    -- 3. 源表字段可能不完全一致，下面通过 information_schema.columns 判断字段是否存在，缺失字段统一补 NULL。
    -- 4. 动态对象名统一使用 format('%I', ...) 拼接，避免表名、索引名等标识符注入风险。
    v_target_table text := 'gis_electric_fence_' || p_project_id;  -- 最终生成的项目电子围栏表名
    v_geom geometry;                                               -- 存储解析后的项目范围空间几何对象
    v_sql text := '';                                              -- 动态拼接的查询/插入SQL语句
    v_table_suffix text;                                           -- 循环中：省份试飞区表名后缀
    v_row_count BIGINT := 0;                                       -- 插入数据的总行数
    v_columns text[];                                              -- 存储源表的字段名数组
    v_start_time timestamptz := clock_timestamp();                  -- 函数开始时间，用于统一返回耗时
    v_log_sql text;                                               -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_project(%L, %L);',
        p_project_id, p_geom_json);

    -- =============================================
    -- 第一步：必填参数合法性校验
    -- =============================================
    -- 判断项目ID和GeoJSON是否为空
    IF p_project_id IS NULL OR p_project_id = '' OR p_geom_json IS NULL OR p_geom_json = '' THEN
        -- 为空则返回参数错误
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (400, format('项目ID或地理范围GeoJSON不能为空，执行时间 %s 秒',
            ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3)), v_log_sql);
        RETURN QUERY SELECT 400, format('项目ID或地理范围GeoJSON不能为空，执行时间 %s 秒',
            ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar, ''::varchar, 0::bigint;
        RETURN;
    END IF;

    -- =============================================
    -- 第二步：解析项目范围GeoJSON
    -- =============================================
    BEGIN
        -- 将GeoJSON字符串转为几何对象，并设置坐标系为WGS84(4326)
        v_geom := ST_SetSRID(ST_GeomFromGeoJSON(p_geom_json), 4326);
    -- 捕获GeoJSON解析异常
    EXCEPTION WHEN OTHERS THEN
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (400, format('GeoJSON格式错误：%s，执行时间 %s 秒',
            SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3)), v_log_sql);
        RETURN QUERY SELECT 400, format('GeoJSON格式错误：%s，执行时间 %s 秒',
            SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar, ''::varchar, 0::bigint;
        RETURN;
    END;

    -- =============================================
    -- 第三步：删除已存在的旧表
    -- =============================================
    -- 安全删除已存在的项目围栏表，避免冲突
    EXECUTE format('DROP TABLE IF EXISTS %I', v_target_table);

    -- =============================================
    -- 第四步：创建全新的项目电子围栏表
    -- =============================================
    -- 创建标准结构的电子围栏表
     -- 注意：geom统一使用4326坐标系；area保存基于geography计算的平方米面积。
    -- fence_type用于区分围栏来源类型：1=禁飞区，3=试飞区。
    EXECUTE format('
        CREATE TABLE %I (
            id             BIGSERIAL PRIMARY KEY,  -- 自增主键
            area_id        integer,                -- 区域ID
            name           varchar(254),           -- 名称
            lat            float8,                 -- 中心点纬度
            lng            float8,                 -- 中心点经度
            radius         float8,                 -- 半径
            fence_type     varchar(254),           -- 围栏类型（1=禁飞区,3=试飞区）
            level          float8,                 -- 等级
            color          varchar(254),           -- 颜色
            city           varchar(254),           -- 城市
            address        varchar(254),           -- 地址
            description    varchar(254),           -- 描述
            height         float8,                 -- 高度
            begin_at       float8,                 -- 开始时间
            end_at         float8,                 -- 结束时间
            create_time    timestamptz DEFAULT now(), -- 创建时间，默认当前时间
            area           numeric,                -- 面积
            geom           geometry(Geometry, 4326) -- 空间几何对象
        )', v_target_table);

    -- =============================================
    -- 第六步：获取禁飞区表字段
    -- =============================================
    -- 查询禁飞区表wrj_jfq_dj的所有字段名，存入数组（使用别名避免与输出列名冲突）
    SELECT array_agg(c.column_name) INTO v_columns
    FROM information_schema.columns c
    WHERE c.table_schema = 'public' AND c.table_name = 'wrj_jfq_dj';

    -- =============================================
    -- 第七步：拼接禁飞区查询SQL
    -- =============================================
    -- 动态拼接禁飞区查询SQL，兼容字段不存在自动补NULL
    -- 这里先生成基础SELECT，不立即执行；最终会作为INSERT INTO ... SELECT ...的一部分写入项目表。
    -- WHERE ST_Intersects(geom, $1) 中的 $1 由 EXECUTE ... USING v_geom 绑定，避免把GeoJSON文本直接拼进SQL。
    v_sql := format('
        SELECT
            gid::integer AS area_id,             -- 区域ID
            name,                                -- 名称
            ST_Y(ST_Centroid(geom)) AS lat,      -- 几何中心点纬度
            ST_X(ST_Centroid(geom)) AS lng,      -- 几何中心点经度
            %s AS radius,                        -- 半径（兼容字段）
            ''1'' AS fence_type,                 -- 围栏类型：1=禁飞区
            %s AS level,                         -- 等级（兼容字段）
            %s AS color,                         -- 颜色（兼容字段）
            %s AS city,                          -- 城市（兼容字段）
            %s AS address,                       -- 地址（兼容字段）
            %s AS description,                   -- 描述（兼容字段）
            %s AS height,                        -- 高度（兼容字段）
            %s AS begin_at,                      -- 开始时间（兼容字段）
            %s AS end_at,                        -- 结束时间（兼容字段）
            now() AS create_time,                -- 创建时间
            ST_Area(geom::geography) AS area,    -- 地理面积（平方米）
            geom                                 -- 空间几何
        FROM wrj_jfq_dj
        WHERE ST_Intersects(geom, $1)',          -- 空间相交筛选条件

        -- 判断字段是否存在，存在则取字段，不存在则置NULL
        CASE WHEN 'radius' = ANY(v_columns) THEN 'radius' ELSE 'NULL::float8' END,
        CASE WHEN 'level'   = ANY(v_columns) THEN '"level"' ELSE 'NULL::float8' END,
        CASE WHEN 'color'   = ANY(v_columns) THEN 'color' ELSE 'NULL::varchar(254)' END,
        CASE WHEN 'city'    = ANY(v_columns) THEN 'city' ELSE 'NULL::varchar(254)' END,
        CASE WHEN 'address' = ANY(v_columns) THEN 'address' ELSE 'NULL::varchar(254)' END,
        CASE WHEN 'descriptio' = ANY(v_columns) THEN 'descriptio'
             WHEN 'description' = ANY(v_columns) THEN 'description'
             ELSE 'NULL::varchar(254)' END,
        CASE WHEN 'height'   = ANY(v_columns) THEN 'height' ELSE 'NULL::float8' END,
        CASE WHEN 'begin_at' = ANY(v_columns) THEN 'begin_at' ELSE 'NULL::float8' END,
        CASE WHEN 'end_at'   = ANY(v_columns) THEN 'end_at' ELSE 'NULL::float8' END
    );

    -- =============================================
    -- 第八步：遍历省份试飞区表
    -- =============================================
    -- 循环查询与项目范围相交的省份，并获取对应的试飞区表名（使用别名避免歧义）
     -- jc_sheng.wrj_sfky_table保存省份试飞区表名；只处理与项目范围相交且表名非空的省份。
    FOR v_table_suffix IN
        SELECT DISTINCT s."wrj_sfky_table"
        FROM jc_sheng s
        WHERE ST_Intersects(s.geom, v_geom)
          AND s."wrj_sfky_table" IS NOT NULL AND s."wrj_sfky_table" != ''
    LOOP
        -- 获取当前试飞区表的所有字段
         -- 不同省份试飞区表结构可能不一致，因此每次循环都重新读取字段列表。
        SELECT array_agg(c.column_name) INTO v_columns
        FROM information_schema.columns c
        WHERE c.table_schema = 'public' AND c.table_name = v_table_suffix;

        -- 拼接UNION ALL，追加试飞区数据，fence_type=3
        -- 使用%I安全引用试飞区表名；空间筛选仍复用同一个$1项目范围几何。
        v_sql := v_sql || format('
            UNION ALL
            SELECT
                id::integer AS area_id,             -- 区域ID
                name,                                -- 名称
                ST_Y(ST_Centroid(geom)) AS lat,      -- 中心点纬度
                ST_X(ST_Centroid(geom)) AS lng,      -- 中心点经度
                %s AS radius,                        -- 半径（兼容字段）
                ''3'' AS fence_type,                 -- 围栏类型：3=试飞区
                %s AS level,                         -- 等级（兼容字段）
                %s AS color,                         -- 颜色（兼容字段）
                %s AS city,                          -- 城市（兼容字段）
                %s AS address,                       -- 地址（兼容字段）
                %s AS description,                   -- 描述（兼容字段）
                %s AS height,                        -- 高度（兼容字段）
                %s AS begin_at,                      -- 开始时间（兼容字段）
                %s AS end_at,                        -- 结束时间（兼容字段）
                now() AS create_time,                -- 创建时间
                ST_Area(geom::geography) AS area,    -- 面积
                geom                                 -- 空间几何
            FROM %I
            WHERE ST_Intersects(geom, $1)',         -- 相交筛选

            CASE WHEN 'radius' = ANY(v_columns) THEN 'radius' ELSE 'NULL::float8' END,
            CASE WHEN 'level'   = ANY(v_columns) THEN '"level"' ELSE 'NULL::float8' END,
            CASE WHEN 'color'   = ANY(v_columns) THEN 'color' ELSE 'NULL::varchar(254)' END,
            CASE WHEN 'city'    = ANY(v_columns) THEN 'city' ELSE 'NULL::varchar(254)' END,
            CASE WHEN 'address' = ANY(v_columns) THEN 'address' ELSE 'NULL::varchar(254)' END,
            CASE WHEN 'descriptio' = ANY(v_columns) THEN 'descriptio'
                 WHEN 'description' = ANY(v_columns) THEN 'description'
                 ELSE 'NULL::varchar(254)' END,
            CASE WHEN 'height'   = ANY(v_columns) THEN 'height' ELSE 'NULL::float8' END,
            CASE WHEN 'begin_at' = ANY(v_columns) THEN 'begin_at' ELSE 'NULL::float8' END,
            CASE WHEN 'end_at'   = ANY(v_columns) THEN 'end_at' ELSE 'NULL::float8' END,
            v_table_suffix
        );
    END LOOP;

    -- =============================================
    -- 第九步：执行插入数据
    -- =============================================
    -- 如果拼接的SQL不为空，则执行插入
    IF v_sql <> '' THEN
        -- 执行INSERT，把查询到的禁飞区+试飞区数据写入项目表
        EXECUTE format('
            INSERT INTO %I (
                area_id, name, lat, lng, radius, fence_type, level,
                color, city, address, description, height, begin_at, end_at, create_time, area, geom
            ) %s', v_target_table, v_sql
        ) USING v_geom;  -- 传入项目范围几何对象
        -- 获取实际插入的行数
        GET DIAGNOSTICS v_row_count = ROW_COUNT;
    END IF;

    IF v_row_count > 0 THEN
        -- 数据写入完成后再创建索引，兼顾建表速度和GeoServer/Cesium查询性能
        EXECUTE format(
            'CREATE INDEX %I ON %I USING GIST (geom) WHERE geom IS NOT NULL',
            'ix_' || v_target_table || '_geom',
            v_target_table
        );

        EXECUTE format(
            'CREATE INDEX %I ON %I (fence_type) WHERE geom IS NOT NULL',
            'ix_' || v_target_table || '_ft_nn',
            v_target_table
        );

        EXECUTE format('ANALYZE %I', v_target_table);
    END IF;

    -- =============================================
    -- 第十步：返回结果
    -- =============================================
    -- 根据插入行数返回成功或无数据
    IF v_row_count > 0 THEN
        RETURN QUERY SELECT 200, format('执行成功，电子围栏已生成，执行时间 %s 秒',
            ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar, v_target_table::varchar, v_row_count;
    ELSE
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (400, format('未查询到相交电子围栏数据，执行时间 %s 秒',
            ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3)), v_log_sql);
        RETURN QUERY SELECT 400, format('未查询到相交电子围栏数据，执行时间 %s 秒',
            ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar, v_target_table::varchar, 0::bigint;
    END IF;

-- =============================================
-- 异常捕获
-- =============================================
-- 捕获所有未处理异常，返回500错误
EXCEPTION WHEN OTHERS THEN
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (500, format('执行异常：%s，执行时间 %s 秒',
        SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3)), v_log_sql);
    -- 兜底异常处理：保留数据库原始错误信息，便于接口调用方定位失败原因。
    RETURN QUERY SELECT 500, format('执行异常：%s，执行时间 %s 秒',
        SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar, v_target_table::varchar, 0::bigint;
END;
$$;
COMMENT ON FUNCTION gis_electric_fence_project(text, text) IS '生成项目电子围栏表';

------------------------------------------------------------------------------geoserver 自动调用项目服务------------------------------------------------------
-- =============================================
-- 函数名称：gis_get_electric_fence_project
-- 函数功能：根据项目ID + 围栏类型，动态查询项目电子围栏数据
-- 函数描述：
--    1. 传入 1          → 返回类型 1
--    2. 传入 1;2        → 返回类型 1、2
--    3. 传入 1,2,3      → 返回类型 1、2、3
--    4. 传入 NULL / -1 / 空串 → 不返回任何数据
--    5. 动态表名，安全防SQL注入
-- 适用场景：GeoServer 调用、项目独立电子围栏表
-- 依赖插件：PostGIS
-- =============================================

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_get_electric_fence_project');

-- 创建函数
-- =============================================================================
-- 函数介绍：gis_get_electric_fence_project
-- 主要作用：按项目ID动态读取项目专属电子围栏表，并按围栏类型过滤返回。
-- 入参说明：p_project_id 为项目ID；p_fence_type 支持单个类型、分号或逗号分隔的类型列表。
-- 返回说明：返回围栏属性、面积和geom几何数据，供GeoServer或业务接口直接查询展示。
-- 注意事项：函数会动态拼接表名，项目围栏表不存在或类型为空时不返回数据。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_get_electric_fence_project(
    p_project_id TEXT,                                   -- 入参1：项目ID，用于拼接动态表名
    p_fence_type TEXT DEFAULT NULL                       -- 入参2：围栏类型，支持1/1;2/1,2,3格式
)
RETURNS TABLE (                                          -- 定义返回结果字段
    area_id        INTEGER,                              -- 区域ID
    name           VARCHAR(254),                         -- 围栏名称
    lat            FLOAT8,                               -- 纬度
    lng            FLOAT8,                               -- 经度
    radius         FLOAT8,                               -- 半径
    fence_type     VARCHAR(254),                         -- 围栏类型（1/2/3）
    level          FLOAT8,                               --  层级
    color          VARCHAR(254),                         -- 颜色
    city           VARCHAR(254),                         -- 城市
    address        VARCHAR(254),                         -- 详细地址
    description    VARCHAR(254),                         -- 描述
    height         FLOAT8,                               -- 高度
    begin_at       FLOAT8,                               -- 生效开始时间
    end_at         FLOAT8,                               -- 生效结束时间
    create_time    TIMESTAMPTZ,                          -- 创建时间
    area           NUMERIC,                              -- 面积
    geom           GEOMETRY                              -- 空间几何数据（PostGIS）
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    -- 定义变量：动态拼接项目专属电子围栏表名
    v_table_name TEXT := 'gis_electric_fence_' || p_project_id; 
    v_types TEXT[];
    -- 定义变量：存储最终要执行的动态SQL语句
    v_sql TEXT;                                                 
BEGIN
    IF p_project_id IS NULL OR btrim(p_project_id) = '' THEN
        RETURN;
    END IF;

    -- =============================================
    -- 核心判断逻辑：
    -- 如果传入的围栏类型是 NULL / 空字符串 / -1
    -- 直接返回空结果，不查询数据库
    -- =============================================
    IF p_fence_type IS NULL OR btrim(p_fence_type) = '' OR btrim(p_fence_type) = '-1' THEN
        RETURN;  -- 直接返回，无数据
    END IF;

    v_types := regexp_split_to_array(
        regexp_replace(btrim(p_fence_type), '\s+', '', 'g'),
        '[,;]+'
    );

    -- =============================================
    -- 正常业务逻辑：
    -- 拼接动态SQL，支持多类型筛选（支持 , 和 ; 分隔）
    -- 使用 format 防止SQL注入，保证安全
    -- =============================================
    v_sql := format($f$
        SELECT
            area_id, name, lat, lng, radius, fence_type, level, color,
            city, address, description, height, begin_at, end_at,
            create_time, area, geom
        FROM %I
        WHERE fence_type = ANY ($1)
          AND geom IS NOT NULL
    $f$, v_table_name);

    -- 执行动态SQL并返回查询结果
    RETURN QUERY EXECUTE v_sql USING v_types;
END;
$$;
COMMENT ON FUNCTION gis_get_electric_fence_project(text, text) IS '查询项目电子围栏数据';


-- =============================================================================
-- 2.2电子围栏校验-函数..sql
--   gis_check_electric_fence                校验电子围栏冲突
--   gis_electric_fence_check_point          检测航点落入围栏
--   gis_electric_fence_check_line           检测航线穿越围栏
--   gis_electric_fence_buffer               生成电子围栏缓冲区
--   gis_electric_fence_check_point_buffer   检测航点缓冲区冲突
--   gis_electric_fence_check_line_buffer    检测航线缓冲区冲突
--
-- =============================================================================

-- =============================================
-- 函数名称gis_check_electric_fence
-- 函数功能电子围栏空间冲突校验（禁飞区/管控区试飞区互斥规则校验）
-- 函数描述1. 接收项目ID、围栏类型、坐标GeoJSON三个独立参数
--            2. 自动标准化几何数据（2D、修复、设置坐标系
--            3. 按类型执行空间冲突校验：
--               - 禁飞区1)：无需校验，直接通过
--               - 管控区2)：禁止与禁飞区1)相交/包含
--               - 试飞区3)：禁止与禁飞区1)、管控区(2)相交/包含
--            4. 支持项目专属围栏+ 公共围栏表双重校
--            5. 返回冲突详情：类型、表名、几何、提示文案
-- 函数说明依赖PostGIS空间扩展，坐标系使用WGS84(4326)
-- 参数说明
--   p_project_id    varchar     项目ID（可选），用于区分项目专属围栏表
--   p_fence_type    text        围栏类型=禁飞区，2=管控区，3=试飞区
--   p_lng_lat_alt   text        坐标GeoJSON字符串，支持Feature或直接Geometry
-- 返回值： 标准TABLE结构
--   code               integer     返回码：200成功00参数错误00空间冲突
--   table_name         text        冲突对应的表名
--   orig_fence_type    text        传入的原始围栏类型
--   conflict_fence_type text       冲突的围栏类型数字)
--   msg                text        详细提示信息（区分相包含 + 中文名称
--   new_geom           text        标准化后的新围栏几何JSON
--   conflict_geom      text        冲突围栏的几何JSON
-- 适用场景新增/编辑电子围栏前的空间合规性校验，防止区域重叠冲突
-- =============================================
-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_check_electric_fence');

-- =============================================================================
-- 函数介绍：gis_check_electric_fence
-- 主要作用：校验新建或编辑电子围栏时，是否与已有围栏存在空间冲突或规则冲突
-- 入参说明：p_project_id 为项目ID；p_geom_json 为待校验围栏GeoJSON；p_fence_type 为围栏类型
-- 返回说明：返回状态码、提示信息以及冲突明细，供保存围栏前进行业务拦截
-- 注意事项：依赖PostGIS空间判断；校验逻辑会结合全局围栏和项目专属围栏数据
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_check_electric_fence(
  IN p_project_id varchar,      -- 入参1：项目ID（可选），用于区分项目专属围栏表
  IN p_fence_type text,         -- 入参2：围栏类型，1=禁飞区，2=管控区，3=试飞区
  IN p_lng_lat_alt text         -- 入参3：坐标GeoJSON字符串，支持Feature或直接Geometry
)
RETURNS TABLE (
  code integer,           -- 返回码：200成功00参数错误00空间冲突
  table_name text,        -- 冲突对应的表名
  orig_fence_type text,   -- 传入的原始围栏类型
  conflict_fence_type text,-- 冲突的围栏类型数字)
  msg text,               -- 详细提示信息（区分相包含 + 中文名称
  new_geom text,          -- 标准化后的新围栏几何JSON
  conflict_geom text      -- 冲突围栏的几何JSON
)
LANGUAGE plpgsql
AS $$
DECLARE
  v_fence_type text;          -- 处理后的围栏类型(数字)
  v_orig_fence_type text;     -- 原始传入的围栏类型数字)
  v_geojson_str text;         -- 传入的坐标GeoJSON字符串
  v_new_geom geometry;        -- 标准化处理后的几何对
  v_geojson_json jsonb;        -- lngLatAlt解析后的JSON对象，兼容Feature和直接Geometry
  v_new_geom_json text;       -- 新几何的GeoJSON格式字符串
  v_sql text;                 -- 动态执行SQL语句
  v_has_conflict boolean;     -- 是否存在冲突标记
  v_is_contains boolean;     -- 是否为包含关系标记
  v_conflict_name text;       -- 冲突围栏中文名称
  v_start_time timestamptz := clock_timestamp(); -- 函数开始时间，用于统一返回耗时
  v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_check_electric_fence(%L, %L, %L);',
        p_project_id, p_fence_type, p_lng_lat_alt);

  -- 初始化冲突标记：默认无冲突
  v_has_conflict := false;

  -- ===================== 1. 解析入参 =====================
  -- 围栏类型从第二个参数直接传入，去除前后空格后参与规则判断
  v_orig_fence_type := trim(p_fence_type);
  v_fence_type := v_orig_fence_type;
  -- 坐标GeoJSON从第三个参数直接传入，兼容Feature和直接Geometry
  v_geojson_str := trim(p_lng_lat_alt);

  -- ===================== 2. 基础参数非空校验 =====================
  -- 校验围栏类型是否为空
  IF v_fence_type IS NULL OR v_fence_type = '' THEN
    code := 400;                     -- 参数错误
    table_name := '';                -- 无表名
    orig_fence_type := v_orig_fence_type; -- 原始围栏类型
    conflict_fence_type := '';       -- 无冲突类型
    msg := format('参数校验失败：围栏类型不能为空，执行时间 %s 秒',
      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3)); -- 错误提示
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (code,msg,v_log_sql);
    new_geom := null;                -- 无几何数据
    conflict_geom := null;           -- 无冲突几何
    RETURN NEXT;  -- 返回结果
    RETURN;       -- 终止函数执行
  END IF;

  -- 校验坐标信息是否为空
  IF v_geojson_str IS NULL OR v_geojson_str = '' THEN
    code := 400;
    table_name := '';
    orig_fence_type := v_orig_fence_type;
    conflict_fence_type := '';
    msg := format('参数校验失败：坐标信息不能为空，执行时间 %s 秒',
      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (code,        msg,        v_log_sql
    );
    new_geom := null;
    conflict_geom := null;
    RETURN NEXT;
    RETURN;
  END IF;

  -- ===================== 3. 几何标准化处=====================
  -- 将GeoJSON字符串转为JSON对象
  -- lngLatAlt可能传Feature，也可能直接传Polygon/MultiPolygon等Geometry；这里统一兼容两种格式
  v_geojson_json := v_geojson_str::jsonb;
  IF v_geojson_json ->> 'type' = 'Feature' THEN
    -- Feature格式：几何数据位于geometry节点
    v_new_geom := ST_GeomFromGeoJSON(v_geojson_json ->> 'geometry');
  ELSE
    -- Geometry格式：整个JSON就是几何对象
    v_new_geom := ST_GeomFromGeoJSON(v_geojson_json::text);
  END IF;
  -- 强制转为2D几何（剔除高度值） + 自动修复非法几何（自相交、不闭合等）
  v_new_geom := ST_MakeValid(ST_Force2D(v_new_geom));
  -- 设置坐标系为EPSG:4326（WGS84经纬度坐标系
  v_new_geom := ST_SetSRID(v_new_geom, 4326);
  -- 将标准化处理后的几何对象转回GeoJSON字符串，用于返回
  v_new_geom_json := ST_AsGeoJSON(v_new_geom);

  -- ===================== 4. 禁飞区1) 直接校验通过 =====================
  -- 业务规则：禁飞区为最高优先级，无需检测任何空间冲突
  IF v_fence_type = '1' THEN
    code := 200;
    table_name := '';
    orig_fence_type := v_orig_fence_type;
    conflict_fence_type := '';
    msg := format('校验成功：禁飞区无需检测空间冲突，执行时间 %s 秒',
      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    new_geom := v_new_geom_json;
    conflict_geom := null;
    RETURN NEXT;
    RETURN;
  END IF;

  -- ===================== 5. 试飞区3) 冲突校验 =====================
  -- 业务规则：试飞区禁止与禁飞区(1)、管控区(2)发生相交/包含关系
  IF v_fence_type = '3' THEN
    -- 拼接动态SQL：优先查询项目专属围栏表
    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
      -- 使用formatL返回表名文本I安全引用动态项目表名
      -- 项目专属表字段名fence_type，用于判断冲突围栏类型
      v_sql := format(
        'SELECT %L, fence_type, ST_AsGeoJSON(geom),
         ST_Contains(ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326), $1) as is_contains
         FROM %I
         WHERE fence_type IN (''1'',''2'')
         AND ST_Intersects($1, ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326))',
        'gis_electric_fence_' || trim(p_project_id),
        'gis_electric_fence_' || trim(p_project_id)
      );
    ELSE
      -- 无项目ID时，查询公共电子围栏
      -- 公共项目围栏表同样使fence_type 字段
      v_sql := 'SELECT ''gis_electric_fence'', fence_type, ST_AsGeoJSON(geom),
                ST_Contains(ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326), $1) as is_contains
                FROM gis_electric_fence
                WHERE fence_type IN (''1'',''2'')
                AND ST_Intersects($1, ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326))';
    END IF;

    -- 遍历冲突查询结果，逐条返回冲突信息
    FOR table_name, conflict_fence_type, conflict_geom, v_is_contains IN EXECUTE v_sql USING v_new_geom
    LOOP
      -- 标记存在空间冲突
      v_has_conflict := true;
      code := 200;                              -- 空间冲突属于正常校验结果
      orig_fence_type := v_orig_fence_type;      -- 原始围栏类型

      -- 围栏类型数字映射为中文名
      CASE conflict_fence_type
        WHEN '1' THEN v_conflict_name := '禁飞区';
        WHEN '2' THEN v_conflict_name := '管控区';
        ELSE v_conflict_name := '未知类型围栏';
      END CASE;

      -- 根据空间关系（包相交）返回不同提示文案
      IF v_is_contains THEN
        msg := format('试飞区与%s发生包含冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      ELSE
        msg := format('试飞区与%s发生相交冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      END IF;
      new_geom := v_new_geom_json;  -- 返回标准化后的新几何
      RETURN NEXT;                  -- 返回当前冲突
    END LOOP;

    -- 遍历公共围栏bo_electric_fence，继续校验冲突
    v_sql := 'SELECT ''bo_electric_fence'', fence_type, ST_AsGeoJSON(geom),
              ST_Contains(ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326), $1) as is_contains
              FROM bo_electric_fence
              WHERE fence_type IN (''1'',''2'') AND project_id = $2
              AND del_flag = false AND status = ''1''
              AND ST_Intersects($1, ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326))';
    FOR table_name, conflict_fence_type, conflict_geom, v_is_contains IN EXECUTE v_sql USING v_new_geom, p_project_id
    LOOP
      v_has_conflict := true;
      code := 200;
      orig_fence_type := v_orig_fence_type;

      -- 冲突类型转中
      CASE conflict_fence_type
        WHEN '1' THEN v_conflict_name := '禁飞区';
        WHEN '2' THEN v_conflict_name := '管控区';
        ELSE v_conflict_name := '未知类型围栏';
      END CASE;

      -- 返回冲突提示信息
      IF v_is_contains THEN
        msg := format('试飞区与%s发生包含冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      ELSE
        msg := format('试飞区与%s发生相交冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      END IF;
      new_geom := v_new_geom_json;
      RETURN NEXT;
    END LOOP;

  -- ===================== 6. 管控区2) 冲突校验 =====================
  -- 业务规则：管控区禁止与禁飞区(1)发生相交/包含关系
  ELSIF v_fence_type = '2' THEN
    -- 拼接动态SQL：优先查询项目专属围栏表
    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
      -- 项目专属表名动态生成，必须使用%I作为标识符引用；表内围栏类型字段fence_type
      v_sql := format(
        'SELECT %L, fence_type, ST_AsGeoJSON(geom),
         ST_Contains(ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326), $1) as is_contains
         FROM %I
         WHERE fence_type = ''1''
         AND ST_Intersects($1, ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326))',
        'gis_electric_fence_' || trim(p_project_id),
        'gis_electric_fence_' || trim(p_project_id)
      );
    ELSE
      -- 无项目ID时查询公共围栏表
      v_sql := 'SELECT ''gis_electric_fence'', fence_type, ST_AsGeoJSON(geom),
                ST_Contains(ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326), $1) as is_contains
                FROM gis_electric_fence
                WHERE fence_type = ''1''
                AND ST_Intersects($1, ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326))';
    END IF;

    -- 遍历项目围栏表冲突数据
    FOR table_name, conflict_fence_type, conflict_geom, v_is_contains IN EXECUTE v_sql USING v_new_geom
    LOOP
      v_has_conflict := true;
      code := 200;
      orig_fence_type := v_orig_fence_type;
      v_conflict_name := '禁飞区'; -- 管控区只校验禁飞区，固定名称

      -- 根据空间关系返回提示
      IF v_is_contains THEN
        msg := format('管控区与%s发生包含冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      ELSE
        msg := format('管控区与%s发生相交冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      END IF;
      new_geom := v_new_geom_json;
      RETURN NEXT;
    END LOOP;

    -- 校验公共bo_electric_fence 中的禁飞区冲突
    v_sql := 'SELECT ''bo_electric_fence'', fence_type, ST_AsGeoJSON(geom),
              ST_Contains(ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326), $1) as is_contains
              FROM bo_electric_fence
              WHERE fence_type = ''1'' AND project_id = $2
              AND del_flag = false AND status = ''1''
              AND ST_Intersects($1, ST_SetSRID(ST_MakeValid(ST_Force2D(geom)), 4326))';
    FOR table_name, conflict_fence_type, conflict_geom, v_is_contains IN EXECUTE v_sql USING v_new_geom, p_project_id
    LOOP
      v_has_conflict := true;
      code := 200;
      orig_fence_type := v_orig_fence_type;
      v_conflict_name := '禁飞区';

      -- 返回冲突提示
      IF v_is_contains THEN
        msg := format('管控区与%s发生包含冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      ELSE
        msg := format('管控区与%s发生相交冲突，执行时间 %s 秒',
          v_conflict_name, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
      END IF;
      new_geom := v_new_geom_json;
      RETURN NEXT;
    END LOOP;

  -- ===================== 7. 未知围栏类型 =====================
  -- 传入的围栏类型不/2/3，返回参数错
  ELSE
    code := 400;
    table_name := '';
    orig_fence_type := v_orig_fence_type;
    conflict_fence_type := '';
    msg := format('参数校验失败：不支持的围栏类型，执行时间 %s 秒',
      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (
        code,
        msg,
        v_log_sql
    );
    new_geom := null;
    conflict_geom := null;
    RETURN NEXT;
    RETURN;
  END IF;

  -- ===================== 8. 无冲突返回成功=====================
  -- 所有校验规则执行完成，未发现任何空间冲突
  IF NOT v_has_conflict THEN
    code := 200;
    table_name := '';
    orig_fence_type := v_orig_fence_type;
    conflict_fence_type := '';
    msg := format('校验成功：未检测到相交、包含空间冲突，执行时间 %s 秒',
      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    new_geom := v_new_geom_json;
    conflict_geom := null;
    RETURN NEXT;
  END IF;

-- ===================== 全局异常捕获 =====================
-- 捕获函数执行过程中所有未知异常，返回标准化错误信息
EXCEPTION WHEN OTHERS THEN
  code := 500;
  table_name := '';
  orig_fence_type := v_orig_fence_type;
  conflict_fence_type := '';
  msg := format('系统异常：%s | 错误码：%s，执行时间 %s 秒',
    SQLERRM, SQLSTATE, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
  INSERT INTO public.gis_error_log(code, msg, sqlstring)
  VALUES (
      code,
      msg,
      v_log_sql
  );
  new_geom := null;
  conflict_geom := null;
  RETURN NEXT;
END;
$$;
COMMENT ON FUNCTION gis_check_electric_fence(varchar, text, text) IS '校验电子围栏冲突';


-- =============================================================================
-- 电子围栏线判断、点判断、缓冲、点缓冲判断、线缓冲判断
-- =============================================================================

-- ====================================================================
-- 函数名称gis_electric_fence_check_point
-- 函数功能无人机定位点 3D 电子围栏碰撞检测（无缓冲，纯原始围栏判断）
-- 函数描述1. 传入 项目ID + 点的GeoJSON（支持Feature和Point格式
--            2. 高度=0（默认）：仅执行2D平面包含判断
--            3. 禁飞区和管控区统一按同一套平面+高度逻辑校验
--            4. 项目ID不为空时查询 gis_electric_fence_{project_id} 表（注意表不存在的情况）
--            5. 项目ID为空时查bo_electric_fence
--            6. 只查询禁飞区、启用状态、未删除的有效围栏
--            7. 返回标准格式结果集，与航线检测函数完全通用，前端可直接渲染
-- 函数说明依赖PostGIS空间扩展，坐标系默认使用WGS84(4326)
-- 参数说明
--   p_project_id    text            输入参数：项目ID（可选），为空则查询公共
--   p_point_geojson text            输入参数：点的GeoJSON字符串（必填，支持Feature和Point格式
--   p_is_3d         boolean         输入参数：是否启用高度判断，默认true；false时只做二维平面判断
-- 返回值： 标准TABLE结构，与航线检测函数完全一
--   code      integer    状态码00=执行成功 400=参数错误 500=执行异常
--   msg       varchar    状态描述信息
--   geom      geometry   本次校验的输入点几何
--   electric_id varchar(32) 命中的围栏ID
--   electric_geom geometry  命中的围栏数据库原始几何
--   electric_geojson json   命中的围栏GeoJSON
-- 函数注意
--   1. bo_electric_fence 必须存在，且包含字段：id, geom, height, del_flag, fence_type, status
--   2. 2D判断使用 ST_Covers，3D判断结合平面+高度区间校验，边界点算命中
--   3. 围栏高度为空或0时按无限高度处理，仅判断平面是否在围栏内
-- 适用场景无人机实时定位是否闯入禁飞区/管控区
-- ====================================================================================

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_electric_fence_check_point');

-- 创建函数
-- =============================================================================
-- 函数介绍：gis_electric_fence_check_point
-- 主要作用：判断单个航点是否落入启用中的禁飞区、管控区等电子围栏范围栏
-- 入参说明：p_point_json 为航点Point/PointZ GeoJSON；p_project_id 用于限定项目围栏范围栏；p_is_3d 控制二维/三维判断
-- 返回说明：返回命中状态、围栏类型、围栏名称和提示信息，供航点合法性校验使用
-- 注意事项：点位坐标默认WGS84；高度规则需结合围栏数据中的高度字段判断
-- =============================================================================
CREATE OR REPLACE FUNCTION public.gis_electric_fence_check_point(
    p_project_id text,
    p_point_geojson text,
    p_is_3d boolean DEFAULT true
)
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    table_name varchar,
    geom geometry,
    electric_id varchar(32),
    fence_type varchar,
    electric_name varchar,
    electric_geom geometry,
    electric_geojson json
)
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
    v_point geometry;          -- 存储生成的空间点几何对象
    v_geojson_json jsonb;      -- 解析后的GeoJSON对象
    v_z double precision;      -- 高度
    v_table_name text;         -- 动态表名
    v_sql text;                -- 动态SQL语句
    v_table_exists boolean;    -- 表是否存
    v_found boolean;           -- 是否找到匹配的围栏
    v_start_time timestamptz := clock_timestamp(); -- 函数开始时间，用于统一返回耗时
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_check_point(%L, %L, %L);',
        p_project_id, p_point_geojson, p_is_3d);

    -- =============================================
    -- 00 参数错误】第一步：校验点GeoJSON是否为空
    -- =============================================
    IF p_point_geojson IS NULL OR p_point_geojson = '' THEN
        code := 400;
        msg := format('点参数为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'p_outer'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    -- =============================================
    -- 解析GeoJSON字符串
    -- =============================================
    BEGIN
        v_geojson_json := p_point_geojson::jsonb;
    EXCEPTION
        WHEN OTHERS THEN
            code := 400;
            msg := format('点的GeoJSON格式错误，执行时间 %s 秒',
                    ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            INSERT INTO public.gis_error_log(code, msg, sqlstring)
            VALUES (
                code,
                msg,
                v_log_sql
            );

            RETURN QUERY SELECT
                code, msg::varchar,
                false, 'p_outer'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
            RETURN;
    END;

    -- =============================================
    -- 从GeoJSON中提取点几何和高
    -- =============================================
    BEGIN
        IF jsonb_typeof(v_geojson_json) = 'array' THEN
            -- Support coordinate array input: [lng, lat, alt] or [[lng, lat, alt], ...].
            IF jsonb_array_length(v_geojson_json) = 0 THEN
                RAISE EXCEPTION 'Point coordinate array cannot be empty';
            END IF;

            IF jsonb_typeof(v_geojson_json -> 0) = 'array' THEN
                IF EXISTS (
                    SELECT 1
                    FROM jsonb_array_elements(v_geojson_json) AS p(pt)
                    WHERE jsonb_typeof(p.pt) <> 'array'
                       OR jsonb_array_length(p.pt) < 2
                ) THEN
                    RAISE EXCEPTION 'Each point coordinate requires at least lng and lat';
                END IF;

                SELECT ST_Multi(ST_Collect(
                    ST_MakePoint(
                        (p.pt ->> 0)::double precision,
                        (p.pt ->> 1)::double precision,
                        COALESCE((p.pt ->> 2)::double precision, 0)
                    )
                    ORDER BY p.ord
                ))
                INTO v_point
                FROM jsonb_array_elements(v_geojson_json) WITH ORDINALITY AS p(pt, ord);
                v_z := 0;
            ELSE
                IF jsonb_array_length(v_geojson_json) < 2 THEN
                    RAISE EXCEPTION 'Point coordinate array requires at least lng and lat';
                END IF;

                v_point := ST_MakePoint(
                    (v_geojson_json ->> 0)::double precision,
                    (v_geojson_json ->> 1)::double precision,
                    COALESCE((v_geojson_json ->> 2)::double precision, 0)
                );
                v_z := COALESCE((v_geojson_json ->> 2)::double precision, 0);
            END IF;
        ELSIF v_geojson_json ->> 'type' = 'FeatureCollection' THEN
            IF jsonb_typeof(v_geojson_json -> 'features') <> 'array'
               OR jsonb_array_length(v_geojson_json -> 'features') = 0 THEN
                RAISE EXCEPTION 'FeatureCollection requires non-empty features';
            END IF;

            SELECT ST_Multi(ST_Collect(
                ST_GeomFromGeoJSON(f.feature ->> 'geometry')
                ORDER BY f.ord
            ))
            INTO v_point
            FROM jsonb_array_elements(v_geojson_json -> 'features') WITH ORDINALITY AS f(feature, ord)
            WHERE f.feature -> 'geometry' IS NOT NULL;
            v_z := 0;
        ELSIF v_geojson_json ->> 'type' = 'Feature' THEN
            -- Feature格式
            v_point := ST_GeomFromGeoJSON(v_geojson_json ->> 'geometry');
            -- 尝试从Feature的properties或几何的Z坐标获取高度
            v_z := COALESCE(
                (v_geojson_json -> 'properties' ->> 'z')::double precision,
                (v_geojson_json -> 'properties' ->> 'height')::double precision,
                CASE WHEN ST_GeometryType(v_point) = 'ST_Point' THEN ST_Z(v_point) END,
                0
            );
        ELSE
            -- 直接Geometry格式
            v_point := ST_GeomFromGeoJSON(v_geojson_json::text);
            v_z := COALESCE(
                CASE WHEN ST_GeometryType(v_point) = 'ST_Point' THEN ST_Z(v_point) END,
                0
            );
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            code := 400;
            msg := format('点的GeoJSON解析失败，执行时间 %s 秒',
                    ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            INSERT INTO public.gis_error_log(code, msg, sqlstring)
            VALUES (
                code,
                msg,
                v_log_sql
            );

            RETURN QUERY SELECT
                code, msg::varchar,
                false, 'p_outer'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
            RETURN;
    END;

    -- =============================================
    -- 校验点类型
    -- =============================================
    IF ST_GeometryType(v_point) NOT IN ('ST_Point', 'ST_MultiPoint') THEN
        code := 400;
        msg := format('GeoJSON必须是Point类型，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'p_outer'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    -- =============================================
    -- 标准化几何（设置坐标系），保留输入高度Z
    -- =============================================
    IF ST_CoordDim(v_point) < 3 AND v_z > 0 THEN
        v_point := ST_Force3DZ(v_point, v_z);
    END IF;
    v_point := ST_SetSRID(v_point, 4326);

    -- =============================================
    -- 构建动态表名和SQL
    -- =============================================
    v_found := false;

    -- 构建最终的查询SQL
    v_sql := '';

    IF p_project_id IS NOT NULL AND p_project_id <> '' THEN
        -- 有项目ID，先检查项目表是否存在
        v_table_name := 'gis_electric_fence_' || p_project_id;

        -- 检查表是否存在
        SELECT EXISTS (
            SELECT 1 FROM information_schema.tables t
            WHERE t.table_schema = 'public'
            AND t.table_name = v_table_name
        ) INTO v_table_exists;

        IF v_table_exists THEN
            -- 项目表存在，使用UNION ALL连接项目表和公共
            v_sql := format('
                WITH input_points AS (
                    SELECT d.path, d.geom AS geom
                    FROM ST_Dump($1) AS d
                )
                SELECT
                    200 AS code,
                    CASE
                        WHEN hit.id IS NULL THEN format(''当前位置不在禁飞区/管控区内，check_type=p_outer(点在外部)，执行时间 %%s 秒'', ROUND(EXTRACT(epoch FROM clock_timestamp() - $3)::numeric, 3))
                        ELSE format(''当前位置在%%s内，check_type=p_inner(点在内部)，执行时间 %%s 秒'', CASE hit.fence_type WHEN ''1'' THEN ''禁飞区'' WHEN ''2'' THEN ''管控区'' ELSE ''电子围栏'' END, ROUND(EXTRACT(epoch FROM clock_timestamp() - $3)::numeric, 3))
                    END::varchar AS msg,
                    (hit.id IS NOT NULL) AS ischeck,
                    CASE WHEN hit.id IS NULL THEN ''p_outer'' ELSE ''p_inner'' END::varchar AS check_type,
                    COALESCE(hit.table_name, '''')::varchar AS table_name,
                    ip.geom,
                    hit.id::varchar(32) AS electric_id,
                    hit.fence_type::varchar AS fence_type,
                    hit.electric_name::varchar AS electric_name,
                    hit.geom AS electric_geom,
                    hit.geom_geojson AS electric_geojson
                FROM input_points ip
                LEFT JOIN LATERAL (
                    SELECT h.table_name, h.id, h.fence_type, h.electric_name, h.geom, h.geom_geojson
                    FROM (
                        SELECT
                            %L::varchar AS table_name,
                            f.id::varchar(32) AS id,
                            f.fence_type::varchar AS fence_type,
                            f.name::varchar AS electric_name,
                            f.geom AS geom,
                            ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson,
                            1 AS priority
                        FROM %I f
                        WHERE f.fence_type IN (''1'',''2'')
                          AND ST_Intersects(ST_SetSRID(f.geom, 4326), ip.geom)
                          AND (
                              NOT $4
                              OR
                              COALESCE(ST_Z(ip.geom), 0) = 0
                              OR COALESCE(f.height, 0) = 0
                              OR
                              (COALESCE(ST_Z(ip.geom), 0) > 0 AND COALESCE(ST_Z(ip.geom), 0) <= f.height)
                          )
                        UNION ALL
                        SELECT
                            ''bo_electric_fence''::varchar AS table_name,
                            f.id::varchar(32) AS id,
                            f.fence_type::varchar AS fence_type,
                            f.name::varchar AS electric_name,
                            f.geom AS geom,
                            ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson,
                            2 AS priority
                        FROM bo_electric_fence f
                        WHERE f.fence_type IN (''1'',''2'')
                          AND f.status = ''1''
                          AND f.del_flag = false
                          AND f.use_enabled = true
                          AND f.project_id::text = btrim($2)
                          AND ST_Intersects(ST_SetSRID(f.geom, 4326), ip.geom)
                          AND (
                              NOT $4
                              OR
                              COALESCE(ST_Z(ip.geom), 0) = 0
                              OR COALESCE(f.height, 0) = 0
                              OR
                              (COALESCE(ST_Z(ip.geom), 0) > 0 AND COALESCE(ST_Z(ip.geom), 0) <= f.height)
                          )
                    ) h
                    ORDER BY CASE h.fence_type WHEN ''1'' THEN 1 WHEN ''2'' THEN 2 ELSE 9 END,
                             h.priority,
                             h.id
                    LIMIT 1
                ) hit ON true
                ORDER BY ip.path',
                v_table_name,
                v_table_name
            );
        ELSE
            -- 项目表不存在，只查询公共
            v_sql := '
                WITH input_points AS (
                    SELECT d.path, d.geom AS geom
                    FROM ST_Dump($1) AS d
                )
                SELECT
                    200 AS code,
                    CASE
                        WHEN hit.id IS NULL THEN format(''当前位置不在禁飞区/管控区内，check_type=p_outer(点在外部)，执行时间 %s 秒'', ROUND(EXTRACT(epoch FROM clock_timestamp() - $3)::numeric, 3))
                        ELSE format(''当前位置在%s内，check_type=p_inner(点在内部)，执行时间 %s 秒'', CASE hit.fence_type WHEN ''1'' THEN ''禁飞区'' WHEN ''2'' THEN ''管控区'' ELSE ''电子围栏'' END, ROUND(EXTRACT(epoch FROM clock_timestamp() - $3)::numeric, 3))
                    END::varchar AS msg,
                    (hit.id IS NOT NULL) AS ischeck,
                    CASE WHEN hit.id IS NULL THEN ''p_outer'' ELSE ''p_inner'' END::varchar AS check_type,
                    COALESCE(hit.table_name, '''')::varchar AS table_name,
                    ip.geom,
                    hit.id::varchar(32) AS electric_id,
                    hit.fence_type::varchar AS fence_type,
                    hit.electric_name::varchar AS electric_name,
                    hit.geom AS electric_geom,
                    hit.geom_geojson AS electric_geojson
                FROM input_points ip
                LEFT JOIN LATERAL (
                    SELECT
                        ''bo_electric_fence''::varchar AS table_name,
                        f.id::varchar(32) AS id,
                        f.fence_type::varchar AS fence_type,
                        f.name::varchar AS electric_name,
                        f.geom AS geom,
                        ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson
                    FROM bo_electric_fence f
                    WHERE f.fence_type IN (''1'',''2'')
                      AND f.status = ''1''
                      AND f.del_flag = false
                      AND f.use_enabled = true
                      AND f.project_id::text = btrim($2)
                      AND ST_Intersects(ST_SetSRID(f.geom, 4326), ip.geom)
                      AND (
                          NOT $4
                          OR
                          COALESCE(ST_Z(ip.geom), 0) = 0
                          OR COALESCE(f.height, 0) = 0
                          OR
                          (COALESCE(ST_Z(ip.geom), 0) > 0 AND COALESCE(ST_Z(ip.geom), 0) <= f.height)
                      )
                    ORDER BY CASE f.fence_type WHEN ''1'' THEN 1 WHEN ''2'' THEN 2 ELSE 9 END,
                             f.id
                    LIMIT 1
                ) hit ON true
                ORDER BY ip.path';
        END IF;

        -- 执行统一的查
        RETURN QUERY EXECUTE v_sql USING v_point, p_project_id, v_start_time, p_is_3d;

        -- 检查是否找到结果
        IF FOUND THEN
            v_found := true;
        END IF;
    ELSE
        -- 没有项目ID，只查询公共
        RETURN QUERY
        SELECT
            200 AS code,
            CASE
                WHEN hit.id IS NULL THEN format('当前位置不在禁飞区/管控区内，check_type=p_outer(点在外部)，执行时间 %s 秒',
                    ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
                ELSE format('当前位置在%s内，check_type=p_inner(点在内部)，执行时间 %s 秒',
                    CASE hit.fence_type WHEN '1' THEN '禁飞区' WHEN '2' THEN '管控区' ELSE '电子围栏' END,
                    ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
            END::varchar AS msg,
            (hit.id IS NOT NULL) AS ischeck,
            CASE WHEN hit.id IS NULL THEN 'p_outer' ELSE 'p_inner' END::varchar AS check_type,
            COALESCE(hit.table_name, '')::varchar AS table_name,
            ip.geom,
            hit.id::varchar(32) AS electric_id,
            hit.fence_type::varchar AS fence_type,
            hit.electric_name::varchar AS electric_name,
            hit.geom AS electric_geom,
            hit.geom_geojson AS electric_geojson
        FROM (
            SELECT d.path, d.geom AS geom
            FROM ST_Dump(v_point) AS d
        ) ip
        LEFT JOIN LATERAL (
            SELECT
                'bo_electric_fence'::varchar AS table_name,
                f.id::varchar(32) AS id,
                f.fence_type::varchar AS fence_type,
                f.name::varchar AS electric_name,
                f.geom AS geom,
                ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson
            FROM bo_electric_fence f
            WHERE f.fence_type IN ('1','2') -- 围栏类型：禁飞区/管控区
              AND f.status = '1'            -- 状态：启用
              AND f.del_flag = false        -- 未删
              AND f.use_enabled = true       -- 使用状态：启用
              AND ST_Intersects(ST_SetSRID(f.geom, 4326), ip.geom)
              AND (
                  NOT p_is_3d
                  OR
                  COALESCE(ST_Z(ip.geom), 0) = 0
                  OR COALESCE(f.height, 0) = 0
                  OR
                  (COALESCE(ST_Z(ip.geom), 0) > 0 AND COALESCE(ST_Z(ip.geom), 0) <= f.height)
              )
            LIMIT 1
        ) hit ON true
        ORDER BY ip.path;

        -- 检查是否找到结果
        IF FOUND THEN
            v_found := true;
        END IF;
    END IF;

    -- =============================================
    -- 00 成功】未检测到闯入任何禁飞区/管控区
    -- =============================================
    IF NOT v_found THEN
        RETURN QUERY SELECT
            200, format('当前位置不在禁飞区/管控区内，check_type=p_outer(点在外部)，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false, 'p_outer'::varchar, ''::varchar, v_point, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
        RETURN;
    END IF;

-- =============================================
-- 00 服务异常】系数据空间函数异常
-- =============================================
EXCEPTION
    WHEN OTHERS THEN
        code := 500;
        msg := format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'p_outer'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
END;
$$;
COMMENT ON FUNCTION public.gis_electric_fence_check_point(text, text, boolean) IS '检测航点落入围栏';

-- ====================================================================================
-- 函数名称gis_electric_fence_check_line
-- 函数功能无人机航线/轨迹电子围栏穿越检测
-- 函数描述1. 传入航线 GeoJSON（LineString/LineStringZ/MultiLineString）
--            2. 禁飞区和管控区统一按二维平面相交 + 航线高度过滤判断
--            3. 围栏height为空或0时按无限高处理；航线未传高度或高度为0时通过高度判断
--            4. 只查询未删除、有效状态的围栏
--            5. 返回标准格式结果集，前端可直接渲
-- 函数说明依赖PostGIS空间扩展，坐标系默认使用WGS84(4326)
-- 参数说明
--   p_line_geojson     text           输入参数：线轨迹/线段的GeoJSON字符串（必填
--   p_is_3d            boolean        输入参数：是否启用高度判断，默认true；false时只做二维平面判断
-- 返回值： 标准TABLE结构，包含状态码、提示信息、输入线几何、命中围栏信息
--   code      integer    状态码00=执行成功 400=参数错误/未查询到数据 500=执行异常
--   msg       varchar    状态描述信息
--   geom      geometry   本次校验的输入线几何
--   electric_id varchar(32) 命中的围栏ID
--   electric_geom geometry  命中的围栏数据库原始几何
--   electric_geojson json   命中的围栏GeoJSON
-- 适用场景无人机航线闯入禁飞区/管控区实时检测
-- ====================================================================================

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_electric_fence_check_line');

-- 创建函数
-- =============================================================================
-- 函数介绍：gis_electric_fence_check_line
-- 主要作用：检测输入航线是否直接穿越或接触启用中的电子围栏区域，并结合height做高度过滤
-- 入参说明：p_line_json 为航线LineString/LineStringZ GeoJSON、Feature或坐标数组；p_is_3d 控制二维/三维判断
-- 返回说明：返回是否冲突、命中围栏属性和相交结果，供航线提交前快速校验
-- 注意事项：本函数不额外扩航线缓冲；高度判断使用航线最低高度 line_min_z 与围栏 height 比较
-- =============================================================================
CREATE OR REPLACE FUNCTION public.gis_electric_fence_check_line(
    p_project_id text,
    p_line_geojson text,
    p_is_3d boolean DEFAULT true
)
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    table_name varchar,
    geom geometry,
    electric_id varchar(32),
    fence_type varchar,
    electric_name varchar,
    electric_geom geometry,
    electric_geojson json
)
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
    v_line geometry;
    v_line_json jsonb;
    v_fence_3d geometry;
    v_table_name text;
    v_sql text;
    v_table_exists boolean;
    v_start_time timestamptz := clock_timestamp(); -- 函数开始时间，用于统一返回耗时
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_check_line(%L, %L, %L);',
        p_project_id, p_line_geojson, p_is_3d);

    -- 1. 参数校验
    IF p_line_geojson IS NULL OR p_line_geojson = '' THEN
        code := 400;
        msg := format('航线GeoJSON不能为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'ln_outside'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    -- 2. 解析航线输入，并设置坐标系WGS84(4326)
    BEGIN
        v_line_json := p_line_geojson::jsonb;

        IF jsonb_typeof(v_line_json) = 'array' THEN
            -- 支持单线 [[lng,lat,alt], ...] 和多线 [[[lng,lat,alt], ...], ...].
            IF jsonb_array_length(v_line_json) < 2 THEN
                RAISE EXCEPTION 'Line coordinate array requires at least two points';
            END IF;

            IF jsonb_typeof(v_line_json -> 0) = 'array'
               AND jsonb_array_length(v_line_json -> 0) > 0
               AND jsonb_typeof((v_line_json -> 0) -> 0) = 'array' THEN
                v_line := ST_GeomFromGeoJSON(
                    jsonb_build_object(
                        'type', 'MultiLineString',
                        'coordinates', v_line_json
                    )::text
                );
            ELSE
                v_line := ST_GeomFromGeoJSON(
                    jsonb_build_object(
                        'type', 'LineString',
                        'coordinates', v_line_json
                    )::text
                );
            END IF;
        ELSIF v_line_json ->> 'type' = 'FeatureCollection' THEN
            IF jsonb_typeof(v_line_json -> 'features') <> 'array'
               OR jsonb_array_length(v_line_json -> 'features') = 0 THEN
                RAISE EXCEPTION 'FeatureCollection requires non-empty features';
            END IF;

            SELECT ST_Multi(ST_Collect(
                ST_GeomFromGeoJSON(f.feature ->> 'geometry')
                ORDER BY f.ord
            ))
            INTO v_line
            FROM jsonb_array_elements(v_line_json -> 'features') WITH ORDINALITY AS f(feature, ord)
            WHERE f.feature -> 'geometry' IS NOT NULL;
        ELSIF v_line_json ->> 'type' = 'Feature' THEN
            -- Feature格式：几何数据位于geometry节点。
            v_line := ST_GeomFromGeoJSON(v_line_json ->> 'geometry');
        ELSE
            -- Geometry格式：LineString/MultiLineString。
            v_line := ST_GeomFromGeoJSON(v_line_json::text);
        END IF;

        v_line := ST_SetSRID(v_line, 4326);
    EXCEPTION
        WHEN OTHERS THEN
            code := 400;
            msg := format('航线GeoJSON/坐标数组解析失败：%s，执行时间 %s 秒',
                    SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            INSERT INTO public.gis_error_log(code, msg, sqlstring)
            VALUES (
                code,
                msg,
                v_log_sql
            );

            RETURN QUERY SELECT
                code, msg::varchar,
                false, 'ln_outside'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
            RETURN;
    END;

    -- 3. 校验输入必须是线要素(LineString/MultiLineString)
    IF ST_GeometryType(v_line) NOT IN ('ST_LineString', 'ST_MultiLineString') THEN
        code := 400;
        msg := format('输入几何体必须是线类型(LineString)，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'ln_outside'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    -- 4. 航线二维平面相交 + 高度过滤：禁飞区和管控区统一使用同一套逻辑。
    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
        v_table_name := 'gis_electric_fence_' || trim(p_project_id);

        SELECT EXISTS (
            SELECT 1 FROM information_schema.tables t
            WHERE t.table_schema = 'public'
              AND t.table_name = v_table_name
        ) INTO v_table_exists;

        IF v_table_exists THEN
            v_sql := format('
                WITH input_lines AS (
                    SELECT
                        d.path,
                        d.geom AS geom,
                        COALESCE(MIN(ST_Z((dp).geom)), 0) AS line_min_z,
                        COALESCE(MAX(ST_Z((dp).geom)), 0) AS line_max_z
                    FROM ST_Dump($1) AS d
                    CROSS JOIN LATERAL ST_DumpPoints(d.geom) AS dp
                    GROUP BY d.path, d.geom
                )
                SELECT
                    200 AS code,
                    CASE
                        WHEN hit.id IS NULL THEN format(''航线未闯入任何电子围栏，check_type=%%s，执行时间 %%s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $2)::numeric, 3))
                        ELSE format(''检测到航线闯入电子围栏，check_type=%%s，执行时间 %%s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $2)::numeric, 3))
                    END::varchar AS msg,
                    (hit.id IS NOT NULL) AS ischeck,
                ct.check_type,
                COALESCE(hit.table_name, '''')::varchar AS table_name,
                il.geom,
                    hit.id::varchar(32) AS electric_id,
                    hit.fence_type::varchar AS fence_type,
                    hit.electric_name::varchar AS electric_name,
                    hit.geom AS electric_geom,
                    hit.geom_geojson AS electric_geojson
                FROM input_lines il
                LEFT JOIN LATERAL (
                    SELECT h.table_name, h.id, h.fence_type, h.electric_name, h.geom, h.geom_geojson
                    FROM (
                        SELECT
                            %L::varchar AS table_name,
                            f.id::varchar(32) AS id,
                            f.fence_type::varchar AS fence_type,
                            f.name::varchar AS electric_name,
                            f.geom AS geom,
                            ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson,
                            1 AS priority
                        FROM %I f
                        WHERE f.fence_type IN (''1'',''2'')
                          AND ST_Intersects(ST_SetSRID(f.geom, 4326), ST_Force2D(il.geom))
                          AND (
                              NOT $3
                              OR COALESCE(f.height, 0) = 0
                              OR il.line_min_z = 0
                              OR il.line_min_z <= f.height
                          )
                        UNION ALL
                        SELECT
                            ''bo_electric_fence''::varchar AS table_name,
                            f.id::varchar(32) AS id,
                            f.fence_type::varchar AS fence_type,
                            f.name::varchar AS electric_name,
                            f.geom AS geom,
                            ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson,
                            2 AS priority
                        FROM bo_electric_fence f
                        WHERE f.fence_type IN (''1'',''2'')
                          AND f.del_flag = false
                          AND f.status = ''1''
                          AND f.use_enabled = true
                          AND ST_Intersects(ST_SetSRID(f.geom, 4326), ST_Force2D(il.geom))
                          AND (
                              NOT $3
                              OR COALESCE(f.height, 0) = 0
                              OR il.line_min_z = 0
                              OR il.line_min_z <= f.height
                          )
                    ) h
                    ORDER BY h.priority, h.id
                    LIMIT 1
                ) hit ON true
                CROSS JOIN LATERAL (
                    SELECT
                        x.check_type,
                        CASE x.check_type
                            WHEN ''ln_outside'' THEN ''ln_outside(线与面：相离)''
                            WHEN ''ln_within'' THEN ''ln_within(线与面：包含于)''
                            WHEN ''ln_enters'' THEN ''ln_enters(线与面：穿入/穿出)''
                            WHEN ''ln_overlaps'' THEN ''ln_overlaps(线与面：重叠)''
                            ELSE ''ln_crosses(线与面：交叉)''
                        END::varchar AS check_type_msg
                    FROM (
                        SELECT CASE
                            WHEN hit.id IS NULL THEN ''ln_outside''
                            WHEN ST_CoveredBy(ST_Force2D(il.geom), ST_Boundary(ST_SetSRID(hit.geom, 4326))) THEN ''ln_overlaps''
                            WHEN ST_CoveredBy(ST_Force2D(il.geom), ST_SetSRID(hit.geom, 4326)) THEN ''ln_within''
                            WHEN ST_Covers(ST_SetSRID(hit.geom, 4326), ST_StartPoint(ST_Force2D(il.geom))) <> ST_Covers(ST_SetSRID(hit.geom, 4326), ST_EndPoint(ST_Force2D(il.geom))) THEN ''ln_enters''
                            ELSE ''ln_crosses''
                        END::varchar AS check_type
                    ) x
                ) ct
                ORDER BY il.path',
                v_table_name,
                v_table_name
            );
        ELSE
            v_sql := '
                WITH input_lines AS (
                    SELECT
                        d.path,
                        d.geom AS geom,
                        COALESCE(MIN(ST_Z((dp).geom)), 0) AS line_min_z,
                        COALESCE(MAX(ST_Z((dp).geom)), 0) AS line_max_z
                    FROM ST_Dump($1) AS d
                    CROSS JOIN LATERAL ST_DumpPoints(d.geom) AS dp
                    GROUP BY d.path, d.geom
                )
                SELECT
                    200 AS code,
                    CASE
                        WHEN hit.id IS NULL THEN format(''航线未闯入任何电子围栏，check_type=%s，执行时间 %s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $2)::numeric, 3))
                        ELSE format(''检测到航线闯入电子围栏，check_type=%s，执行时间 %s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $2)::numeric, 3))
                    END::varchar AS msg,
                    (hit.id IS NOT NULL) AS ischeck,
                ct.check_type,
                COALESCE(hit.table_name, '''')::varchar AS table_name,
                il.geom,
                    hit.id::varchar(32) AS electric_id,
                    hit.fence_type::varchar AS fence_type,
                    hit.electric_name::varchar AS electric_name,
                    hit.geom AS electric_geom,
                    hit.geom_geojson AS electric_geojson
                FROM input_lines il
                LEFT JOIN LATERAL (
                    SELECT
                        ''bo_electric_fence''::varchar AS table_name,
                        f.id::varchar(32) AS id,
                        f.fence_type::varchar AS fence_type,
                        f.name::varchar AS electric_name,
                        f.geom AS geom,
                        ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson
                    FROM bo_electric_fence f
                    WHERE f.fence_type IN (''1'',''2'')
                      AND f.del_flag = false
                      AND f.status = ''1''
                      AND f.use_enabled = true
                      AND ST_Intersects(ST_SetSRID(f.geom, 4326), ST_Force2D(il.geom))
                      AND (
                          NOT $3
                          OR COALESCE(f.height, 0) = 0
                          OR il.line_min_z = 0
                          OR il.line_min_z <= f.height
                      )
                    ORDER BY f.id
                    LIMIT 1
                ) hit ON true
                CROSS JOIN LATERAL (
                    SELECT
                        x.check_type,
                        CASE x.check_type
                            WHEN ''ln_outside'' THEN ''ln_outside(线与面：相离)''
                            WHEN ''ln_within'' THEN ''ln_within(线与面：包含于)''
                            WHEN ''ln_enters'' THEN ''ln_enters(线与面：穿入/穿出)''
                            WHEN ''ln_overlaps'' THEN ''ln_overlaps(线与面：重叠)''
                            ELSE ''ln_crosses(线与面：交叉)''
                        END::varchar AS check_type_msg
                    FROM (
                        SELECT CASE
                            WHEN hit.id IS NULL THEN ''ln_outside''
                            WHEN ST_CoveredBy(ST_Force2D(il.geom), ST_Boundary(ST_SetSRID(hit.geom, 4326))) THEN ''ln_overlaps''
                            WHEN ST_CoveredBy(ST_Force2D(il.geom), ST_SetSRID(hit.geom, 4326)) THEN ''ln_within''
                            WHEN ST_Covers(ST_SetSRID(hit.geom, 4326), ST_StartPoint(ST_Force2D(il.geom))) <> ST_Covers(ST_SetSRID(hit.geom, 4326), ST_EndPoint(ST_Force2D(il.geom))) THEN ''ln_enters''
                            ELSE ''ln_crosses''
                        END::varchar AS check_type
                    ) x
                ) ct
                ORDER BY il.path';
        END IF;
    ELSE
        v_sql := '
            WITH input_lines AS (
                SELECT
                    d.path,
                    d.geom AS geom,
                    COALESCE(MIN(ST_Z((dp).geom)), 0) AS line_min_z,
                    COALESCE(MAX(ST_Z((dp).geom)), 0) AS line_max_z
                FROM ST_Dump($1) AS d
                CROSS JOIN LATERAL ST_DumpPoints(d.geom) AS dp
                GROUP BY d.path, d.geom
            )
            SELECT
                200 AS code,
                CASE
                    WHEN hit.id IS NULL THEN format(''航线未闯入任何电子围栏，check_type=%s，执行时间 %s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $2)::numeric, 3))
                    ELSE format(''检测到航线闯入电子围栏，check_type=%s，执行时间 %s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $2)::numeric, 3))
                END::varchar AS msg,
                (hit.id IS NOT NULL) AS ischeck,
                ct.check_type,
                COALESCE(hit.table_name, '''')::varchar AS table_name,
                il.geom,
                hit.id::varchar(32) AS electric_id,
                hit.fence_type::varchar AS fence_type,
                hit.electric_name::varchar AS electric_name,
                hit.geom AS electric_geom,
                hit.geom_geojson AS electric_geojson
            FROM input_lines il
            LEFT JOIN LATERAL (
                SELECT
                    ''bo_electric_fence''::varchar AS table_name,
                    f.id::varchar(32) AS id,
                    f.fence_type::varchar AS fence_type,
                    f.name::varchar AS electric_name,
                    f.geom AS geom,
                    ST_AsGeoJSON(ST_SetSRID(f.geom, 4326))::json AS geom_geojson
                FROM bo_electric_fence f
                WHERE f.fence_type IN (''1'',''2'')
                  AND f.del_flag = false
                  AND f.status = ''1''
                  AND f.use_enabled = true
                  AND ST_Intersects(ST_SetSRID(f.geom, 4326), ST_Force2D(il.geom))
                  AND (
                      NOT $3
                      OR COALESCE(f.height, 0) = 0
                      OR il.line_min_z = 0
                      OR il.line_min_z <= f.height
                  )
                ORDER BY f.id
                LIMIT 1
            ) hit ON true
            CROSS JOIN LATERAL (
                SELECT
                    x.check_type,
                    CASE x.check_type
                        WHEN ''ln_outside'' THEN ''ln_outside(线与面：相离)''
                        WHEN ''ln_within'' THEN ''ln_within(线与面：包含于)''
                        WHEN ''ln_enters'' THEN ''ln_enters(线与面：穿入/穿出)''
                        WHEN ''ln_overlaps'' THEN ''ln_overlaps(线与面：重叠)''
                        ELSE ''ln_crosses(线与面：交叉)''
                    END::varchar AS check_type_msg
                FROM (
                    SELECT CASE
                        WHEN hit.id IS NULL THEN ''ln_outside''
                        WHEN ST_CoveredBy(ST_Force2D(ifl.geom), ST_Boundary(ST_SetSRID(hit.geom, 4326))) THEN ''ln_overlaps''
                        WHEN ST_CoveredBy(ST_Force2D(il.geom), ST_SetSRID(hit.geom, 4326)) THEN ''ln_within''
                        WHEN ST_Covers(ST_SetSRID(hit.geom, 4326), ST_StartPoint(ST_Force2D(il.geom))) <> ST_Covers(ST_SetSRID(hit.geom, 4326), ST_EndPoint(ST_Force2D(il.geom))) THEN ''ln_enters''
                        ELSE ''ln_crosses''
                    END::varchar AS check_type
                ) x
            ) ct
            ORDER BY il.path';
    END IF;

    RETURN QUERY EXECUTE v_sql USING v_line, v_start_time, p_is_3d;

    -- 5. 无碰撞时返回空结果状00
    IF NOT FOUND THEN
        RETURN QUERY SELECT
            200, format('航线未闯入任何电子围栏，check_type=ln_outside(线与面：相离)，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false, 'ln_outside'::varchar, ''::varchar, v_line, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
    END IF;

-- 异常捕获
EXCEPTION
    WHEN OTHERS THEN
        code := 500;
        msg := format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'ln_outside'::varchar, ''::varchar, NULL::geometry, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json;
END;
$$;
COMMENT ON FUNCTION public.gis_electric_fence_check_line(text, text, boolean) IS '检测航线穿越围栏';



-- ====================================================================================
-- 函数名称gis_electric_fence_buffer
-- 函数功能根据电子围栏ID和缓冲半径，计算围栏2D缓冲面、构D立体几何体，并返回GeoJSON格式数据
-- 函数描述1. 校验入参围栏ID是否为空
--            2. 从电子围栏表查询有效围栏数据（未删除
--            3. 基于WGS84(4326)坐标系计算指定半径的2D平面缓冲突
--            4. 基于2D缓冲面生成底部Z=0、顶部Z=围栏高度D立体几何
--            5. 统一返回标准状态码+几何数据的GeoJSON
-- 函数说明依赖PostGIS空间扩展，坐标系默认使用WGS84(4326)，平面缓冲使用墨卡托(3857)计算
-- 参数说明
--   p_project_id   text          输入参数：项目ID（可选）
--   p_fence_id     varchar(32)   输入参数：电子围栏唯一ID（可选，为空返回全部）
--   p_buffer_radius double precision 输入参数：缓冲半径（单位：米），0则不做缓冲，直接使用原始围栏
-- 返回值： 标准TABLE结构，包含状态码、提示信息、围栏ID、各类几何GeoJSON
--   code      integer    状态码00=执行成功 400=参数错误/未查询到数据 500=执行异常
-- 200：执行成功，返回完整几何数据
-- 400：参数为/ 无有效围栏数据（业务异常
-- 500：SQL 执行异常、表不存在、字段错误等（系统异常）
--   msg       varchar    状态描述信息
-- 返回策略
--   code=200 表示函数正常完成功
--   code=400 表示输入参数非法
--   code=500 表示执行过程中出现异常
--   msg 中包含执行时间，以及具体执行说明
--   id        varchar(32) 围栏ID
--   geom_geojson json    原始围栏几何的GeoJSON
--   electric_buffer_geom geometry 缓冲面几何
--   electric_buffer_geojson json 缓冲面几何的GeoJSON
--   electric_solid_geom geometry 立体几何体
--   electric_solid_geojson json 立体几何体的GeoJSON
-- 函数注意
--   1. bo_electric_fence 必须存在，且包含字段：id, geom, height, del_flag
--   2. geom 字段为PostGIS几何类型，height 为围栏高度（数字类型
--   3. 缓冲半径单位**，坐标系转换保证距离计算准确
--   4. 3D几何体为：底Z=0) + 顶部(Z=围栏高度) 的集合几何体
-- 适用场景电子围栏可视化、GIS空间分析、前端地图渲染（2D/3D围栏展示
-- ====================================================================================

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_electric_fence_buffer');

-- =============================================================================
-- 函数介绍：gis_electric_fence_buffer
-- 主要作用：根据电子围栏ID和缓冲距离，计算围栏外扩后的缓冲面几何
-- 入参说明：p_project_id 为项目ID；p_fence_id 为围栏ID（为空返回全部）；p_buffer_m 为缓冲距离，单位米。
-- 返回说明：返回缓冲区GeoJSON、原始围栏信息和执行状态，便于前端展示或后续碰撞判断。
-- 注意事项：缓冲按米计算，内部会转换到适合平面距离计算的坐标系后再转回WGS84
-- =============================================================================
CREATE OR REPLACE FUNCTION public.gis_electric_fence_buffer(
    p_fence_id varchar(32),        -- 入参1：围栏ID
    p_buffer_radius double precision, -- 入参2：缓冲半径（米）
    p_return_geojson boolean DEFAULT false -- 是否返回GeoJSON
)
-- 定义函数返回的表结构（字段顺序、类型必须严格匹配）
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    electric_id varchar(32),
    fence_type varchar,
    electric_geom geometry,
    electric_geojson json,
    electric_buffer_geom geometry,
    electric_buffer_geojson json,
    electric_solid_geom geometry,
    electric_solid_geojson json
)
-- 函数语言：PL/pgSQL（PostgreSQL过程语言
LANGUAGE plpgsql
-- 易变性声明：VOLATILE 表示函数可能写入错误日志表
VOLATILE
AS $$
DECLARE
    -- 定义变量：存D缓冲后的几何对象
    v_buffer_geom geometry;
    -- 定义变量：存储单条围栏记录（类型与表 bo_electric_fence 完全一致）
    v_fence_record bo_electric_fence%ROWTYPE;
    -- 定义变量：存D立体几何对象
    v_3d_geom geometry;
    v_start_time timestamptz := clock_timestamp(); -- 函数开始时间，用于统一返回耗时
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_buffer(%L, %s, %L);',
        p_fence_id, COALESCE(p_buffer_radius::text, 'NULL'), p_return_geojson);

    -- ==============================================
    -- 1. 入参合法性校验：围栏ID 不能为空/空字符串
    -- ==============================================
    IF p_fence_id IS NULL OR p_fence_id = '' THEN
        -- 返回400：参数错误，所有几何字段置
        code := 400;
        msg := format('围栏ID不能为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
        -- 终止函数执行
        RETURN;
    END IF;

    -- ==============================================
    -- 2. 查询有效围栏数据（未逻辑删除
    -- ==============================================
    SELECT *
    INTO v_fence_record  -- 查询结果存入围栏记录变量
    FROM bo_electric_fence f
    WHERE f.id = p_fence_id  -- 按围栏ID匹配
      AND f.del_flag = false  -- 只查询未删除的数据
      AND f.status = '1'      -- 只查询启用状态的数据
      AND f.use_enabled = true; -- 只查询使用启用的数据

    -- ==============================================
    -- 3. 校验：未查询到有效围栏数据
    -- ==============================================
    IF v_fence_record.id IS NULL THEN
        -- 返回400：无数据，所有几何字段置
        code := 400;
        msg := format('未查询到有效围栏数据，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    -- ==============================================
    -- 4. 计算2D缓冲几何（核心GIS逻辑
    -- ==============================================
    SELECT
            CASE
                -- 情况1：缓冲半0 直接使用原始围栏几何，设置坐标系4326(WGS84)
                WHEN p_buffer_radius = 0 THEN
                    ST_SetSRID(v_fence_record.geom, 4326)
                -- 情况2：半0 计算缓冲突
                ELSE
                    -- 步骤326857（墨卡托，米单位）→ 做缓转回4326
                    ST_Transform(
                        ST_Buffer(
                            ST_Transform(ST_SetSRID(v_fence_record.geom,4326),3857),
                            p_buffer_radius
                        ),
                        4326
                    )
            END
    INTO v_buffer_geom; -- 结果存入缓冲几何变量

    -- ==============================================
    -- 5. 构建3D立体几何体（底部+顶部
    -- ==============================================
    SELECT
            -- 转换为多几何对象（兼容前端渲染）
            ST_Multi(
                -- 合并两个3D面：底部(Z=0) + 顶部(Z=围栏高度)
                ST_Collect(
                    -- 底部面：Z坐标=0
                    ST_Force3DZ(v_buffer_geom, 0),
                    -- 顶部面：Z坐标=围栏高度（空值则
                    ST_Force3DZ(v_buffer_geom, COALESCE(v_fence_record.height, 0))
                )
            )
    INTO v_3d_geom; -- 结果存入3D几何变量

    -- ==============================================
    -- 6. 执行成功：返00 + 所有几何数据
    -- ==============================================
    RETURN QUERY SELECT
        200,                        -- 状态码：成功
        format('成功，check_type=b_generated(缓冲区已生成)，执行时间 %s 秒',
            ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,            -- 提示信息
        true,
        'b_generated'::varchar,
        v_fence_record.id::varchar, -- 围栏ID
        v_fence_record.fence_type::varchar,
        v_fence_record.geom,
        -- 原始围栏几何 GeoJSON
        CASE WHEN p_return_geojson THEN ST_AsGeoJSON(ST_SetSRID(v_fence_record.geom, 4326))::json ELSE NULL::json END,
        v_buffer_geom,
        -- 2D缓冲几何 GeoJSON
        CASE WHEN p_return_geojson THEN ST_AsGeoJSON(v_buffer_geom)::json ELSE NULL::json END,
        v_3d_geom,
        -- 3D立体几何 GeoJSON
        CASE WHEN p_return_geojson THEN ST_AsGeoJSON(v_3d_geom)::json ELSE NULL::json END;

-- ==============================================
-- 异常捕获：执行过程中出现任何错误，返00
-- ==============================================
EXCEPTION
    WHEN OTHERS THEN
        code := 500;
        msg := format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
END;
$$;
COMMENT ON FUNCTION public.gis_electric_fence_buffer(varchar, double precision, boolean) IS '生成电子围栏缓冲区';

-- 支持项目ID；p_fence_id为空时返回项目/公共范围内全部围栏缓冲数据
CREATE OR REPLACE FUNCTION public.gis_electric_fence_buffer(
    p_project_id text,
    p_fence_id varchar(32) DEFAULT NULL,
    p_buffer_radius double precision DEFAULT 0,
    p_return_geojson boolean DEFAULT false
)
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    electric_id varchar(32),
    fence_type varchar,
    electric_geom geometry,
    electric_geojson json,
    electric_buffer_geom geometry,
    electric_buffer_geojson json,
    electric_solid_geom geometry,
    electric_solid_geojson json
)
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
    v_table_name text;
    v_table_exists boolean;
    v_sql text;
    v_start_time timestamptz := clock_timestamp();
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_buffer(%L, %L, %s, %L);',
        p_project_id, p_fence_id, COALESCE(p_buffer_radius::text, 'NULL'), p_return_geojson);

    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
        v_table_name := 'gis_electric_fence_' || trim(p_project_id);

        SELECT EXISTS (
            SELECT 1 FROM information_schema.tables t
            WHERE t.table_schema = 'public'
              AND t.table_name = v_table_name
        ) INTO v_table_exists;

        IF v_table_exists THEN
            v_sql := format('
                WITH src AS (
                    SELECT f.id::varchar AS id,
                           f.geom AS geom,
                           ST_SetSRID(f.geom, 4326) AS calc_geom,
                           COALESCE(f.height, 0)::double precision AS height,
                           ''1''::varchar AS fence_type
                    FROM %I f
                    WHERE f.geom IS NOT NULL
                      AND ($1 IS NULL OR btrim($1) = '''' OR f.id::varchar = btrim($1))
                    UNION ALL
                    SELECT f.id::varchar AS id,
                           f.geom AS geom,
                           ST_SetSRID(f.geom, 4326) AS calc_geom,
                           COALESCE(f.height, 0)::double precision AS height,
                           f.fence_type::varchar AS fence_type
                    FROM bo_electric_fence f
                    WHERE f.del_flag = false
                      AND f.status = ''1''
                      AND f.use_enabled = true
                      AND f.geom IS NOT NULL
                      AND ($1 IS NULL OR btrim($1) = '''' OR f.id::varchar = btrim($1))
                      AND ($2 IS NULL OR btrim($2) = '''' OR f.project_id::text = btrim($2))
                )
                SELECT
                    200 AS code,
                    format(''成功，check_type=b_generated(缓冲区已生成)，执行时间 %%s 秒'', ROUND(EXTRACT(epoch FROM clock_timestamp() - $4)::numeric, 3))::varchar AS msg,
                    true AS ischeck,
                    ''b_generated''::varchar AS check_type,
                    src.id::varchar(32) AS electric_id,
                    src.fence_type::varchar AS fence_type,
                    src.geom AS electric_geom,
                    CASE WHEN $5 THEN ST_AsGeoJSON(src.calc_geom)::json ELSE NULL::json END AS electric_geojson,
                    buf.buffer_geom AS electric_buffer_geom,
                    CASE WHEN $5 THEN ST_AsGeoJSON(buf.buffer_geom)::json ELSE NULL::json END AS electric_buffer_geojson,
                    solid.solid_geom AS electric_solid_geom,
                    CASE WHEN $5 THEN ST_AsGeoJSON(solid.solid_geom)::json ELSE NULL::json END AS electric_solid_geojson
                FROM src
                CROSS JOIN LATERAL (
                    SELECT CASE
                        WHEN COALESCE($3, 0) = 0 THEN ST_Force2D(src.calc_geom)
                        ELSE ST_Transform(
                            ST_Buffer(ST_Transform(ST_Force2D(src.calc_geom), 3857), COALESCE($3, 0)),
                            4326
                        )
                    END AS buffer_geom
                ) buf
                CROSS JOIN LATERAL (
                    SELECT ST_Multi(ST_Collect(
                            ST_Force3DZ(buf.buffer_geom, 0),
                            ST_Force3DZ(buf.buffer_geom, src.height)
                        )) AS solid_geom
                ) solid',
                v_table_name
            );
        ELSE
            v_sql := '
                WITH src AS (
                    SELECT f.id::varchar AS id,
                           f.geom AS geom,
                           ST_SetSRID(f.geom, 4326) AS calc_geom,
                           COALESCE(f.height, 0)::double precision AS height,
                           f.fence_type::varchar AS fence_type
                    FROM bo_electric_fence f
                    WHERE f.del_flag = false
                      AND f.status = ''1''
                      AND f.use_enabled = true
                      AND f.geom IS NOT NULL
                      AND ($1 IS NULL OR btrim($1) = '''' OR f.id::varchar = btrim($1))
                      AND ($2 IS NULL OR btrim($2) = '''' OR f.project_id::text = btrim($2))
                )
                SELECT
                    200 AS code,
                    format(''成功，check_type=b_generated(缓冲区已生成)，执行时间 %s 秒'', ROUND(EXTRACT(epoch FROM clock_timestamp() - $4)::numeric, 3))::varchar AS msg,
                    true AS ischeck,
                    ''b_generated''::varchar AS check_type,
                    src.id::varchar(32) AS electric_id,
                    src.fence_type::varchar AS fence_type,
                    src.geom AS electric_geom,
                    CASE WHEN $5 THEN ST_AsGeoJSON(src.calc_geom)::json ELSE NULL::json END AS electric_geojson,
                    buf.buffer_geom AS electric_buffer_geom,
                    CASE WHEN $5 THEN ST_AsGeoJSON(buf.buffer_geom)::json ELSE NULL::json END AS electric_buffer_geojson,
                    solid.solid_geom AS electric_solid_geom,
                    CASE WHEN $5 THEN ST_AsGeoJSON(solid.solid_geom)::json ELSE NULL::json END AS electric_solid_geojson
                FROM src
                CROSS JOIN LATERAL (
                    SELECT CASE
                        WHEN COALESCE($3, 0) = 0 THEN ST_Force2D(src.calc_geom)
                        ELSE ST_Transform(
                            ST_Buffer(ST_Transform(ST_Force2D(src.calc_geom), 3857), COALESCE($3, 0)),
                            4326
                        )
                    END AS buffer_geom
                ) buf
                CROSS JOIN LATERAL (
                    SELECT ST_Multi(ST_Collect(
                            ST_Force3DZ(buf.buffer_geom, 0),
                            ST_Force3DZ(buf.buffer_geom, src.height)
                        )) AS solid_geom
                ) solid';
        END IF;
    ELSE
        v_sql := '
            WITH src AS (
                SELECT f.id::varchar AS id,
                       f.geom AS geom,
                       ST_SetSRID(f.geom, 4326) AS calc_geom,
                       COALESCE(f.height, 0)::double precision AS height,
                       f.fence_type::varchar AS fence_type
                    FROM bo_electric_fence f
                    WHERE f.del_flag = false
                      AND f.status = ''1''
                      AND f.use_enabled = true
                      AND f.geom IS NOT NULL
                  AND ($1 IS NULL OR btrim($1) = '''' OR f.id::varchar = btrim($1))
            )
            SELECT
                200 AS code,
                format(''成功，check_type=b_generated(缓冲区已生成)，执行时间 %s 秒'', ROUND(EXTRACT(epoch FROM clock_timestamp() - $4)::numeric, 3))::varchar AS msg,
                true AS ischeck,
                ''b_generated''::varchar AS check_type,
                src.id::varchar(32) AS electric_id,
                src.fence_type::varchar AS fence_type,
                src.geom AS electric_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(src.calc_geom)::json ELSE NULL::json END AS electric_geojson,
                buf.buffer_geom AS electric_buffer_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(buf.buffer_geom)::json ELSE NULL::json END AS electric_buffer_geojson,
                solid.solid_geom AS electric_solid_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(solid.solid_geom)::json ELSE NULL::json END AS electric_solid_geojson
            FROM src
            CROSS JOIN LATERAL (
                SELECT CASE
                    WHEN COALESCE($3, 0) = 0 THEN ST_Force2D(src.calc_geom)
                    ELSE ST_Transform(
                        ST_Buffer(ST_Transform(ST_Force2D(src.calc_geom), 3857), COALESCE($3, 0)),
                        4326
                    )
                END AS buffer_geom
            ) buf
            CROSS JOIN LATERAL (
                SELECT ST_Multi(ST_Collect(
                        ST_Force3DZ(buf.buffer_geom, 0),
                        ST_Force3DZ(buf.buffer_geom, src.height)
                    )) AS solid_geom
            ) solid';
    END IF;

    RETURN QUERY EXECUTE v_sql USING p_fence_id, p_project_id, p_buffer_radius, v_start_time, p_return_geojson;

    IF NOT FOUND THEN
        code := 400;
        msg := format('未查询到有效围栏数据，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        code := 500;
        msg := format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
END;
$$;
COMMENT ON FUNCTION public.gis_electric_fence_buffer(text, varchar, double precision, boolean) IS '生成电子围栏缓冲区';



-- 航点缓冲区检测，支持项目ID

SELECT gis_drop_function('gis_electric_fence_check_point_buffer');

CREATE OR REPLACE FUNCTION public.gis_electric_fence_check_point_buffer(
    p_project_id text,
    p_point_geojson text,
    p_buffer_radius double precision DEFAULT 0,
    p_return_geojson boolean DEFAULT false
)
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    electric_id varchar(32),
    fence_type varchar,
    electric_name varchar,
    electric_geom geometry,
    electric_geojson json,
    electric_buffer_geom geometry,
    electric_buffer_geojson json,
    electric_solid_geom geometry,
    electric_solid_geojson json
)
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
    v_point geometry;
    v_point_json jsonb;
    v_z double precision;
    v_table_name text;
    v_table_exists boolean;
    v_sql text;
    v_start_time timestamptz := clock_timestamp();
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_check_point_buffer(%L, %L, %s, %L);',
        p_project_id, p_point_geojson, COALESCE(p_buffer_radius::text, 'NULL'), p_return_geojson);

    IF p_point_geojson IS NULL OR p_point_geojson = '' THEN
        code := 400;
        msg := format('点的GeoJSON不能为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    BEGIN
        v_point_json := p_point_geojson::jsonb;
        IF jsonb_typeof(v_point_json) = 'array' THEN
            IF jsonb_array_length(v_point_json) < 2 THEN
                RAISE EXCEPTION 'Point coordinate array requires at least lng and lat';
            ELSIF jsonb_array_length(v_point_json) >= 3 THEN
                v_point := ST_MakePoint(
                    (v_point_json ->> 0)::double precision,
                    (v_point_json ->> 1)::double precision,
                    (v_point_json ->> 2)::double precision
                );
                v_z := COALESCE((v_point_json ->> 2)::double precision, 0);
            ELSE
                v_point := ST_MakePoint(
                    (v_point_json ->> 0)::double precision,
                    (v_point_json ->> 1)::double precision
                );
                v_z := 0;
            END IF;
        ELSIF v_point_json ->> 'type' = 'Feature' THEN
            v_point := ST_GeomFromGeoJSON(v_point_json ->> 'geometry');
            v_z := COALESCE(
                (v_point_json -> 'properties' ->> 'z')::double precision,
                (v_point_json -> 'properties' ->> 'height')::double precision,
                ST_Z(v_point),
                0
            );
        ELSE
            v_point := ST_GeomFromGeoJSON(v_point_json::text);
            v_z := COALESCE(ST_Z(v_point), 0);
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            code := 400;
            msg := format('点GeoJSON解析失败：%s，执行时间 %s 秒',
                    SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            INSERT INTO public.gis_error_log(code, msg, sqlstring)
            VALUES (
                code,
                msg,
                v_log_sql
            );

            RETURN QUERY SELECT
                code, msg::varchar,
                false, 'invalid_param'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
            RETURN;
    END;

    IF ST_GeometryType(v_point) NOT IN ('ST_Point') THEN
        code := 400;
        msg := format('GeoJSON必须是Point类型，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    IF ST_CoordDim(v_point) < 3 AND v_z > 0 THEN
        v_point := ST_Force3DZ(v_point, v_z);
    END IF;
    v_point := ST_SetSRID(v_point, 4326);

    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
        v_table_name := 'gis_electric_fence_' || trim(p_project_id);
        SELECT EXISTS (
            SELECT 1 FROM information_schema.tables t
            WHERE t.table_schema = 'public'
              AND t.table_name = v_table_name
        ) INTO v_table_exists;
    ELSE
        v_table_exists := false;
    END IF;

    IF v_table_exists THEN
        v_sql := format('
            WITH fences AS (
                SELECT f.id::varchar AS id, f.geom AS geom, ST_SetSRID(f.geom, 4326) AS calc_geom,
                       COALESCE(f.height, 0)::double precision AS height, ''1''::varchar AS fence_type,
                       f.name::varchar AS electric_name, 1 AS priority
                FROM %I f
                WHERE f.geom IS NOT NULL
                UNION ALL
                SELECT f.id::varchar AS id, f.geom AS geom, ST_SetSRID(f.geom, 4326) AS calc_geom,
                       COALESCE(f.height, 0)::double precision AS height, f.fence_type::varchar AS fence_type,
                       f.name::varchar AS electric_name, 2 AS priority
                FROM bo_electric_fence f
                WHERE f.del_flag = false
                  AND f.status = ''1''
                  AND f.use_enabled = true
                  AND f.geom IS NOT NULL
                  AND ($3 IS NULL OR btrim($3) = '''' OR f.project_id::text = btrim($3))
            )
            SELECT
                200 AS code,
                format(''检测到航点闯入电子围栏缓冲区，check_type=p_inner(点在内部)，执行时间 %%s 秒'', ROUND(EXTRACT(epoch FROM clock_timestamp() - $4)::numeric, 3))::varchar AS msg,
                true AS ischeck,
                ''p_inner''::varchar AS check_type,
                f.id::varchar(32) AS electric_id,
                f.fence_type::varchar AS fence_type,
                f.electric_name::varchar AS electric_name,
                f.geom AS electric_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(f.calc_geom)::json ELSE NULL::json END AS electric_geojson,
                buf.buffer_geom AS electric_buffer_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(buf.buffer_geom)::json ELSE NULL::json END AS electric_buffer_geojson,
                ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )) AS electric_solid_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )))::json ELSE NULL::json END AS electric_solid_geojson
            FROM fences f
            CROSS JOIN LATERAL (
                SELECT CASE
                    WHEN COALESCE($2, 0) = 0 THEN ST_Force2D(f.calc_geom)
                    ELSE ST_Transform(ST_Buffer(ST_Transform(ST_Force2D(f.calc_geom), 3857), COALESCE($2, 0)), 4326)
                END AS buffer_geom
            ) buf
            WHERE ST_Covers(buf.buffer_geom, $1)
              AND (
                  COALESCE(ST_Z($1), 0) = 0
                  OR COALESCE(f.height, 0) = 0
                  OR (COALESCE(ST_Z($1), 0) > 0 AND COALESCE(ST_Z($1), 0) <= f.height)
              )
            ORDER BY f.priority, f.id
            LIMIT 1',
            v_table_name
        );
    ELSE
        v_sql := '
            WITH fences AS (
                SELECT f.id::varchar AS id, f.geom AS geom, ST_SetSRID(f.geom, 4326) AS calc_geom,
                       COALESCE(f.height, 0)::double precision AS height, f.fence_type::varchar AS fence_type,
                       f.name::varchar AS electric_name
                FROM bo_electric_fence f
                WHERE f.del_flag = false
                  AND f.status = ''1''
                  AND f.use_enabled = true
                  AND f.geom IS NOT NULL
                  AND ($3 IS NULL OR btrim($3) = '''' OR f.project_id::text = btrim($3))
            )
            SELECT
                200 AS code,
                format(''检测到航点闯入电子围栏缓冲区，check_type=p_inner(点在内部)，执行时间 %s 秒'', ROUND(EXTRACT(epoch FROM clock_timestamp() - $4)::numeric, 3))::varchar AS msg,
                true AS ischeck,
                ''p_inner''::varchar AS check_type,
                f.id::varchar(32) AS electric_id,
                f.fence_type::varchar AS fence_type,
                f.electric_name::varchar AS electric_name,
                f.geom AS electric_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(f.calc_geom)::json ELSE NULL::json END AS electric_geojson,
                buf.buffer_geom AS electric_buffer_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(buf.buffer_geom)::json ELSE NULL::json END AS electric_buffer_geojson,
                ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )) AS electric_solid_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )))::json ELSE NULL::json END AS electric_solid_geojson
            FROM fences f
            CROSS JOIN LATERAL (
                SELECT CASE
                    WHEN COALESCE($2, 0) = 0 THEN ST_Force2D(f.calc_geom)
                    ELSE ST_Transform(ST_Buffer(ST_Transform(ST_Force2D(f.calc_geom), 3857), COALESCE($2, 0)), 4326)
                END AS buffer_geom
            ) buf
            WHERE ST_Covers(buf.buffer_geom, $1)
              AND (
                  COALESCE(ST_Z($1), 0) = 0
                  OR COALESCE(f.height, 0) = 0
                  OR (COALESCE(ST_Z($1), 0) > 0 AND COALESCE(ST_Z($1), 0) <= f.height)
              )
            ORDER BY f.id
            LIMIT 1';
    END IF;

    RETURN QUERY EXECUTE v_sql USING v_point, p_buffer_radius, p_project_id, v_start_time, p_return_geojson;

    IF NOT FOUND THEN
        RETURN QUERY SELECT
            200, format('航点未闯入任何电子围栏缓冲区，check_type=p_outer(点在外部)，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false, 'p_outer'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        code := 500;
        msg := format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
END;
$$;
COMMENT ON FUNCTION public.gis_electric_fence_check_point_buffer(text, text, double precision, boolean) IS '检测航点缓冲区冲突';

 

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_electric_fence_check_line_buffer');

  
CREATE OR REPLACE FUNCTION public.gis_electric_fence_check_line_buffer(
    p_line_geojson text,
    p_buffer_radius double precision DEFAULT 0,
    p_return_geojson boolean DEFAULT false
)
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    electric_id varchar(32),
    fence_type varchar,
    electric_name varchar,
    electric_geom geometry,
    electric_geojson json,
    electric_buffer_geom geometry,
    electric_buffer_geojson json,
    electric_solid_geom geometry,
    electric_solid_geojson json
)
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
    v_line geometry; -- 存储转换后的线路几何对象
    v_line_json jsonb;
    v_start_time timestamptz := clock_timestamp(); -- 函数开始时间，用于统一返回耗时
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_check_line_buffer(%L, %s, %L);',
        p_line_geojson, COALESCE(p_buffer_radius::text, 'NULL'), p_return_geojson);

    -- ==============================================
    -- 1. GeoJSON线路解析：转换为PostGIS几何对象，强制设326坐标记
    -- ==============================================
    IF p_line_geojson IS NULL OR p_line_geojson = '' THEN
        code := 400;
        msg := format('航线GeoJSON不能为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    BEGIN
        v_line_json := p_line_geojson::jsonb;

        IF jsonb_typeof(v_line_json) = 'array' THEN
            IF jsonb_array_length(v_line_json) < 2 THEN
                RAISE EXCEPTION 'Line coordinate array requires at least two points';
            END IF;
            v_line := ST_GeomFromGeoJSON(
                jsonb_build_object(
                    'type', 'LineString',
                    'coordinates', v_line_json
                )::text
            );
        ELSIF v_line_json ->> 'type' = 'Feature' THEN
            v_line := ST_GeomFromGeoJSON(v_line_json ->> 'geometry');
        ELSE
            v_line := ST_GeomFromGeoJSON(v_line_json::text);
        END IF;

        v_line := ST_SetSRID(v_line, 4326);
    EXCEPTION
        WHEN OTHERS THEN
            code := 400;
            msg := format('航线GeoJSON/坐标数组解析失败：%s，执行时间 %s 秒',
                    SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            INSERT INTO public.gis_error_log(code, msg, sqlstring)
            VALUES (
                code,
                msg,
                v_log_sql
            );

            RETURN QUERY SELECT
                code, msg::varchar,
                false, 'invalid_param'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
            RETURN;
    END;

    -- ==============================================
    -- 2. 核心逻辑：禁飞区和管控区统一按缓冲区/高度逻辑判断
    -- ==============================================
    RETURN QUERY
    SELECT
        res.code,
        format('检测到航线缓冲区闯入电子围栏，check_type=%s，执行时间 %s 秒',
            ct.check_type_msg,
            ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar AS msg,
        true AS ischeck,
        ct.check_type,
        res.electric_id,
        res.fence_type,
        f.name::varchar AS electric_name,
        res.electric_geom,
        res.electric_geojson,
        res.electric_buffer_geom,
        res.electric_buffer_geojson,
        res.electric_solid_geom,
        res.electric_solid_geojson
    FROM bo_electric_fence f,
         -- 计算围栏2D缓冲突
         LATERAL (
             SELECT
                 CASE WHEN p_buffer_radius = 0 THEN ST_SetSRID(f.geom, 4326)
                      ELSE ST_Transform(ST_Buffer(ST_Transform(ST_SetSRID(f.geom,4326),3857), p_buffer_radius), 4326)
                 END AS buf
         ) AS buf_data,
         -- 构建3D立体几何体（拉伸高度
         LATERAL ST_Extrude(ST_Force3D(buf_data.buf), 0, 0, COALESCE(f.height, 0)) AS solid_geom,
         -- 调用已有缓冲函数，获取标准返回结果
         LATERAL gis_electric_fence_buffer(NULL, f.id, p_buffer_radius, p_return_geojson) AS res,
         LATERAL (
             SELECT
                 x.check_type,
                 CASE x.check_type
                     WHEN 'ln_outside' THEN 'ln_outside(线与面：相离)'
                     WHEN 'ln_within' THEN 'ln_within(线与面：包含于)'
                     WHEN 'ln_enters' THEN 'ln_enters(线与面：穿入/穿出)'
                     WHEN 'ln_overlaps' THEN 'ln_overlaps(线与面：重叠)'
                     ELSE 'ln_crosses(线与面：交叉)'
                 END::varchar AS check_type_msg
             FROM (
                 SELECT CASE
                     WHEN ST_CoveredBy(ST_Force2D(v_line), ST_Boundary(buf_data.buf)) THEN 'ln_overlaps'
                     WHEN ST_CoveredBy(ST_Force2D(v_line), buf_data.buf) THEN 'ln_within'
                     WHEN ST_Covers(buf_data.buf, ST_StartPoint(ST_Force2D(v_line))) <> ST_Covers(buf_data.buf, ST_EndPoint(ST_Force2D(v_line))) THEN 'ln_enters'
                     ELSE 'ln_crosses'
                 END::varchar AS check_type
             ) x
         ) AS ct
    WHERE
        f.del_flag = false  -- 仅有效围栏
        AND f.status = '1'  -- 仅启用围栏
        AND f.use_enabled = true -- 仅使用启用围栏
        AND (
            (COALESCE(f.height, 0) = 0 AND ST_Intersects(ST_Force2D(v_line), buf_data.buf))
            OR
            (COALESCE(f.height, 0) > 0 AND ST_3DIntersects(v_line, solid_geom))
        )
    ORDER BY f.id
    LIMIT 1; -- 禁飞区和管控区统一：有高度按3D判断，无高度/0高度按2D判断

    IF NOT FOUND THEN
        RETURN QUERY SELECT
            200, format('航线未闯入任何电子围栏，check_type=ln_outside(线与面：相离)，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false, 'ln_outside'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        code := 500;
        msg := format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
END;
$$;
COMMENT ON FUNCTION public.gis_electric_fence_check_line_buffer(text, double precision, boolean) IS '检测航线缓冲区冲突';

-- 支持项目ID的航线缓冲区检测
CREATE OR REPLACE FUNCTION public.gis_electric_fence_check_line_buffer(
    p_project_id text,
    p_line_geojson text,
    p_buffer_radius double precision DEFAULT 0,
    p_return_geojson boolean DEFAULT false
)
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    electric_id varchar(32),
    fence_type varchar,
    electric_name varchar,
    electric_geom geometry,
    electric_geojson json,
    electric_buffer_geom geometry,
    electric_buffer_geojson json,
    electric_solid_geom geometry,
    electric_solid_geojson json
)
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
    v_line geometry;
    v_line_json jsonb;
    v_table_name text;
    v_table_exists boolean;
    v_sql text;
    v_start_time timestamptz := clock_timestamp();
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_electric_fence_check_line_buffer(%L, %L, %s, %L);',
        p_project_id, p_line_geojson, COALESCE(p_buffer_radius::text, 'NULL'), p_return_geojson);

    IF p_line_geojson IS NULL OR p_line_geojson = '' THEN
        code := 400;
        msg := format('航线GeoJSON不能为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
        RETURN;
    END IF;

    BEGIN
        v_line_json := p_line_geojson::jsonb;

        IF jsonb_typeof(v_line_json) = 'array' THEN
            IF jsonb_array_length(v_line_json) < 2 THEN
                RAISE EXCEPTION 'Line coordinate array requires at least two points';
            END IF;
            v_line := ST_GeomFromGeoJSON(
                jsonb_build_object(
                    'type', 'LineString',
                    'coordinates', v_line_json
                )::text
            );
        ELSIF v_line_json ->> 'type' = 'Feature' THEN
            v_line := ST_GeomFromGeoJSON(v_line_json ->> 'geometry');
        ELSE
            v_line := ST_GeomFromGeoJSON(v_line_json::text);
        END IF;

        v_line := ST_SetSRID(v_line, 4326);
    EXCEPTION
        WHEN OTHERS THEN
            code := 400;
            msg := format('航线GeoJSON/坐标数组解析失败：%s，执行时间 %s 秒',
                    SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            INSERT INTO public.gis_error_log(code, msg, sqlstring)
            VALUES (
                code,
                msg,
                v_log_sql
            );

            RETURN QUERY SELECT
                code, msg::varchar,
                false, 'invalid_param'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
            RETURN;
    END;

    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
        v_table_name := 'gis_electric_fence_' || trim(p_project_id);
        SELECT EXISTS (
            SELECT 1 FROM information_schema.tables t
            WHERE t.table_schema = 'public'
              AND t.table_name = v_table_name
        ) INTO v_table_exists;
    ELSE
        v_table_exists := false;
    END IF;

    IF v_table_exists THEN
        v_sql := format('
            WITH fences AS (
                SELECT f.id::varchar AS id, f.geom AS geom, ST_SetSRID(f.geom, 4326) AS calc_geom,
                       COALESCE(f.height, 0)::double precision AS height, ''1''::varchar AS fence_type,
                       f.name::varchar AS electric_name, 1 AS priority
                FROM %I f
                WHERE f.geom IS NOT NULL
                UNION ALL
                SELECT f.id::varchar AS id, f.geom AS geom, ST_SetSRID(f.geom, 4326) AS calc_geom,
                       COALESCE(f.height, 0)::double precision AS height, f.fence_type::varchar AS fence_type,
                       f.name::varchar AS electric_name, 2 AS priority
                FROM bo_electric_fence f
                WHERE f.del_flag = false
                  AND f.status = ''1''
                  AND f.use_enabled = true
                  AND f.geom IS NOT NULL
                  AND ($2 IS NULL OR btrim($2) = '''' OR f.project_id::text = btrim($2))
            )
            SELECT
                200 AS code,
                format(''检测到航线缓冲区闯入电子围栏，check_type=%%s，执行时间 %%s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $3)::numeric, 3))::varchar AS msg,
                true AS ischeck,
                ct.check_type,
                f.id::varchar(32) AS electric_id,
                f.fence_type::varchar AS fence_type,
                f.electric_name::varchar AS electric_name,
                f.geom AS electric_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(f.calc_geom)::json ELSE NULL::json END AS electric_geojson,
                buf.buffer_geom AS electric_buffer_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(buf.buffer_geom)::json ELSE NULL::json END AS electric_buffer_geojson,
                ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )) AS electric_solid_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )))::json ELSE NULL::json END AS electric_solid_geojson
            FROM fences f
            CROSS JOIN LATERAL (
                SELECT CASE
                    WHEN COALESCE($1, 0) = 0 THEN ST_Force2D(f.calc_geom)
                    ELSE ST_Transform(ST_Buffer(ST_Transform(ST_Force2D(f.calc_geom), 3857), COALESCE($1, 0)), 4326)
                END AS buffer_geom
            ) buf
            CROSS JOIN LATERAL (
                SELECT ST_Extrude(ST_Force3D(buf.buffer_geom), 0, 0, f.height) AS solid_geom
            ) solid
            CROSS JOIN LATERAL (
                SELECT
                    x.check_type,
                    CASE x.check_type
                        WHEN ''ln_outside'' THEN ''ln_outside(线与面：相离)''
                        WHEN ''ln_within'' THEN ''ln_within(线与面：包含于)''
                        WHEN ''ln_enters'' THEN ''ln_enters(线与面：穿入/穿出)''
                        WHEN ''ln_overlaps'' THEN ''ln_overlaps(线与面：重叠)''
                        ELSE ''ln_crosses(线与面：交叉)''
                    END::varchar AS check_type_msg
                FROM (
                    SELECT CASE
                        WHEN ST_CoveredBy(ST_Force2D($4), ST_Boundary(buf.buffer_geom)) THEN ''ln_overlaps''
                        WHEN ST_CoveredBy(ST_Force2D($4), buf.buffer_geom) THEN ''ln_within''
                        WHEN ST_Covers(buf.buffer_geom, ST_StartPoint(ST_Force2D($4))) <> ST_Covers(buf.buffer_geom, ST_EndPoint(ST_Force2D($4))) THEN ''ln_enters''
                        ELSE ''ln_crosses''
                    END::varchar AS check_type
                ) x
            ) ct
            WHERE (
                (COALESCE(f.height, 0) = 0 AND ST_Intersects(ST_Force2D($4), buf.buffer_geom))
                OR
                (COALESCE(f.height, 0) > 0 AND ST_3DIntersects($4, solid.solid_geom))
            )
            ORDER BY f.priority, f.id
            LIMIT 1',
            v_table_name
        );
    ELSE
        v_sql := '
            WITH fences AS (
                SELECT f.id::varchar AS id, f.geom AS geom, ST_SetSRID(f.geom, 4326) AS calc_geom,
                       COALESCE(f.height, 0)::double precision AS height, f.fence_type::varchar AS fence_type,
                       f.name::varchar AS electric_name
                FROM bo_electric_fence f
                WHERE f.del_flag = false
                  AND f.status = ''1''
                  AND f.use_enabled = true
                  AND f.geom IS NOT NULL
                  AND ($2 IS NULL OR btrim($2) = '''' OR f.project_id::text = btrim($2))
            )
            SELECT
                200 AS code,
                format(''检测到航线缓冲区闯入电子围栏，check_type=%s，执行时间 %s 秒'', ct.check_type_msg, ROUND(EXTRACT(epoch FROM clock_timestamp() - $3)::numeric, 3))::varchar AS msg,
                true AS ischeck,
                ct.check_type,
                f.id::varchar(32) AS electric_id,
                f.fence_type::varchar AS fence_type,
                f.electric_name::varchar AS electric_name,
                f.geom AS electric_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(f.calc_geom)::json ELSE NULL::json END AS electric_geojson,
                buf.buffer_geom AS electric_buffer_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(buf.buffer_geom)::json ELSE NULL::json END AS electric_buffer_geojson,
                ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )) AS electric_solid_geom,
                CASE WHEN $5 THEN ST_AsGeoJSON(ST_Multi(ST_Collect(
                    ST_Force3DZ(buf.buffer_geom, 0),
                    ST_Force3DZ(buf.buffer_geom, f.height)
                )))::json ELSE NULL::json END AS electric_solid_geojson
            FROM fences f
            CROSS JOIN LATERAL (
                SELECT CASE
                    WHEN COALESCE($1, 0) = 0 THEN ST_Force2D(f.calc_geom)
                    ELSE ST_Transform(ST_Buffer(ST_Transform(ST_Force2D(f.calc_geom), 3857), COALESCE($1, 0)), 4326)
                END AS buffer_geom
            ) buf
            CROSS JOIN LATERAL (
                SELECT ST_Extrude(ST_Force3D(buf.buffer_geom), 0, 0, f.height) AS solid_geom
            ) solid
            CROSS JOIN LATERAL (
                SELECT
                    x.check_type,
                    CASE x.check_type
                        WHEN ''ln_outside'' THEN ''ln_outside(线与面：相离)''
                        WHEN ''ln_within'' THEN ''ln_within(线与面：包含于)''
                        WHEN ''ln_enters'' THEN ''ln_enters(线与面：穿入/穿出)''
                        WHEN ''ln_overlaps'' THEN ''ln_overlaps(线与面：重叠)''
                        ELSE ''ln_crosses(线与面：交叉)''
                    END::varchar AS check_type_msg
                FROM (
                    SELECT CASE
                        WHEN ST_CoveredBy(ST_Force2D($4), ST_Boundary(buf.buffer_geom)) THEN ''ln_overlaps''
                        WHEN ST_CoveredBy(ST_Force2D($4), buf.buffer_geom) THEN ''ln_within''
                        WHEN ST_Covers(buf.buffer_geom, ST_StartPoint(ST_Force2D($4))) <> ST_Covers(buf.buffer_geom, ST_EndPoint(ST_Force2D($4))) THEN ''ln_enters''
                        ELSE ''ln_crosses''
                    END::varchar AS check_type
                ) x
            ) ct
            WHERE (
                (COALESCE(f.height, 0) = 0 AND ST_Intersects(ST_Force2D($4), buf.buffer_geom))
                OR
                (COALESCE(f.height, 0) > 0 AND ST_3DIntersects($4, solid.solid_geom))
            )
            ORDER BY f.id
            LIMIT 1';
    END IF;

    RETURN QUERY EXECUTE v_sql USING p_buffer_radius, p_project_id, v_start_time, v_line, p_return_geojson;

    IF NOT FOUND THEN
        RETURN QUERY SELECT
            200, format('航线未闯入任何电子围栏缓冲区，check_type=ln_outside(线与面：相离)，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false, 'ln_outside'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        code := 500;
        msg := format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (
            code,
            msg,
            v_log_sql
        );

        RETURN QUERY SELECT
            code, msg::varchar,
            false, 'error'::varchar, NULL::varchar, NULL::varchar, NULL::varchar, NULL::geometry, NULL::json, NULL::geometry, NULL::json, NULL::geometry, NULL::json;
END;
$$;
COMMENT ON FUNCTION public.gis_electric_fence_check_line_buffer(text, text, double precision, boolean) IS '检测航线缓冲区冲突';


 -- =============================================================================
-- 3.1粗三维网格生成.sql
--   gis_generate_3d_grid                    生成项目三维飞行网格
--
-- =============================================================================

-- ==============================================
-- PostgreSQL + PostGIS 无人机GIS系统 完整表结构初始化脚本
--
-- 本文件定位：
--   负责把业务区域转换成项目级粗三维网格，生成 gis_grid_nodes_<project_id> 表。
--   电子围栏、建筑等障碍打标由后续脚本按需写入 block_mask/is_flyable 字段。
--
-- 数据流：
--   GeoJSON面 + 高度范围 + 分辨率
--     -> gis_generate_3d_grid 生成 gis_grid_nodes_<project_id>
--     -> 3.2电子围栏打标记.sql 写入电子围栏阻塞位 block_mask & 1
--     -> 建筑阻塞位 block_mask & 2 由 4.2建筑标记.sql 中的 gis_mark_buildings 写入
--     -> 3.2/3.3 基于 is_flyable=true 的节点做路径规划
--
-- 使用提醒：
--   1. 文件底部包含 SELECT 调用示例，生产环境批量执行前建议确认是否需要注释示例调用。
--   2. gis_generate_3d_grid 会先删除同名项目网格表再重建，适合初始化/重建，不适合在线增量更新。
--   3. 网格表使用 UNLOGGED 提高写入速度，数据库异常重启后可能丢失，需要永久保存时可改为 LOGGED。
--   4. 分辨率越小数据量按三维近似立方增长，100m适合全局粗网格，20/30m建议只在3.3走廊内生成。
--
-- 返回策略：
--   code=200 表示函数正常完成。
--   code=400 表示输入参数非法。
--   code=500 表示执行过程中出现异常。
--   msg 中包含执行时间，以及具体执行说明。
--
-- 功能说明：
-- 1. 依赖PostGIS扩展实现空间数据存储、空间索引、地理计算
-- 2. 本文件只包含项目粗三维网格生成函数
-- 3. 所有表/索引统一采用【先删除、后创建】策略，保证脚本幂等性
-- 4. 生成项目级网格表，支持项目级数据隔离
-- ==============================================

-- ====================================================================================  启用PostGIS空间扩展 ==================================================================================== 
-- 为PostgreSQL提供空间几何对象、空间函数、空间索引、地理计算能力
CREATE EXTENSION IF NOT EXISTS postgis;
-- 提供拓扑结构分析、空间数据校验能力（可选增强扩展）
CREATE EXTENSION IF NOT EXISTS postgis_topology;

-- ==================================================================================== 会话级性能加速设置 ====================================================================================
-- 以下设置仅对当前会话生效，可在生成大规模网格数据时提升性能
SET work_mem = '256MB';                        -- 提高排序和哈希操作的内存
SET maintenance_work_mem = '1GB';             -- 提高维护操作（如CREATE INDEX）的内存
SET max_parallel_maintenance_workers = 8;     -- 允许并行创建索引
SET synchronous_commit = OFF;                  -- 关闭同步提交，减少磁盘IO（风险：系统崩溃可能丢失最近事务）


-- ================================================================= gis_generate_3d_grid 生成三维网格节点表====================================================================
-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_generate_3d_grid');

-- ==============================================
-- 函数名：gis_generate_3d_grid
-- 功能描述：生成三维网格节点表。根据传入的GeoJSON面范围、高程范围和分辨率，
--          自动计算经纬度边界并生成均匀分布的3D网格点，每个点包含空间坐标（经纬度+高度）及其索引。
-- 参数说明：
--   p_project_id           : 项目ID（必传）。表名变为 gis_grid_nodes_<project_id>，实现项目级数据隔离。
--   p_geojson              : GeoJSON面（Polygon），函数自动解析并计算最小/最大经纬度范围。
--   p_min_alt, p_max_alt   : 高程范围（米），例如 50, 280
--   p_resolution           : 网格分辨率（米），表示相邻网格点之间的水平/垂直间距
-- 返回值：标准TABLE结构
--   code        integer     返回码：200成功，400参数错误，500执行异常
--   table_name  text        生成的网格表名
--   msg         text        返回信息/错误提示
--   count       bigint      生成网格点总数量
-- 注意事项：
--   - 函数使用 UNLOGGED 表且关闭自动清理（autovacuum_enabled=off），以最大化写入速度，
--     适用于一次性构建网格场景。生成完成后建议手动执行 ALTER TABLE ... SET LOGGED 永久化。
--   - 经纬度步长通过分辨率除以111000米（赤道附近1度≈111km）近似换算，高纬度地区可能存在轻微形变，
--     如需精确可实际使用中根据平均纬度调整。
--   - 建表后会自动创建 (x,y,z) 复合索引和 geom 空间索引。
--   - 支持直接传入GeoJSON面，自动计算外接矩形范围，无需手动指定经纬度。
-- ==============================================
-- =============================================================================
-- 函数介绍：gis_generate_3d_grid
-- 主要作用：根据项目范围GeoJSON、高度范围和分辨率，生成项目级三维飞行网格节点表。
-- 入参说明：p_project_id 为项目ID；p_geojson 为面范围；p_min_alt/p_max_alt 为高度范围；p_resolution 为网格间距。
-- 返回说明：返回生成表名、状态信息和网格点数量，供后续围栏、建筑标记和路径规划使用。
-- 注意事项：会删除并重建同名网格表；分辨率越小数据量按三维近似立方增长。
-- =============================================================================
 CREATE OR REPLACE FUNCTION gis_generate_3d_grid(
    p_project_id VARCHAR,
    p_geojson TEXT,
    p_min_alt NUMERIC,
    p_max_alt NUMERIC,
    p_resolution INT
) 
RETURNS TABLE (
    code integer,
    table_name text,
    msg text,
    count bigint
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_start_time timestamptz := clock_timestamp(); -- 统计函数总耗时，写入返回msg
    v_table TEXT;                          -- 最终生成的网格表名
    v_idx_prefix TEXT;                     -- 动态索引名前缀，避免项目ID过长导致索引名截断冲突
    v_cnt BIGINT := 0;                     -- 插入网格点的总行数
    v_estimated_count BIGINT := 0;         -- 按外接矩形预估的最大网格点数量
    v_max_grid_count BIGINT := 30000000;   -- 单次生成上限，防止误操作生成超大表
    v_table_regclass REGCLASS;             -- 已存在的目标表对象，存在才删除
    v_lon_max_idx INT;                     -- 经度方向最大网格索引
    v_lat_max_idx INT;                     -- 纬度方向最大网格索引
    v_alt_max_idx INT;                     -- 高度方向最大网格索引
    step_lon DOUBLE PRECISION;             -- 经度方向步长（度）
    step_lat DOUBLE PRECISION;             -- 纬度方向步长（度）
    step_alt DOUBLE PRECISION;             -- 高度方向步长（米）
    v_mid_lat DOUBLE PRECISION;            -- 区域中心纬度，用于修正经度方向步长
    v_lon_meter DOUBLE PRECISION;          -- 当前纬度下1度经度对应米数
    v_geom geometry;                       -- 解析后的GeoJSON几何，仅解析一次
    v_min_lon DOUBLE PRECISION;            -- 从GeoJSON解析出的最小经度
    v_max_lon DOUBLE PRECISION;            -- 从GeoJSON解析出的最大经度
    v_min_lat DOUBLE PRECISION;            -- 从GeoJSON解析出的最小纬度
    v_max_lat DOUBLE PRECISION;            -- 从GeoJSON解析出的最大纬度
    v_log_sql text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_generate_3d_grid(%L, %L, %s, %s, %s);',
        p_project_id, p_geojson, COALESCE(p_min_alt::text, 'NULL'), COALESCE(p_max_alt::text, 'NULL'), COALESCE(p_resolution::text, 'NULL'));

    -- 初始化返回参数，默认成功状态
    code := 200;
    table_name := '';
    msg := '';
    count := 0;

    -- 提高当前事务内CTAS和索引创建的并行倾向，最终是否并行由PostgreSQL优化器决定
    BEGIN
        PERFORM set_config('max_parallel_workers_per_gather', '8', true);
        PERFORM set_config('max_parallel_workers', '16', true);
        PERFORM set_config('parallel_setup_cost', '0', true);
        PERFORM set_config('parallel_tuple_cost', '0', true);
        PERFORM set_config('min_parallel_table_scan_size', '0', true);
        PERFORM set_config('min_parallel_index_scan_size', '0', true);
        PERFORM set_config('jit', 'off', true);
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;

    -- ===================== 从GeoJSON字符串自动解析空间范围 =====================
    -- GeoJSON只解析一次，后续复用几何对象和外接矩形范围
    BEGIN
        v_geom := ST_SetSRID(ST_GeomFromGeoJSON(p_geojson), 4326);
        v_geom := ST_MakeValid(v_geom);

        SELECT
            ST_XMin(v_geom),
            ST_XMax(v_geom),
            ST_YMin(v_geom),
            ST_YMax(v_geom)
        INTO v_min_lon, v_max_lon, v_min_lat, v_max_lat;
    EXCEPTION WHEN OTHERS THEN
        code := 400;
        msg := format('参数错误：GeoJSON格式非法，无法解析空间范围，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END;

    -- ===================== 基础参数合法性校验 =====================
    -- 检查范围参数：最小值不能大于等于最大值
    IF v_min_lon >= v_max_lon OR v_min_lat >= v_max_lat OR p_min_alt >= p_max_alt THEN
        code := 400;
        msg := format('参数错误：最小坐标不能大于等于最大坐标，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    -- 检查分辨率：必须大于0
    IF p_resolution <= 0 THEN
        code := 400;
        msg := format('参数错误：分辨率必须大于0，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF GeometryType(v_geom) NOT IN ('POLYGON', 'MULTIPOLYGON') THEN
        code := 400;
        msg := format('参数错误：GeoJSON必须是Polygon或MultiPolygon面数据，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    -- ===================== 计算网格步长 =====================
    -- 纬度方向约1度=111320米；经度方向按区域中心纬度修正
    v_mid_lat := (v_min_lat + v_max_lat) / 2.0;
    v_lon_meter := 111320.0 * cos(radians(v_mid_lat));

    IF abs(v_lon_meter) < 1 THEN
        code := 400;
        msg := format('参数错误：区域纬度过高，无法按经纬度生成稳定网格，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    step_lat := p_resolution / 111320.0;
    step_lon := p_resolution / v_lon_meter;
    -- 高度步长直接使用分辨率（米）
    step_alt := p_resolution;

    -- ===================== 预估生成数量，避免低分辨率误生成超大表 =====================
    v_lon_max_idx := floor((v_max_lon - v_min_lon) / step_lon)::INT;
    v_lat_max_idx := floor((v_max_lat - v_min_lat) / step_lat)::INT;
    v_alt_max_idx := floor((p_max_alt::DOUBLE PRECISION - p_min_alt::DOUBLE PRECISION) / step_alt)::INT;
    v_estimated_count := (v_lon_max_idx::BIGINT + 1) * (v_lat_max_idx::BIGINT + 1) * (v_alt_max_idx::BIGINT + 1);

    IF v_estimated_count > v_max_grid_count THEN
        code := 400;
        msg := format('参数错误：预计最多生成 %s 个网格点，超过单次上限 %s，请提高分辨率或缩小范围，执行时间 %s 秒', v_estimated_count, v_max_grid_count, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        count := v_estimated_count;
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    -- ===================== 根据项目ID生成表名 =====================
    -- 项目ID为空使用默认项目表名，不为空则拼接项目ID，并过滤非法字符防止SQL注入
    IF p_project_id IS NULL OR p_project_id = '' THEN
        v_table := 'gis_grid_nodes_default';
    ELSE
        v_table := 'gis_grid_nodes_' || regexp_replace(p_project_id, '[^0-9a-zA-Z_]', '', 'g');
    END IF;
    table_name := v_table;
    v_idx_prefix := 'idx_' || substr(md5(v_table), 1, 12);

    -- ===================== 存在旧表才删除，避免无表场景走DROP异常/通知路径 =====================
    SELECT to_regclass(format('%I.%I', current_schema(), v_table)) INTO v_table_regclass;
    IF v_table_regclass IS NOT NULL THEN
        EXECUTE format('DROP TABLE %s CASCADE;', v_table_regclass);
    END IF;
		
    -- ===================== 批量生成三维网格点并建表 =====================
    -- CTAS避免逐行维护SERIAL/主键；先过滤二维面内点，再展开高度层，减少重复空间判断
    EXECUTE format('
        CREATE UNLOGGED TABLE %I
        WITH (autovacuum_enabled = off) AS
        WITH lon_series AS (
            SELECT
                s_lon::INT AS x,
                ($1 + s_lon * $4)::DOUBLE PRECISION AS lon
            FROM generate_series(0, $10) s_lon
            WHERE ($1 + s_lon * $4) <= $7
        ),
        lat_series AS (
            SELECT
                s_lat::INT AS y,
                ($2 + s_lat * $5)::DOUBLE PRECISION AS lat
            FROM generate_series(0, $11) s_lat
            WHERE ($2 + s_lat * $5) <= $8
        ),
        xy_grid AS MATERIALIZED (
            SELECT
                x.x,
                y.y,
                x.lon,
                y.lat,
                ST_SetSRID(ST_MakePoint(x.lon, y.lat), 4326)::geometry(Point,4326) AS geom2d
            FROM lon_series x
            CROSS JOIN lat_series y
            WHERE ST_Covers($13::geometry, ST_SetSRID(ST_MakePoint(x.lon, y.lat), 4326))
        ),
        z_grid AS MATERIALIZED (
            SELECT
                s_alt::INT AS z,
                ($3 + s_alt * $6)::DOUBLE PRECISION AS alt
            FROM generate_series(0, $12) s_alt
            WHERE ($3 + s_alt * $6) <= $9
        )
        SELECT
            ((z.z::BIGINT * ($11::BIGINT + 1) + xy.y::BIGINT) * ($10::BIGINT + 1) + xy.x::BIGINT + 1) AS id,
            xy.x::INT,
            xy.y::INT,
            z.z::INT,
            xy.lon,
            xy.lat,
            z.alt,
            true::BOOLEAN AS is_flyable,
            NULL::VARCHAR(20) AS zone_type,
            0::INT AS block_mask,
            xy.geom2d,
            ST_SetSRID(ST_MakePoint(xy.lon, xy.lat, z.alt), 4326)::geometry(PointZ,4326) AS geom
        FROM xy_grid xy
        CROSS JOIN z_grid z;
    ', v_table)
    USING v_min_lon, v_min_lat, p_min_alt,
          step_lon, step_lat, step_alt,
          v_max_lon, v_max_lat, p_max_alt,
          v_lon_max_idx, v_lat_max_idx, v_alt_max_idx,
          v_geom;
    GET DIAGNOSTICS v_cnt = ROW_COUNT;

    -- ===================== 补充主键、注释和索引 =====================
    EXECUTE format('ALTER TABLE %I ALTER COLUMN id SET NOT NULL;', v_table);
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I PRIMARY KEY (id);', v_table, v_table || '_pkey');

    EXECUTE format('COMMENT ON TABLE %I IS ''项目三维网格节点表：用于电子围栏、建筑、地形、倾斜摄影、DEM等多源打标'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.id IS ''网格节点主键ID，按x/y/z计算生成'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.x IS ''网格X索引，经度方向'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.y IS ''网格Y索引，纬度方向'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.z IS ''网格Z索引，高度方向'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.lon IS ''经度'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.lat IS ''纬度'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.alt IS ''绝对高度或当前系统统一高度基准，单位：米'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.is_flyable IS ''是否可飞：true=可参与路径规划，false=不可通行'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.zone_type IS ''电子围栏区域类型：禁飞区/管控区/适飞区'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.block_mask IS ''阻塞位标记：1电子围栏，2建筑，4地形，8倾斜摄影，16 DEM，32国家空域规则'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.geom2d IS ''二维空间点，WGS84经纬度坐标系'';', v_table);
    EXECUTE format('COMMENT ON COLUMN %I.geom IS ''三维空间点，WGS84经纬度坐标系 + 高度'';', v_table);

    count := v_cnt;

    EXECUTE format('CREATE UNIQUE INDEX IF NOT EXISTS %I ON %I (x, y, z);', v_idx_prefix || '_xyz', v_table);
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (x, y, z) WHERE is_flyable = true;', v_idx_prefix || '_fly_xyz', v_table);
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (x, y) WHERE is_flyable = true;', v_idx_prefix || '_fly_xy', v_table);
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I (block_mask) WHERE block_mask <> 0;', v_idx_prefix || '_mask', v_table);
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I USING GIST(geom2d) WHERE z = 0;', v_idx_prefix || '_geom2d_z0', v_table);
    EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON %I USING GIST(geom);', v_idx_prefix || '_geom', v_table);

    -- ===================== 恢复autovacuum并更新表统计信息 =====================
    EXECUTE format('ALTER TABLE %I SET (autovacuum_enabled = on); ANALYZE %I;', v_table, v_table);

    -- ===================== 执行成功，返回结果 =====================
    msg := format('三维网格生成成功，共生成 %s 个点，执行时间 %s 秒', v_cnt, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    RETURN NEXT;

-- ===================== 全局异常捕获 =====================
EXCEPTION WHEN OTHERS THEN
    code := 500;
    msg := format('生成失败：%s，执行时间 %s 秒', SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    count := 0;
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (code, msg, v_log_sql);
    RETURN NEXT;
END;
$$;
COMMENT ON FUNCTION gis_generate_3d_grid(VARCHAR, TEXT, NUMERIC, NUMERIC, INT) IS '生成项目三维飞行网格';
 
 -- =============================================================================
-- 3.2 电子围栏打标记.sql
--
-- 函数清单：
--   gis_mark_electric_fence                 标记网格电子围栏障碍
--   gis_refresh_electric_fence              刷新网格电子围栏标记
--   gis_refresh_electric_fence_add          新增电子围栏后局部刷新
--   gis_refresh_electric_fence_delete       删除电子围栏后局部刷新
--   gis_refresh_electric_fence_edit         编辑电子围栏后局部刷新
--
-- =============================================================================

-- ============================================================ gis_mark_electric_fence
-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_mark_electric_fence');

-- ==============================================
-- 函数名：gis_mark_electric_fence
-- 功能描述：查询公共电子围栏和项目专属电子围栏，按围栏范围定位网格并写入阻塞标记。
-- 标记规则：bo_electric_fence 写入 block_mask & 1；gis_electric_fence_<project_id> 写入 block_mask & 32。
-- 参数：p_project_id 项目ID；为空时使用默认网格表 gis_grid_nodes。
-- 返回值：标准 TABLE 结构，包含 code、table_name、msg、count。
-- ==============================================
CREATE OR REPLACE FUNCTION gis_mark_electric_fence(p_project_id VARCHAR DEFAULT '')
RETURNS TABLE (code integer, table_name text, msg text, count bigint)
LANGUAGE plpgsql AS $$
DECLARE
    v_start_time timestamptz := clock_timestamp();
    v_table TEXT;
    v_updated_rows BIGINT := 0;
    v_cleared_rows BIGINT := 0;
    v_step_start timestamptz;
    v_extent box3d;
    v_col_exists boolean;
    v_geom_col TEXT;
    v_project_fence_table TEXT;
    v_project_fence_regclass REGCLASS;
    v_log_sql text;
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_mark_electric_fence(%L);', p_project_id);

    -- 根据项目ID确定目标网格表和项目专属围栏表。
    -- p_project_id 为空时操作默认网格表 gis_grid_nodes，只使用公共围栏数据。
    v_step_start := clock_timestamp();
    IF p_project_id = '' OR p_project_id IS NULL THEN
        v_table := 'gis_grid_nodes';
        v_project_fence_table := NULL;
    ELSE
        v_table := 'gis_grid_nodes_' || regexp_replace(p_project_id, '[^0-9a-zA-Z_]', '', 'g');
        v_project_fence_table := 'gis_electric_fence_' || regexp_replace(p_project_id, '[^0-9a-zA-Z_]', '', 'g');
    END IF;
    table_name := v_table;
    RAISE NOTICE '[gis_mark_electric_fence] table: %, elapsed: %', v_table, clock_timestamp() - v_step_start;

    -- 目标网格表必须存在；不存在时直接返回 400 并记录错误日志。
    IF to_regclass(format('%I.%I', current_schema(), v_table)) IS NULL THEN
        code := 400;
        msg := format('参数错误：网格表不存在：%s，执行时间 %s 秒', v_table, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    -- 准备网格标记字段。
    -- zone_type 保存禁飞区/管控区文本；block_mask 保存来源 bit；is_flyable 表示当前网格是否可飞。
    v_step_start := clock_timestamp();
    SELECT EXISTS (
        SELECT 1
        FROM information_schema.columns c
        WHERE c.table_schema = current_schema()
          AND c.table_name = v_table
          AND c.column_name = 'zone_type'
    ) INTO v_col_exists;

    IF NOT v_col_exists THEN
        EXECUTE format('ALTER TABLE %I ADD COLUMN zone_type VARCHAR(20);', v_table);
    END IF;
    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS block_mask INT DEFAULT 0;', v_table);
    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS is_flyable BOOLEAN DEFAULT true;', v_table);

    -- 电子围栏判断只需要平面几何。
    -- 优先使用 geom2d；旧表没有 geom2d 时使用 geom，并为 z=0 平面网格创建空间索引。
    SELECT CASE WHEN EXISTS (
        SELECT 1
        FROM information_schema.columns c
        WHERE c.table_schema = current_schema()
          AND c.table_name = v_table
          AND c.column_name = 'geom2d'
    ) THEN 'geom2d' ELSE 'geom' END INTO v_geom_col;
    EXECUTE format(
        'CREATE INDEX IF NOT EXISTS %I ON %I USING GIST (%I) WHERE z = 0;',
        'idx_' || substr(md5(v_table), 1, 12) || '_' || v_geom_col || '_z0',
        v_table,
        v_geom_col
    );
    RAISE NOTICE '[gis_mark_electric_fence] prepare columns elapsed: %', clock_timestamp() - v_step_start;

    -- 物化本次参与打标的围栏。
    -- 后续网格空间匹配只访问临时表，避免反复扫描业务围栏表。
    v_step_start := clock_timestamp();
    DROP TABLE IF EXISTS tmp_mark_electric_fence;
    CREATE TEMP TABLE tmp_mark_electric_fence (
        id text,
        source_table text,
        priority int,
        zone_type varchar(20),
        max_height double precision,
        geom4326 geometry(Geometry,4326)
    ) ON COMMIT DROP;

    -- 写入公共围栏 bo_electric_fence。
    -- 只处理有效的禁飞区/管控区：del_flag=false、status=1、fence_type in (1,2)。
    -- height 为 NULL 或 0 时表示不限制高度。
    INSERT INTO tmp_mark_electric_fence (
        id, source_table, priority, zone_type, max_height, geom4326
    )
    SELECT
        id::text,
        'bo_electric_fence',
        CASE fence_type WHEN '1' THEN 10 WHEN '2' THEN 20 END AS priority,
        CASE fence_type
            WHEN '1' THEN '禁飞区'
            WHEN '2' THEN '管控区'
        END::varchar(20) AS zone_type,
        NULLIF(COALESCE(height, 0), 0)::double precision AS max_height,
        ST_SetSRID(ST_Force2D(geom), 4326) AS geom4326
    FROM bo_electric_fence
    WHERE del_flag = false
      AND status = '1'
      AND geom IS NOT NULL
      AND fence_type IN ('1','2')
      AND (COALESCE(p_project_id, '') = '' OR project_id::text = p_project_id::text);

    -- 写入项目专属围栏 gis_electric_fence_<project_id>。
    -- 项目表不存在时跳过，不影响公共围栏打标。
    IF v_project_fence_table IS NOT NULL THEN
        SELECT to_regclass(format('%I.%I', current_schema(), v_project_fence_table)) INTO v_project_fence_regclass;
        IF v_project_fence_regclass IS NOT NULL THEN
            EXECUTE format('
                INSERT INTO tmp_mark_electric_fence (
                    id, source_table, priority, zone_type, max_height, geom4326
                )
                SELECT
                    id::text,
                    %L,
                    CASE fence_type WHEN ''1'' THEN 10 WHEN ''2'' THEN 20 END AS priority,
                    CASE fence_type
                        WHEN ''1'' THEN ''禁飞区''
                        WHEN ''2'' THEN ''管控区''
                    END::varchar(20) AS zone_type,
                    NULLIF(COALESCE(height, 0), 0)::double precision AS max_height,
                    ST_SetSRID(ST_Force2D(geom), 4326) AS geom4326
                FROM %s
                WHERE geom IS NOT NULL
                  AND fence_type IN (''1'',''2'')
            ', v_project_fence_table, v_project_fence_regclass);
        END IF;
    END IF;

    CREATE INDEX IF NOT EXISTS idx_tmp_mark_electric_fence_geom ON tmp_mark_electric_fence USING GIST (geom4326);
    ANALYZE tmp_mark_electric_fence;

    SELECT ST_Extent(geom4326) INTO v_extent FROM tmp_mark_electric_fence;

    -- 没有任何有效围栏时，清空网格表中的电子围栏标记。
    -- 只清 bit 1 和 bit 32，不影响其他模块写入的 block_mask 位。
    IF v_extent IS NULL THEN
        EXECUTE format('
            UPDATE %I
            SET
                zone_type = NULL,
                block_mask = COALESCE(block_mask, 0) & ~33,
                is_flyable = ((COALESCE(block_mask, 0) & ~33) = 0)
            WHERE zone_type IS NOT NULL
               OR (COALESCE(block_mask, 0) & 33) <> 0
        ', v_table);
        GET DIAGNOSTICS v_cleared_rows = ROW_COUNT;
        count := v_cleared_rows;
        code := 200;
        msg := format('无有效电子围栏，已清空 %s 条标记，执行时间 %s 秒', v_cleared_rows, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        RETURN NEXT;
        RETURN;
    END IF;
    RAISE NOTICE '[gis_mark_electric_fence] materialize fences elapsed: %', clock_timestamp() - v_step_start;

    -- 计算每个网格点应该写入的最终围栏标记。
    -- 先只拿 z=0 的平面网格做 ST_Intersects，减少三维高度层重复空间计算。
    -- 再通过 x/y 回连所有高度层，并用 max_height 判断高度是否受围栏影响。
    v_step_start := clock_timestamp();
    DROP TABLE IF EXISTS tmp_mark_desired_zone;
    EXECUTE format('
        CREATE TEMP TABLE tmp_mark_desired_zone ON COMMIT DROP AS
        WITH xy_match AS MATERIALIZED (
            SELECT
                n.x,
                n.y,
                f.zone_type,
                f.max_height,
                f.priority,
                f.id AS fence_id,
                CASE WHEN f.source_table = ''bo_electric_fence'' THEN 1 ELSE 32 END AS block_bit
            FROM (
                SELECT DISTINCT x, y, %I AS geom2d
                FROM %I
                WHERE z = 0
                  AND %I && ST_MakeEnvelope($1, $2, $3, $4, 4326)
            ) n
            JOIN tmp_mark_electric_fence f
              ON n.geom2d && f.geom4326
             AND ST_Intersects(n.geom2d, f.geom4326)
        )
        SELECT
            n.id,
            (array_agg(xy.zone_type ORDER BY xy.priority, xy.fence_id))[1]::varchar(20) AS zone_type,
            bit_or(xy.block_bit) AS block_bit
        FROM %I n
        JOIN xy_match xy
          ON n.x = xy.x
         AND n.y = xy.y
        WHERE xy.max_height IS NULL
           OR n.alt <= xy.max_height
        GROUP BY n.id
    ', v_geom_col, v_table, v_geom_col, v_table)
    USING ST_XMin(v_extent), ST_YMin(v_extent), ST_XMax(v_extent), ST_YMax(v_extent);

    CREATE INDEX IF NOT EXISTS idx_tmp_mark_desired_zone_id ON tmp_mark_desired_zone(id);
    ANALYZE tmp_mark_desired_zone;

    -- 写入命中围栏的网格。
    -- 多个围栏重叠时，zone_type 取优先级最高的围栏，block_mask 用 bit_or 合并来源。
    -- IS DISTINCT FROM 避免重复更新未变化的行。
    EXECUTE format('
        UPDATE %I n
        SET
            zone_type = t.zone_type,
            block_mask = (COALESCE(n.block_mask, 0) & ~33) | t.block_bit,
            is_flyable = false
        FROM tmp_mark_desired_zone t
        WHERE n.id = t.id
          AND (
              n.zone_type IS DISTINCT FROM t.zone_type
              OR n.block_mask IS DISTINCT FROM ((COALESCE(n.block_mask, 0) & ~33) | t.block_bit)
              OR n.is_flyable IS DISTINCT FROM false
          )
    ', v_table);
    GET DIAGNOSTICS v_updated_rows = ROW_COUNT;

    -- 清空不再命中任何有效围栏的旧标记。
    -- 这里是全表级清理：凡是不在 tmp_mark_desired_zone 中的电子围栏标记都会被清掉。
    EXECUTE format('
        UPDATE %I n
        SET
            zone_type = NULL,
            block_mask = COALESCE(n.block_mask, 0) & ~33,
            is_flyable = ((COALESCE(n.block_mask, 0) & ~33) = 0)
        WHERE (n.zone_type IS NOT NULL OR (COALESCE(n.block_mask, 0) & 33) <> 0)
          AND NOT EXISTS (SELECT 1 FROM tmp_mark_desired_zone t WHERE t.id = n.id)
    ', v_table);
    GET DIAGNOSTICS v_cleared_rows = ROW_COUNT;

    count := v_updated_rows + v_cleared_rows;
    code := 200;
    msg := format('电子围栏标记完成，更新 %s 条，清空 %s 条，执行时间 %s 秒', v_updated_rows, v_cleared_rows, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    RAISE NOTICE '[gis_mark_electric_fence] update elapsed: %, affected: %', clock_timestamp() - v_step_start, count;
    RETURN NEXT;

EXCEPTION WHEN OTHERS THEN
    code := 500;
    msg := format('执行异常：%s，执行时间 %s 秒', SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    count := 0;
    table_name := v_table;
    RAISE NOTICE '[gis_mark_electric_fence] error: %', SQLERRM;
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (code, msg, v_log_sql);
    RETURN NEXT;
END;
$$;
COMMENT ON FUNCTION gis_mark_electric_fence(VARCHAR) IS '标记网格电子围栏障碍';

-- ============================================================ gis_refresh_electric_fence
-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_refresh_electric_fence');

-- ==============================================
-- 函数名：gis_refresh_electric_fence
-- 功能描述：刷新项目三维网格的电子围栏标记。
-- 参数：
--   p_project_id   项目ID，必填。
--   p_refresh_json 刷新动作 JSON 文本，可选；NULL 表示全量刷新，传 action/fence_id/geojson 表示局部刷新。
--                  对接接口建议调用拆参函数：
--                  gis_refresh_electric_fence_add(project_id, fence_id, geojson_text)
--                  gis_refresh_electric_fence_delete(project_id, fence_id)
--                  gis_refresh_electric_fence_edit(project_id, fence_id, old_geojson_text, new_geojson_text)
-- 返回值：
--   code        integer     返回码：200 成功，400 参数错误，500 执行异常。
--   table_name  text        操作的网格表名。
--   msg         text        结果描述。
--   count       bigint      本次实际更新或清空的记录数。
-- 刷新规则：
--   1. 全量刷新：先清空电子围栏标记，再调用 gis_mark_electric_fence 重新打标。
--   2. 局部刷新：按 fence_id/action/geojson/old_geojson 确定影响范围，只重算范围内禁飞区/管控区网格。
--   3. 删除场景：优先使用 JSON 中的 geojson；未传时按 fence_id 查询旧 geom。
-- ==============================================
CREATE OR REPLACE FUNCTION gis_refresh_electric_fence(
    p_project_id VARCHAR DEFAULT '',
    p_refresh_json text DEFAULT NULL
)
RETURNS TABLE (
    code integer,
    table_name text,
    msg text,
    count bigint
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_table TEXT;
    v_updated_match_rows BIGINT := 0;
    v_cleared_rows BIGINT := 0;
    v_geom_col TEXT;
    v_project_fence_table TEXT;
    v_project_fence_regclass REGCLASS;
    v_scope_extent box3d;
    v_fence_id varchar;
    v_is_partial boolean;
    v_start_time timestamptz := clock_timestamp();
    v_action text;
    v_fence_type text;
    v_new_geojson jsonb;
    v_old_geojson jsonb;
    v_refresh_json jsonb;
    v_scope_geom geometry(Geometry,4326);
    v_log_sql text;                 -- current function call SQL for error logging
BEGIN
    -- 先把外部传入的 JSON 文本解析成 jsonb。
    -- 这里单独捕获异常，是为了让非法 JSON 文本返回标准 TABLE 结构并写入错误日志。
    BEGIN
        v_refresh_json := CASE
            WHEN p_refresh_json IS NULL OR btrim(p_refresh_json) = '' THEN NULL
            ELSE p_refresh_json::jsonb
        END;
    EXCEPTION WHEN OTHERS THEN
        code := 400;
        table_name := '';
        msg := format('参数错误：refresh_json不是合法JSON文本：%s', SQLERRM);
        count := 0;
        v_log_sql := format('SELECT * FROM public.gis_refresh_electric_fence(%L, %L);',
            p_project_id, p_refresh_json);
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END;

    -- 从 JSON 中兼容读取围栏 ID 和动作类型。
    -- 只传 fence_id 时也视为局部刷新；不传 JSON 或 JSON 为空时走全量刷新。
    v_fence_id := COALESCE(
        v_refresh_json ->> 'fence_id',
        v_refresh_json ->> 'fenceId',
        v_refresh_json ->> 'id'
    );
    v_action := lower(COALESCE(
        v_refresh_json ->> 'action',
        v_refresh_json ->> 'operate',
        v_refresh_json ->> 'operation',
        v_refresh_json ->> 'type',
        ''
    ));
    v_is_partial := v_refresh_json IS NOT NULL
        AND (
            COALESCE(NULLIF(btrim(v_fence_id), ''), '') <> ''
            OR COALESCE(NULLIF(btrim(v_action), ''), '') <> ''
        );

    v_log_sql := format('SELECT * FROM public.gis_refresh_electric_fence(%L, %L);',
        p_project_id, p_refresh_json);

    IF p_project_id IS NULL OR btrim(p_project_id) = '' THEN
        code := 400;
        table_name := '';
        msg := format('参数错误：项目ID不能为空，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    v_table := 'gis_grid_nodes_' || regexp_replace(p_project_id, '[^0-9a-zA-Z_]', '', 'g');
    v_project_fence_table := 'gis_electric_fence_' || regexp_replace(p_project_id, '[^0-9a-zA-Z_]', '', 'g');
    table_name := v_table;
    SELECT to_regclass(format('%I.%I', current_schema(), v_project_fence_table)) INTO v_project_fence_regclass;

    IF v_project_fence_regclass IS NULL THEN
        code := 500;
        msg := format('执行异常：电子围栏表不存在：%s，执行时间 %s 秒', v_project_fence_table, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF to_regclass(format('%I.%I', current_schema(), v_table)) IS NULL THEN
        code := 500;
        msg := format('执行异常：网格表不存在：%s，执行时间 %s 秒', v_table, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS zone_type VARCHAR(20);', v_table);
    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS block_mask INT DEFAULT 0;', v_table);
    EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS is_flyable BOOLEAN DEFAULT true;', v_table);

    -- 网格表可能同时存在 geom 和 geom2d。
    -- 电子围栏只做平面范围判断，优先使用 geom2d，没有则回退到 geom。
    SELECT CASE WHEN EXISTS (
        SELECT 1
        FROM information_schema.columns c
        WHERE c.table_schema = current_schema()
          AND c.table_name = v_table
          AND c.column_name = 'geom2d'
    ) THEN 'geom2d' ELSE 'geom' END INTO v_geom_col;
    EXECUTE format(
        'CREATE INDEX IF NOT EXISTS %I ON %I USING GIST (%I) WHERE z = 0;',
        'idx_' || substr(md5(v_table), 1, 12) || '_' || v_geom_col || '_z0',
        v_table,
        v_geom_col
    );

    -- 全量刷新：先清空电子围栏相关标记位，再调用 gis_mark_electric_fence 重新打标。
    -- block_mask 中 bit 1 表示公共围栏，bit 32 表示项目专属围栏；~33 用于只清这两类标记。
    IF NOT v_is_partial THEN
        EXECUTE format('
            UPDATE %I
            SET
                zone_type = NULL,
                block_mask = COALESCE(block_mask, 0) & ~33,
                is_flyable = ((COALESCE(block_mask, 0) & ~33) = 0)
            WHERE zone_type IS NOT NULL
               OR (COALESCE(block_mask, 0) & 33) <> 0
        ', v_table);
        GET DIAGNOSTICS v_cleared_rows = ROW_COUNT;

        RETURN QUERY
        SELECT
            m.code,
            m.table_name,
            format('已清空 %s 条电子围栏标记；%s', v_cleared_rows, m.msg)::text AS msg,
            (v_cleared_rows + COALESCE(m.count, 0))::bigint AS count
        FROM gis_mark_electric_fence(p_project_id) AS m;
        RETURN;
    END IF;

    -- 局部刷新临时表：
    -- tmp_refresh_electric_fence 保存本次刷新范围内仍然有效、需要参与重算的围栏。
    -- tmp_refresh_scope_fence 保存本次需要重算的空间范围，来源可以是新/旧 GeoJSON 或 fence_id 查到的旧 geom。
    DROP TABLE IF EXISTS tmp_refresh_electric_fence;
    CREATE TEMP TABLE tmp_refresh_electric_fence (
        id text,
        source_table text,
        priority int,
        zone_type varchar(20),
        max_height double precision,
        geom4326 geometry(Geometry,4326)
    ) ON COMMIT DROP;

    DROP TABLE IF EXISTS tmp_refresh_scope_fence;
    CREATE TEMP TABLE tmp_refresh_scope_fence (
        geom4326 geometry(Geometry,4326)
    ) ON COMMIT DROP;

    IF v_is_partial THEN
        IF v_refresh_json IS NOT NULL THEN
            -- 解析局部刷新动作。GeoJSON 字段兼容多种命名，方便接口侧传参。
            v_fence_type := COALESCE(v_refresh_json ->> 'fence_type', v_refresh_json ->> 'fenceType');
            v_new_geojson := COALESCE(
                v_refresh_json -> 'geojson',
                v_refresh_json -> 'geom',
                v_refresh_json -> 'geometry',
                v_refresh_json -> 'new_geojson',
                v_refresh_json -> 'newGeom',
                v_refresh_json -> 'new_geometry'
            );
            v_old_geojson := COALESCE(
                v_refresh_json -> 'old_geojson',
                v_refresh_json -> 'oldGeom',
                v_refresh_json -> 'old_geometry'
            );

            IF v_action IN ('add', 'insert', 'create', '新增') THEN
                -- 新增：只需要用新 GeoJSON 作为局部刷新范围。
                -- 围栏数据本身不在这里插入，本函数只负责刷新网格标记。
                IF v_new_geojson IS NULL THEN
                    code := 400;
                    msg := format('参数错误：新增刷新必须提供geojson，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                    count := 0;
                    INSERT INTO public.gis_error_log(code, msg, sqlstring)
                    VALUES (code, msg, v_log_sql);
                    RETURN NEXT;
                    RETURN;
                END IF;

                -- 将 GeoJSON 解析为 4326 平面几何，并校验必须是非空、有效的面。
                BEGIN
                    v_scope_geom := ST_SetSRID(ST_Force2D(ST_GeomFromGeoJSON(CASE WHEN v_new_geojson ->> 'type' = 'Feature' THEN v_new_geojson ->> 'geometry' ELSE v_new_geojson::text END)), 4326);
                EXCEPTION WHEN OTHERS THEN
                    code := 400;
                    msg := format('参数错误：新增geojson格式错误：%s，执行时间 %s 秒', SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                    count := 0;
                    INSERT INTO public.gis_error_log(code, msg, sqlstring)
                    VALUES (code, msg, v_log_sql);
                    RETURN NEXT;
                    RETURN;
                END;

                IF ST_IsEmpty(v_scope_geom) THEN
                    code := 400;
                    msg := format('参数错误：新增geojson不能为空几何，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                    count := 0;
                    INSERT INTO public.gis_error_log(code, msg, sqlstring)
                    VALUES (code, msg, v_log_sql);
                    RETURN NEXT;
                    RETURN;
                END IF;

                IF ST_GeometryType(v_scope_geom) NOT IN ('ST_Polygon', 'ST_MultiPolygon') THEN
                    code := 400;
                    msg := format('参数错误：新增geojson必须是Polygon或MultiPolygon，当前为%s，执行时间 %s 秒', ST_GeometryType(v_scope_geom), ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                    count := 0;
                    INSERT INTO public.gis_error_log(code, msg, sqlstring)
                    VALUES (code, msg, v_log_sql);
                    RETURN NEXT;
                    RETURN;
                END IF;

                IF NOT ST_IsValid(v_scope_geom) THEN
                    code := 400;
                    msg := format('参数错误：新增geojson几何无效：%s，执行时间 %s 秒', ST_IsValidReason(v_scope_geom), ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                    count := 0;
                    INSERT INTO public.gis_error_log(code, msg, sqlstring)
                    VALUES (code, msg, v_log_sql);
                    RETURN NEXT;
                    RETURN;
                END IF;

                INSERT INTO tmp_refresh_scope_fence (geom4326)
                VALUES (v_scope_geom);

            ELSIF v_action IN ('edit', 'update', 'modify', '编辑') THEN
                -- 编辑：用新范围和旧范围的并集做局部刷新。
                -- 这样既能标记新增覆盖区域，也能清理旧范围中不再被覆盖的网格。
                IF v_new_geojson IS NULL THEN
                    code := 400;
                    msg := format('参数错误：编辑刷新必须提供geojson，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                    count := 0;
                    INSERT INTO public.gis_error_log(code, msg, sqlstring)
                    VALUES (code, msg, v_log_sql);
                    RETURN NEXT;
                    RETURN;
                END IF;

                IF v_new_geojson IS NOT NULL THEN
                    -- 新 GeoJSON 负责刷新编辑后的覆盖范围。
                    BEGIN
                        v_scope_geom := ST_SetSRID(ST_Force2D(ST_GeomFromGeoJSON(CASE WHEN v_new_geojson ->> 'type' = 'Feature' THEN v_new_geojson ->> 'geometry' ELSE v_new_geojson::text END)), 4326);
                    EXCEPTION WHEN OTHERS THEN
                        code := 400;
                        msg := format('参数错误：编辑新geojson格式错误：%s，执行时间 %s 秒', SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                        count := 0;
                        INSERT INTO public.gis_error_log(code, msg, sqlstring)
                        VALUES (code, msg, v_log_sql);
                        RETURN NEXT;
                        RETURN;
                    END;
                    IF ST_IsEmpty(v_scope_geom) OR ST_GeometryType(v_scope_geom) NOT IN ('ST_Polygon', 'ST_MultiPolygon') OR NOT ST_IsValid(v_scope_geom) THEN
                        code := 400;
                        msg := format('参数错误：编辑新geojson必须是非空有效Polygon或MultiPolygon，当前类型%s，有效性：%s，执行时间 %s 秒', ST_GeometryType(v_scope_geom), ST_IsValidReason(v_scope_geom), ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                        count := 0;
                        INSERT INTO public.gis_error_log(code, msg, sqlstring)
                        VALUES (code, msg, v_log_sql);
                        RETURN NEXT;
                        RETURN;
                    END IF;
                    INSERT INTO tmp_refresh_scope_fence (geom4326)
                    VALUES (v_scope_geom);
                END IF;

                IF v_old_geojson IS NOT NULL THEN
                    -- 旧 GeoJSON 负责刷新编辑前的覆盖范围，避免旧标记残留。
                    BEGIN
                        v_scope_geom := ST_SetSRID(ST_Force2D(ST_GeomFromGeoJSON(CASE WHEN v_old_geojson ->> 'type' = 'Feature' THEN v_old_geojson ->> 'geometry' ELSE v_old_geojson::text END)), 4326);
                    EXCEPTION WHEN OTHERS THEN
                        code := 400;
                        msg := format('参数错误：编辑旧geojson格式错误：%s，执行时间 %s 秒', SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                        count := 0;
                        INSERT INTO public.gis_error_log(code, msg, sqlstring)
                        VALUES (code, msg, v_log_sql);
                        RETURN NEXT;
                        RETURN;
                    END;
                    IF ST_IsEmpty(v_scope_geom) OR ST_GeometryType(v_scope_geom) NOT IN ('ST_Polygon', 'ST_MultiPolygon') OR NOT ST_IsValid(v_scope_geom) THEN
                        code := 400;
                        msg := format('参数错误：编辑旧geojson必须是非空有效Polygon或MultiPolygon，当前类型%s，有效性：%s，执行时间 %s 秒', ST_GeometryType(v_scope_geom), ST_IsValidReason(v_scope_geom), ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                        count := 0;
                        INSERT INTO public.gis_error_log(code, msg, sqlstring)
                        VALUES (code, msg, v_log_sql);
                        RETURN NEXT;
                        RETURN;
                    END IF;
                    INSERT INTO tmp_refresh_scope_fence (geom4326)
                    VALUES (v_scope_geom);
                END IF;

            ELSIF v_action IN ('delete', 'remove', 'del', '删除') THEN
                -- 删除：如果调用方传了旧 GeoJSON，则优先用旧 GeoJSON 确定刷新范围。
                -- 如果没传，后面会按 fence_id 从围栏表中查询旧 geom。
                IF v_new_geojson IS NOT NULL THEN
                    BEGIN
                        v_scope_geom := ST_SetSRID(ST_Force2D(ST_GeomFromGeoJSON(CASE WHEN v_new_geojson ->> 'type' = 'Feature' THEN v_new_geojson ->> 'geometry' ELSE v_new_geojson::text END)), 4326);
                    EXCEPTION WHEN OTHERS THEN
                        code := 400;
                        msg := format('参数错误：删除geojson格式错误：%s，执行时间 %s 秒', SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                        count := 0;
                        INSERT INTO public.gis_error_log(code, msg, sqlstring)
                        VALUES (code, msg, v_log_sql);
                        RETURN NEXT;
                        RETURN;
                    END;
                    IF ST_IsEmpty(v_scope_geom) OR ST_GeometryType(v_scope_geom) NOT IN ('ST_Polygon', 'ST_MultiPolygon') OR NOT ST_IsValid(v_scope_geom) THEN
                        code := 400;
                        msg := format('参数错误：删除geojson必须是非空有效Polygon或MultiPolygon，当前类型%s，有效性：%s，执行时间 %s 秒', ST_GeometryType(v_scope_geom), ST_IsValidReason(v_scope_geom), ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                        count := 0;
                        INSERT INTO public.gis_error_log(code, msg, sqlstring)
                        VALUES (code, msg, v_log_sql);
                        RETURN NEXT;
                        RETURN;
                    END IF;
                    INSERT INTO tmp_refresh_scope_fence (geom4326)
                    VALUES (v_scope_geom);
                END IF;
            ELSE
                code := 400;
                msg := format('参数错误：refresh_json.action必须是新增/编辑/删除，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                count := 0;
                INSERT INTO public.gis_error_log(code, msg, sqlstring)
                VALUES (code, msg, v_log_sql);
                RETURN NEXT;
                RETURN;
            END IF;

            IF v_fence_type IS NOT NULL AND v_fence_type NOT IN ('1', '2', '3') THEN
                code := 400;
                msg := format('参数错误：fence_type必须是1/2/3，执行时间 %s 秒', ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
                count := 0;
                INSERT INTO public.gis_error_log(code, msg, sqlstring)
                VALUES (code, msg, v_log_sql);
                RETURN NEXT;
                RETURN;
            END IF;
        END IF;

        -- 兼容只传 fence_id 的局部刷新。
        -- 从公共围栏表和项目专属围栏表查旧 geom，一并加入刷新范围。
        INSERT INTO tmp_refresh_scope_fence (geom4326)
        SELECT ST_SetSRID(ST_Force2D(geom), 4326) AS geom4326
        FROM bo_electric_fence
        WHERE id::text = v_fence_id::text
          AND geom IS NOT NULL
          AND (COALESCE(p_project_id, '') = '' OR project_id::TEXT = p_project_id::TEXT);

        IF v_project_fence_table IS NOT NULL AND v_project_fence_regclass IS NOT NULL THEN
            EXECUTE format('
                INSERT INTO tmp_refresh_scope_fence (geom4326)
                SELECT ST_SetSRID(ST_Force2D(geom), 4326) AS geom4326
                FROM %s
                WHERE id::text = $1
                  AND geom IS NOT NULL
            ', v_project_fence_regclass)
            USING v_fence_id;
        END IF;

        -- 用所有范围几何的外包框作为本次局部刷新范围。
        -- 如果范围为空，说明既没有有效 GeoJSON，也没能按 fence_id 找到旧 geom。
        SELECT ST_Extent(geom4326) INTO v_scope_extent FROM tmp_refresh_scope_fence;

        IF v_scope_extent IS NULL THEN
            code := 400;
            msg := format('参数错误：未找到可刷新的电子围栏或围栏无geom：%s，执行时间 %s 秒', v_fence_id, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            count := 0;
            INSERT INTO public.gis_error_log(code, msg, sqlstring)
            VALUES (code, msg, v_log_sql);
            RETURN NEXT;
            RETURN;
        END IF;
    END IF;

    -- 收集本次刷新范围内仍然有效的公共围栏。
    -- 后续不是简单清空旧范围，而是根据这些有效围栏重新计算网格最终标记，避免误清重叠围栏。
    INSERT INTO tmp_refresh_electric_fence (
        id, source_table, priority, zone_type, max_height, geom4326
    )
    SELECT
        id::text,
        'bo_electric_fence',
        CASE fence_type WHEN '1' THEN 10 WHEN '2' THEN 20 END AS priority,
        CASE fence_type
            WHEN '1' THEN '禁飞区'
            WHEN '2' THEN '管控区'
        END::varchar(20) AS zone_type,
        NULLIF(COALESCE(height, 0), 0)::double precision AS max_height,
        ST_SetSRID(ST_Force2D(geom), 4326) AS geom4326
    FROM bo_electric_fence
    WHERE del_flag = false
      AND status = '1'
      AND geom IS NOT NULL
      AND fence_type IN ('1', '2')
      AND (COALESCE(p_project_id, '') = '' OR project_id::TEXT = p_project_id::TEXT)
      AND (
          NOT v_is_partial
          OR ST_SetSRID(ST_Force2D(geom), 4326) && ST_MakeEnvelope(
              ST_XMin(v_scope_extent), ST_YMin(v_scope_extent),
              ST_XMax(v_scope_extent), ST_YMax(v_scope_extent), 4326
          )
      );

    IF v_project_fence_table IS NOT NULL THEN
        IF v_project_fence_regclass IS NOT NULL THEN
            -- 收集本次刷新范围内仍然有效的项目专属围栏。
            -- source_table 用于区分 block_mask 写 bit 1 还是 bit 32。
            EXECUTE format('
                INSERT INTO tmp_refresh_electric_fence (
                    id, source_table, priority, zone_type, max_height, geom4326
                )
                SELECT
                    id::text,
                    %L,
                    CASE fence_type WHEN ''1'' THEN 10 WHEN ''2'' THEN 20 END AS priority,
                    CASE fence_type
                        WHEN ''1'' THEN ''禁飞区''
                        WHEN ''2'' THEN ''管控区''
                    END::varchar(20) AS zone_type,
                    NULLIF(COALESCE(height, 0), 0)::double precision AS max_height,
                    ST_SetSRID(ST_Force2D(geom), 4326) AS geom4326
                FROM %s
                WHERE geom IS NOT NULL
                  AND fence_type IN (''1'',''2'')
                  AND (
                      NOT $1
                      OR ST_SetSRID(ST_Force2D(geom), 4326) && ST_MakeEnvelope($2, $3, $4, $5, 4326)
                  )
            ', v_project_fence_table, v_project_fence_regclass)
            USING v_is_partial,
                  CASE WHEN v_scope_extent IS NULL THEN NULL ELSE ST_XMin(v_scope_extent) END,
                  CASE WHEN v_scope_extent IS NULL THEN NULL ELSE ST_YMin(v_scope_extent) END,
                  CASE WHEN v_scope_extent IS NULL THEN NULL ELSE ST_XMax(v_scope_extent) END,
                  CASE WHEN v_scope_extent IS NULL THEN NULL ELSE ST_YMax(v_scope_extent) END;
        END IF;
    END IF;

    CREATE INDEX IF NOT EXISTS idx_tmp_refresh_electric_fence_geom ON tmp_refresh_electric_fence USING GIST (geom4326);
    ANALYZE tmp_refresh_electric_fence;

    IF NOT v_is_partial THEN
        SELECT ST_Extent(geom4326) INTO v_scope_extent FROM tmp_refresh_electric_fence;
    END IF;

    -- 如果当前没有任何有效围栏，则清空电子围栏相关标记。
    IF v_scope_extent IS NULL THEN
        EXECUTE format('
            UPDATE %I
            SET
                zone_type = NULL,
                block_mask = COALESCE(block_mask, 0) & ~33,
                is_flyable = ((COALESCE(block_mask, 0) & ~33) = 0)
            WHERE zone_type IS NOT NULL
               OR (COALESCE(block_mask, 0) & 33) <> 0
        ', v_table);
        GET DIAGNOSTICS v_cleared_rows = ROW_COUNT;
        count := v_cleared_rows;
        code := 200;
        msg := format('无有效电子围栏，已清空 %s 条标记，执行时间 %s 秒', v_cleared_rows, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        RETURN NEXT;
        RETURN;
    END IF;

    -- 先缩小到刷新范围内的 z=0 平面网格点。
    -- 后续再通过 x/y 关联所有高度层，避免每个高度层重复做空间相交判断。
    DROP TABLE IF EXISTS tmp_refresh_scope_xy;
    EXECUTE format('
        CREATE TEMP TABLE tmp_refresh_scope_xy ON COMMIT DROP AS
        SELECT DISTINCT x, y, %I AS geom2d
        FROM %I
        WHERE z = 0
          AND %I && ST_MakeEnvelope($1, $2, $3, $4, 4326)
    ', v_geom_col, v_table, v_geom_col)
    USING ST_XMin(v_scope_extent), ST_YMin(v_scope_extent), ST_XMax(v_scope_extent), ST_YMax(v_scope_extent);

    CREATE INDEX IF NOT EXISTS idx_tmp_refresh_scope_xy ON tmp_refresh_scope_xy (x, y);
    ANALYZE tmp_refresh_scope_xy;

    -- 计算每个网格点最终应该拥有的电子围栏标记。
    -- 多个围栏重叠时，按 priority 和 fence_id 取最高优先级 zone_type，同时 bit_or 合并来源标记位。
    DROP TABLE IF EXISTS tmp_desired_zone;
    EXECUTE format('
        CREATE TEMP TABLE tmp_desired_zone ON COMMIT DROP AS
        WITH xy_match AS MATERIALIZED (
            SELECT
                n.x,
                n.y,
                f.zone_type,
                f.max_height,
                f.priority,
                f.id AS fence_id,
                CASE WHEN f.source_table = ''bo_electric_fence'' THEN 1 ELSE 32 END AS block_bit
            FROM (
                SELECT x, y, geom2d
                FROM tmp_refresh_scope_xy
            ) n
            JOIN tmp_refresh_electric_fence f
              ON n.geom2d && f.geom4326
             AND ST_Intersects(n.geom2d, f.geom4326)
        )
        SELECT
            n.id,
            (array_agg(xy.zone_type ORDER BY xy.priority, xy.fence_id))[1]::varchar(20) AS zone_type,
            bit_or(xy.block_bit) AS block_bit
        FROM %I n
        JOIN xy_match xy
          ON n.x = xy.x
         AND n.y = xy.y
        WHERE xy.max_height IS NULL
           OR n.alt <= xy.max_height
        GROUP BY n.id
    ', v_table);

    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_tmp_desired_zone_id ON tmp_desired_zone(id);';
    EXECUTE 'ANALYZE tmp_desired_zone;';

    -- 写入仍然命中有效围栏的网格。
    -- WHERE 中使用 IS DISTINCT FROM，只更新实际发生变化的行，减少无效写入。
    EXECUTE format('
        UPDATE %I n
        SET
            zone_type = t.zone_type,
            block_mask = (COALESCE(n.block_mask, 0) & ~33) | t.block_bit,
            is_flyable = false
        FROM tmp_desired_zone t
        WHERE n.id = t.id
          AND (
              n.zone_type IS DISTINCT FROM t.zone_type
              OR n.block_mask IS DISTINCT FROM ((COALESCE(n.block_mask, 0) & ~33) | t.block_bit)
              OR n.is_flyable IS DISTINCT FROM false
          )
    ', v_table);
    GET DIAGNOSTICS v_updated_match_rows = ROW_COUNT;

    -- 清空刷新范围内已经不再命中任何有效围栏的网格。
    -- 只清电子围栏相关 bit，不影响建筑物、DEM 等其他可能占用的 block_mask 位。
    EXECUTE format('
        UPDATE %I n
        SET
            zone_type = NULL,
            block_mask = COALESCE(n.block_mask, 0) & ~33,
            is_flyable = ((COALESCE(n.block_mask, 0) & ~33) = 0)
        WHERE (n.zone_type IS NOT NULL OR (COALESCE(n.block_mask, 0) & 33) <> 0)
          AND EXISTS (SELECT 1 FROM tmp_refresh_scope_xy s WHERE s.x = n.x AND s.y = n.y)
          AND NOT EXISTS (SELECT 1 FROM tmp_desired_zone t WHERE t.id = n.id)
    ', v_table);
    GET DIAGNOSTICS v_cleared_rows = ROW_COUNT;

    count := v_updated_match_rows + v_cleared_rows;
    code := 200;
    msg := CASE
        WHEN v_is_partial THEN format('按围栏 %s 局部刷新完成，更新 %s 条，清空 %s 条，执行时间 %s 秒', v_fence_id, v_updated_match_rows, v_cleared_rows, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
        ELSE format('按 bo_electric_fence 当前有效数据和项目专属围栏刷新完成，更新 %s 条，清空 %s 条，执行时间 %s 秒', v_updated_match_rows, v_cleared_rows, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
    END;
    RETURN NEXT;

EXCEPTION WHEN OTHERS THEN
    code := 500;
    table_name := v_table;
    msg := format('刷新失败：%s，执行时间 %s 秒', SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    count := 0;
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (code, msg, v_log_sql);
    RETURN NEXT;
END;
$$;
COMMENT ON FUNCTION gis_refresh_electric_fence(VARCHAR, text) IS '刷新网格电子围栏标记';

-- ============================================================ gis_refresh_electric_fence_add
SELECT gis_drop_function('gis_refresh_electric_fence_add');

-- 函数名：gis_refresh_electric_fence_add
-- 功能描述：新增电子围栏后，根据新围栏 GeoJSON 做局部刷新。
-- 参数：
--   p_project_id 项目ID，必填。
--   p_fence_id   围栏ID，必填。
--   p_geojson    新围栏 GeoJSON 文本，必填。
CREATE OR REPLACE FUNCTION gis_refresh_electric_fence_add(
    p_project_id VARCHAR,
    p_fence_id VARCHAR,
    p_geojson text
)
RETURNS TABLE (
    code integer,
    table_name text,
    msg text,
    count bigint
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_log_sql text := format('SELECT * FROM public.gis_refresh_electric_fence_add(%L, %L, %L);', p_project_id, p_fence_id, p_geojson);
BEGIN
    -- 对接层拆参函数：先校验必填参数，再组装底层 refresh_json。
    -- GeoJSON 文本在这里先转 jsonb，非法 JSON 会进入异常捕获并写日志。
    IF p_project_id IS NULL OR btrim(p_project_id) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：项目ID不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_fence_id IS NULL OR btrim(p_fence_id) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：围栏ID不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_geojson IS NULL OR btrim(p_geojson) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：新增围栏GeoJSON不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT *
    FROM gis_refresh_electric_fence(
        p_project_id,
        jsonb_build_object(
            'action', 'add',
            'fence_id', p_fence_id,
            'geojson', p_geojson::jsonb
        )::text
    );
EXCEPTION WHEN OTHERS THEN
    code := 400;
    table_name := '';
    msg := format('参数错误：新增围栏刷新参数异常：%s', SQLERRM);
    count := 0;
    INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
    RETURN NEXT;
END;
$$;
COMMENT ON FUNCTION gis_refresh_electric_fence_add(VARCHAR, VARCHAR, text) IS '新增电子围栏后局部刷新网格电子围栏标记';

-- ============================================================ gis_refresh_electric_fence_delete
SELECT gis_drop_function('gis_refresh_electric_fence_delete');

-- 函数名：gis_refresh_electric_fence_delete
-- 功能描述：删除电子围栏后，根据围栏ID查询旧 geom 并做局部刷新。
-- 参数：
--   p_project_id 项目ID，必填。
--   p_fence_id   围栏ID，必填。
CREATE OR REPLACE FUNCTION gis_refresh_electric_fence_delete(
    p_project_id VARCHAR,
    p_fence_id VARCHAR
)
RETURNS TABLE (
    code integer,
    table_name text,
    msg text,
    count bigint
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_log_sql text := format('SELECT * FROM public.gis_refresh_electric_fence_delete(%L, %L);', p_project_id, p_fence_id);
BEGIN
    -- 删除刷新只需要项目ID和围栏ID。
    -- 底层会按 fence_id 查旧 geom 作为刷新范围，然后重算该范围内的网格标记。
    IF p_project_id IS NULL OR btrim(p_project_id) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：项目ID不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_fence_id IS NULL OR btrim(p_fence_id) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：围栏ID不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT *
    FROM gis_refresh_electric_fence(
        p_project_id,
        jsonb_build_object(
            'action', 'delete',
            'fence_id', p_fence_id
        )::text
    );
EXCEPTION WHEN OTHERS THEN
    code := 500;
    table_name := '';
    msg := format('删除围栏刷新失败：%s', SQLERRM);
    count := 0;
    INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
    RETURN NEXT;
END;
$$;
COMMENT ON FUNCTION gis_refresh_electric_fence_delete(VARCHAR, VARCHAR) IS '删除电子围栏后按围栏ID局部刷新网格电子围栏标记';

-- ============================================================ gis_refresh_electric_fence_edit
SELECT gis_drop_function('gis_refresh_electric_fence_edit');

-- 函数名：gis_refresh_electric_fence_edit
-- 功能描述：编辑电子围栏后，根据旧 GeoJSON 和新 GeoJSON 的共同范围做局部刷新。
-- 参数：
--   p_project_id  项目ID，必填。
--   p_fence_id    围栏ID，必填。
--   p_old_geojson 旧围栏 GeoJSON 文本，必填。
--   p_new_geojson 新围栏 GeoJSON 文本，必填。
CREATE OR REPLACE FUNCTION gis_refresh_electric_fence_edit(
    p_project_id VARCHAR,
    p_fence_id VARCHAR,
    p_old_geojson text,
    p_new_geojson text
)
RETURNS TABLE (
    code integer,
    table_name text,
    msg text,
    count bigint
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_log_sql text := format('SELECT * FROM public.gis_refresh_electric_fence_edit(%L, %L, %L, %L);', p_project_id, p_fence_id, p_old_geojson, p_new_geojson);
BEGIN
    -- 编辑刷新必须同时提供旧 GeoJSON 和新 GeoJSON。
    -- 旧范围用于清理旧标记，新范围用于写入新标记，二者共同决定局部刷新范围。
    IF p_project_id IS NULL OR btrim(p_project_id) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：项目ID不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_fence_id IS NULL OR btrim(p_fence_id) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：围栏ID不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_old_geojson IS NULL OR btrim(p_old_geojson) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：旧围栏GeoJSON不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_new_geojson IS NULL OR btrim(p_new_geojson) = '' THEN
        code := 400;
        table_name := '';
        msg := '参数错误：新围栏GeoJSON不能为空';
        count := 0;
        INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
        RETURN NEXT;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT *
    FROM gis_refresh_electric_fence(
        p_project_id,
        jsonb_build_object(
            'action', 'edit',
            'fence_id', p_fence_id,
            'old_geojson', p_old_geojson::jsonb,
            'geojson', p_new_geojson::jsonb
        )::text
    );
EXCEPTION WHEN OTHERS THEN
    code := 400;
    table_name := '';
    msg := format('参数错误：编辑围栏刷新参数异常：%s', SQLERRM);
    count := 0;
    INSERT INTO public.gis_error_log(code, msg, sqlstring) VALUES (code, msg, v_log_sql);
    RETURN NEXT;
END;
$$;
COMMENT ON FUNCTION gis_refresh_electric_fence_edit(VARCHAR, VARCHAR, text, text) IS '编辑电子围栏后按旧新范围局部刷新网格电子围栏标记';

 -- =============================================================================
-- 3.2线路自动规划.sql
--   gis_linestring_length_m                 计算三维航线实际长度
--   gis_flight_point_in_fence               判断航点是否在围栏
--   gis_flight_line_intersects_fence        判断航线是否穿越围栏
--   gis_astar_3d_flight                     规划单段三维避障航线
--   gis_astar_3d_flight_plan                单段航线自动规划接口
--   gis_flight_paths_plan                   多点航线自动分段规划
--
-- =============================================================================

-- =============================================================================
-- 2026-07-13 维护备注：航线平滑与直升直降规则
-- 1. p_height_mode = 0 且起点高度 != 安全高度时，必须保留：
--      起点真实高度 -> 起点安全高度
-- 2. p_height_mode = 0 且终点高度 != 安全高度时，必须保留：
--      终点安全高度 -> 终点真实高度
-- 3. 起点/终点高度都等于安全高度时，若直线不穿越围栏，允许最终简化为：
--      起点 -> 终点
-- 4. 直线兜底、A*失败兜底、异常兜底、长距离快速直线返回，都必须按同一套直升直降规则构造航线。
-- 5. 原始航线 path_line 和平滑航线 smooth_path_line 在返回/入库前会删除连续重复点；
--    仅删除 XYZ 都相同的重复点，同经纬度但高度不同的直升直降点必须保留。
-- =============================================================================

-- ==============================================
-- 3.2 线路自动规划：全局网格 A* 粗规划函数
--
-- 本文件定位：
--   基于 3.1 生成的项目级网格表 gis_grid_nodes_<project_id> 做三维 A* 路径规划，
--   并把结果写入 gis_flight_paths。它适合使用 100m 左右的全局粗网格进行快速规划。
--
-- 与 3.1 / 3.3 的关系：
--   1. 3.1 负责生成网格和障碍打标，输出 is_flyable=true/false。
--   2. 3.2 读取可飞网格做全局路径搜索，返回 code/msg + 航线字段。
--   3. 3.3 会先调用本文件的 gis_astar_3d_flight_plan 得到粗航线，
--      再沿粗航线走廊生成 20/30m 精细网格做二次规划。
--
-- 返回策略：
--   code=200 表示函数正常完成。
--   code=400 表示输入参数非法。
--   code=500 表示执行过程中出现异常。
--   msg 中包含执行时间，以及具体执行说明，便于接口侧记录耗时和定位慢点。
--
-- 维护提醒：
--   本文件的核心函数使用 RETURNS TABLE，返回列 id/project_id/del_flag 等会成为 PL/pgSQL 变量。
--   函数体内静态 SQL 必须使用表别名访问同名字段，避免 "column reference is ambiguous"。
-- ==============================================
-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_linestring_length_m');
-- =============================================================================
-- 函数介绍：gis_linestring_length_m
-- 主要作用：计算LineString或LineStringZ航线的近似三维实际长度，单位米。
-- 入参说明：p_line 为PostGIS线几何，支持带Z高度的三维航线。
-- 返回说明：返回整条线各相邻点段长度累加值，二维距离按经纬度近似换算，高度差按米计算。
-- 注意事项：该函数用于航线距离统计，适合小范围无人机航线；超大范围需改用更精确测地线算法。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_linestring_length_m(p_line geometry)
RETURNS DOUBLE PRECISION AS $$
    WITH pts AS (
        SELECT (dp).path[1] AS idx, (dp).geom AS geom
        FROM ST_DumpPoints(p_line) AS dp
    ),
    segs AS (
        SELECT
            a.geom AS geom_a,
            b.geom AS geom_b,
            RADIANS((ST_Y(a.geom) + ST_Y(b.geom)) / 2.0) AS avg_lat_rad
        FROM pts a
        JOIN pts b ON b.idx = a.idx + 1
    )
    SELECT COALESCE(SUM(
        SQRT(
            POWER((ST_X(geom_b) - ST_X(geom_a)) * 111000.0 * COS(avg_lat_rad), 2)
            + POWER((ST_Y(geom_b) - ST_Y(geom_a)) * 111000.0, 2)
            + POWER(COALESCE(ST_Z(geom_b), 0) - COALESCE(ST_Z(geom_a), 0), 2)
        )
    ), 0)::DOUBLE PRECISION
    FROM segs;
$$ LANGUAGE SQL IMMUTABLE STRICT;
COMMENT ON FUNCTION gis_linestring_length_m(geometry) IS '计算三维航线实际长度';

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_linestring_remove_duplicate_points');
-- =============================================================================
-- 函数介绍：gis_linestring_remove_duplicate_points
-- 主要作用：删除LineString航线中的连续重复点。
-- 返回说明：仅当连续点XYZ都相同才删除；同经纬度但高度不同的直升直降点会保留。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_linestring_remove_duplicate_points(p_line geometry)
RETURNS geometry
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_clean geometry;
    v_count integer;
BEGIN
    IF p_line IS NULL OR ST_IsEmpty(p_line) OR GeometryType(p_line) NOT IN ('LINESTRING', 'LINESTRINGZ') THEN
        RETURN p_line;
    END IF;

    WITH pts AS (
        SELECT
            (dp).path[1] AS idx,
            (dp).geom AS geom,
            lag((dp).geom) OVER (ORDER BY (dp).path[1]) AS prev_geom
        FROM ST_DumpPoints(p_line) AS dp
    ),
    kept AS (
        SELECT idx, geom
        FROM pts
        WHERE prev_geom IS NULL
           OR abs(ST_X(geom) - ST_X(prev_geom)) > 0.000000001
           OR abs(ST_Y(geom) - ST_Y(prev_geom)) > 0.000000001
           OR abs(COALESCE(ST_Z(geom), 0) - COALESCE(ST_Z(prev_geom), 0)) > 0.000000001
    )
    SELECT ST_SetSRID(ST_MakeLine(geom ORDER BY idx), ST_SRID(p_line)), count(*)
    INTO v_clean, v_count
    FROM kept;

    IF COALESCE(v_count, 0) < 2 THEN
        RETURN p_line;
    END IF;

    RETURN v_clean;
END;
$$;
COMMENT ON FUNCTION gis_linestring_remove_duplicate_points(geometry) IS '删除LineString连续重复点，保留同经纬度不同高度的直升直降点';

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_flight_point_in_fence');
-- =============================================================================
-- 函数介绍：gis_flight_point_in_fence
-- 主要作用：判断单个航点是否落入禁飞区或管控区。
-- 入参说明：p_point 为航点几何；p_project_id 用于匹配全局电子围栏和项目国家规定表。
-- 返回说明：返回boolean，true表示航点命中不可通行围栏，false表示未命中。
-- 注意事项：同时检查 bo_electric_fence 和 gis_electric_fence_<project_id>。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_flight_point_in_fence(
    p_point geometry,
    p_project_id varchar DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
AS $$
DECLARE
    v_hit boolean := false;
    v_project_fence_table text;
    v_project_fence_has_height boolean := false;
BEGIN
    IF p_point IS NULL THEN
        RETURN false;
    END IF;

    IF to_regclass('public.bo_electric_fence') IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1
            FROM public.bo_electric_fence f
            WHERE f.geom IS NOT NULL
              AND f.fence_type IN ('1', '2')
              AND f.status = '1'
              AND f.del_flag = false
              AND f.use_enabled = true
              AND (COALESCE(p_project_id, '') = '' OR f.project_id::text = p_project_id::text)
              AND (
                  COALESCE(f.height, 0) = 0
                  OR COALESCE(ST_Z(p_point), 0) <= f.height
              )
              AND ST_Covers(
                  ST_SetSRID(ST_MakeValid(ST_Force2D(f.geom)), 4326),
                  ST_Force2D(p_point)
              )
        ) INTO v_hit;

        IF v_hit THEN
            RETURN true;
        END IF;
    END IF;

    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
        v_project_fence_table := 'gis_electric_fence_' || regexp_replace(trim(p_project_id), '[^0-9a-zA-Z_]', '', 'g');
        IF to_regclass(format('%I.%I', 'public', v_project_fence_table)) IS NOT NULL THEN
            SELECT EXISTS(
                SELECT 1
                FROM information_schema.columns
                WHERE table_schema = 'public'
                  AND table_name = v_project_fence_table
                  AND column_name = 'height'
            ) INTO v_project_fence_has_height;

            EXECUTE format('
                SELECT EXISTS(
                    SELECT 1
                    FROM %I.%I f
                    WHERE f.geom IS NOT NULL
                      AND f.fence_type IN (''1'', ''2'')
                      %s
                      AND ST_Covers(
                          ST_SetSRID(ST_MakeValid(ST_Force2D(f.geom)), 4326),
                          ST_Force2D($1)
                      )
                )',
                'public',
                v_project_fence_table,
                CASE WHEN v_project_fence_has_height THEN
                    'AND (COALESCE(f.height, 0) = 0 OR COALESCE(ST_Z($1), 0) <= f.height)'
                ELSE
                    ''
                END
            )
            INTO v_hit
            USING p_point;

            IF v_hit THEN
                RETURN true;
            END IF;
        END IF;
    END IF;

    RETURN false;
END;
$$;
COMMENT ON FUNCTION gis_flight_point_in_fence(geometry, varchar) IS '判断航点是否在围栏';

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_flight_line_intersects_fence');
-- =============================================================================
-- 函数介绍：gis_flight_line_intersects_fence
-- 主要作用：判断航线线段是否穿越禁飞区或管控区。
-- 入参说明：p_line 为待检测航线几何；p_project_id 用于匹配全局电子围栏和项目国家规定表。
-- 返回说明：返回boolean，true表示线段与不可通行围栏相交，false表示未相交。
-- 注意事项：同时检查 bo_electric_fence 和 gis_electric_fence_<project_id>。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_flight_line_intersects_fence(
    p_line geometry,
    p_project_id varchar DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
AS $$
DECLARE
    v_hit boolean := false;
    v_project_fence_table text;
    v_project_fence_has_height boolean := false;
BEGIN
    IF p_line IS NULL THEN
        RETURN false;
    END IF;

    IF to_regclass('public.bo_electric_fence') IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1
            FROM public.bo_electric_fence f
            WHERE f.geom IS NOT NULL
              AND f.fence_type IN ('1', '2')
              AND f.status = '1'
              AND f.del_flag = false
              AND f.use_enabled = true
              AND (COALESCE(p_project_id, '') = '' OR f.project_id::text = p_project_id::text)
              AND (
                  COALESCE(f.height, 0) = 0
                  OR (
                      SELECT MIN(ST_Z((dp).geom))
                      FROM ST_DumpPoints(p_line) AS dp
                  ) <= f.height
              )
              AND ST_Intersects(
                  ST_SetSRID(ST_MakeValid(ST_Force2D(f.geom)), 4326),
                  ST_Force2D(p_line)
              )
        ) INTO v_hit;

        IF v_hit THEN
            RETURN true;
        END IF;
    END IF;

    IF p_project_id IS NOT NULL AND trim(p_project_id) <> '' THEN
        v_project_fence_table := 'gis_electric_fence_' || regexp_replace(trim(p_project_id), '[^0-9a-zA-Z_]', '', 'g');
        IF to_regclass(format('%I.%I', 'public', v_project_fence_table)) IS NOT NULL THEN
            SELECT EXISTS(
                SELECT 1
                FROM information_schema.columns
                WHERE table_schema = 'public'
                  AND table_name = v_project_fence_table
                  AND column_name = 'height'
            ) INTO v_project_fence_has_height;

            EXECUTE format('
                SELECT EXISTS(
                    SELECT 1
                    FROM %I.%I f
                    WHERE f.geom IS NOT NULL
                      AND f.fence_type IN (''1'', ''2'')
                      %s
                      AND ST_Intersects(
                          ST_SetSRID(ST_MakeValid(ST_Force2D(f.geom)), 4326),
                          ST_Force2D($1)
                      )
                )',
                'public',
                v_project_fence_table,
                CASE WHEN v_project_fence_has_height THEN
                    'AND (COALESCE(f.height, 0) = 0 OR (SELECT MIN(ST_Z((dp).geom)) FROM ST_DumpPoints($1) AS dp) <= f.height)'
                ELSE
                    ''
                END
            )
            INTO v_hit
            USING p_line;

            IF v_hit THEN
                RETURN true;
            END IF;
        END IF;
    END IF;

    RETURN false;
END;
$$;
COMMENT ON FUNCTION gis_flight_line_intersects_fence(geometry, varchar) IS '判断航线是否穿越围栏';

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_astar_3d_flight');

-- =============================================================================
-- 函数介绍：gis_astar_3d_flight
-- 主要作用：对单段起终点执行三维A*航线规划，自动避开网格中不可飞节点和围栏穿越边。
-- 入参说明：包含起点/终点经纬高、安全高度、高度模式、是否强制重算、项目ID和创建人。
-- 返回说明：返回规划状态、航线记录字段、原始路径、平滑路径、航点JSON和距离统计。
-- 注意事项：优先复用历史航线；强制重算或无历史时读取项目网格表，失败时会降级返回直线航线。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_astar_3d_flight(
    p_start_lon        DOUBLE PRECISION,
    p_start_lat        DOUBLE PRECISION,
    p_start_alt        DOUBLE PRECISION,
    p_end_lon          DOUBLE PRECISION,
    p_end_lat          DOUBLE PRECISION,
    p_end_alt          DOUBLE PRECISION,
    p_safe_altitude    DOUBLE PRECISION DEFAULT 120,
    p_height_mode      DOUBLE PRECISION DEFAULT 0,
    p_force_gen        BOOLEAN DEFAULT FALSE,
    p_project_id       VARCHAR DEFAULT NULL,
    p_create_user      VARCHAR DEFAULT NULL
) RETURNS TABLE (
    code integer,
    msg text,
    id integer,
    project_id char(32),
    create_user varchar(32),
    create_time timestamp,
    update_user varchar(32),
    update_time timestamp,
    del_flag boolean,
    start_point geometry(PointZ,4326),
    end_point geometry(PointZ,4326),
    safe_altitude double precision,
    path_line geometry(LineStringZ,4326),
    smooth_path_line geometry(LineStringZ,4326),
    waypoints jsonb,
    smooth_waypoints jsonb,
    total_distance double precision,
    smooth_ratio double precision
) AS $$
DECLARE
    v_start_time    timestamptz := clock_timestamp();
    v_return_msg    TEXT;

    -- ====================== 几何相关变量 ======================
    -- 3D起点几何对象（PointZ，WGS84坐标系SRID=4326）
    v_start_pt      geometry(PointZ,4326);
    -- 3D终点几何对象
    v_end_pt        geometry(PointZ,4326);
    v_start_safe_pt geometry(PointZ,4326);
    v_end_safe_pt   geometry(PointZ,4326);
    
    -- ====================== 历史航线复用 ======================
    -- 存储查询到的匹配历史航线记录
    v_old_path      gis_flight_paths;
    
    -- ====================== 网格节点ID ======================
    -- 距离起点最近的网格节点ID
    v_start_id      INT;
    -- 距离终点最近的网格节点ID
    v_goal_id       INT;
    
    -- ====================== A* 路径结果 ======================
    -- A*算法找到的路径节点ID数组（用于回溯生成线路）
    v_path_ids      INT[];
    -- 路径回溯时当前遍历节点ID
    v_current_id    INT;
    
    -- ====================== 线路几何 ======================
    -- A*算法生成的原始三维线路（未做高度平滑）
    v_path_line     geometry(LineStringZ,4326);
    -- A*算法生成的初始三维线路（未做可视连线简化）
    v_raw_path_line geometry(LineStringZ,4326);
    -- 高度平滑后的最终可执行飞行线路
    v_final_path    geometry(LineStringZ,4326);
    
    -- ====================== 航点JSON ======================
    -- 原始路径对应的航点JSON数组（lon/lat/alt）
    v_waypoints     JSONB;
    -- 平滑后路径对应的航点JSON数组
    v_smooth_waypoints JSONB;
    
    -- ====================== 高度平滑辅助变量 ======================
    -- 高度计算中间比例值（用于三段式平滑）
    ratio           DOUBLE PRECISION;
    -- 插值计算后的新高度值（米）
    new_z           DOUBLE PRECISION;
    
    -- ====================== 搜索范围裁剪 ======================
    -- 网格搜索范围X轴最小值（经度方向索引）
    v_min_x INT;
    -- 网格搜索范围X轴最大值
    v_max_x INT;
    -- 网格搜索范围Y轴最小值（纬度方向索引）
    v_min_y INT;
    -- 网格搜索范围Y轴最大值
    v_max_y INT;
    -- 本次A*两点距离（米），用于动态调整搜索范围
    v_astar_segment_m DOUBLE PRECISION;
    -- 搜索范围外扩网格数：短线小、长线大，避免固定外扩导致短线变慢或长线绕不开
    v_expand_grid INT;
    
    -- ====================== 算法控制标志 ======================
    -- 是否启用A*算法进行路径规划（true=启用，false=直接直线）
    v_use_astar     BOOLEAN := false;
    -- 实际参与本次规划的网格表名；优先使用项目网格表 gis_grid_nodes_{项目ID}
    v_grid_table     TEXT;
    v_debug_tmp_grid_count BIGINT;
    v_debug_start_node TEXT;
    v_debug_goal_node TEXT;
    v_debug_path_ids_before_trim INT[];
    
    -- ====================== 边检查辅助变量 ======================
    v_edge_line     geometry(LineStringZ,4326);   -- 节点间的线段几何
    v_log_sql      text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_astar_3d_flight(%s, %s, %s, %s, %s, %s, %s, %s, %L, %L, %L);',
        COALESCE(p_start_lon::text, 'NULL'), COALESCE(p_start_lat::text, 'NULL'), COALESCE(p_start_alt::text, 'NULL'),
        COALESCE(p_end_lon::text, 'NULL'), COALESCE(p_end_lat::text, 'NULL'), COALESCE(p_end_alt::text, 'NULL'),
        COALESCE(p_safe_altitude::text, 'NULL'), COALESCE(p_height_mode::text, 'NULL'),
        p_force_gen, p_project_id, p_create_user);

    -- ====================== 0. 基础参数校验 ======================
    IF p_start_lon IS NULL OR p_start_lat IS NULL OR p_start_alt IS NULL
       OR p_end_lon IS NULL OR p_end_lat IS NULL OR p_end_alt IS NULL THEN
        code := 400;
        msg := format('参数错误：起点/终点经纬度和高度不能为空，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    IF p_safe_altitude IS NULL OR p_safe_altitude <= 0 THEN
        code := 400;
        msg := format('参数错误：安全高度必须大于0，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    IF p_height_mode IS NULL OR p_height_mode < 0 OR p_height_mode >= 1 THEN
        code := 400;
        msg := format('参数错误：高度平滑模式必须满足 0 <= p_height_mode < 1，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    -- ====================== 1. 构建3D起点和终点几何对象 ======================
    -- 将输入的经纬度+高度构造成PostGIS 3D点，并指定WGS84坐标系（SRID 4326）
    v_start_pt := ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_start_alt), 4326);
    v_end_pt   := ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_end_alt), 4326);
    v_start_safe_pt := ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_safe_altitude), 4326);
    v_end_safe_pt   := ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_safe_altitude), 4326);
    RAISE NOTICE '【A*调试】规划安全高度点：start_safe=(%,%,%), end_safe=(%,%,%)',
        ST_X(v_start_safe_pt), ST_Y(v_start_safe_pt), ST_Z(v_start_safe_pt),
        ST_X(v_end_safe_pt), ST_Y(v_end_safe_pt), ST_Z(v_end_safe_pt);

    IF gis_flight_point_in_fence(v_start_pt, p_project_id) THEN
        code := 400;
        msg := format('参数错误：起点在禁飞区或管控区内，start=(%s,%s,%s)，执行时间 %s 秒',
                      p_start_lon, p_start_lat, p_start_alt,
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    IF gis_flight_point_in_fence(v_end_pt, p_project_id) THEN
        code := 400;
        msg := format('参数错误：终点在禁飞区或管控区内，end=(%s,%s,%s)，执行时间 %s 秒',
                      p_end_lon, p_end_lat, p_end_alt,
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    -- ====================== 2. 非强制生成时，优先复用历史航线 ======================
    -- 未开启强制重算 → 尝试查询完全相同条件的历史航线（避免重复计算）
    IF NOT p_force_gen THEN
        -- 查询条件：未删除 + 同项目 + 同安全高度 + 同平滑模式 + 起止点空间相等
        SELECT fp.* INTO v_old_path
        FROM gis_flight_paths fp
        WHERE fp.del_flag = false
          AND fp.project_id IS NOT DISTINCT FROM p_project_id
          AND fp.safe_altitude = p_safe_altitude
          AND fp.smooth_ratio = p_height_mode
          AND ST_Equals(fp.start_point, v_start_pt)
          AND ST_Equals(fp.end_point, v_end_pt)
        LIMIT 1;-- 只取一条（通常最多一条）

        -- 找到历史航线 → 直接返回并结束函数，极大提升性能
        IF v_old_path IS NOT NULL THEN
            v_return_msg := format('规划成功：复用历史航线，执行时间 %s 秒',
                                   ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
            RETURN QUERY SELECT 200, v_return_msg, (v_old_path).*;
            RETURN;
        END IF;
    END IF;

    -- ====================== 3. 判断是否满足A*算法执行条件 ======================
    -- 网格表选择规则：
    -- 1. project_id不为空且项目网格表 gis_grid_nodes_{项目ID} 存在 → 使用项目网格表
    -- 2. 项目网格表不存在但公共表 gis_grid_nodes 存在 → 使用公共表
    -- 3. 两者都不存在 → 不启用A*，直接走直线兜底
    IF p_project_id IS NOT NULL
       AND trim(p_project_id) <> ''
       AND to_regclass(format('%I.%I', 'public', 'gis_grid_nodes_' || trim(p_project_id))) IS NOT NULL THEN
        v_grid_table := 'gis_grid_nodes_' || trim(p_project_id);
    ELSIF to_regclass('public.gis_grid_nodes') IS NOT NULL THEN
        v_grid_table := 'gis_grid_nodes';
    ELSE
        v_grid_table := NULL;
        RAISE NOTICE '【调试】未找到可用网格表，直接返回直线兜底航线';
    END IF;

    IF v_grid_table IS NOT NULL THEN
        -- 查找起点最近的可通行网格，优先使用综合 is_flyable 标记。
        EXECUTE format('
            SELECT id
            FROM %I
            WHERE is_flyable = true
              AND ST_Z(geom) <= $2
            ORDER BY geom <-> $1
            LIMIT 1', v_grid_table)
        INTO v_start_id
        USING v_start_safe_pt, p_safe_altitude;

        -- 查找终点最近的可通行网格，优先使用综合 is_flyable 标记。
        EXECUTE format('
            SELECT id
            FROM %I
            WHERE is_flyable = true
              AND ST_Z(geom) <= $2
            ORDER BY geom <-> $1
            LIMIT 1', v_grid_table)
        INTO v_goal_id
        USING v_end_safe_pt, p_safe_altitude;
    END IF;

    -- A*启用条件：
    --   (1) 起止点都找到有效网格节点
    --   (2) 起止点所在网格为适飞区或未标记（非禁飞区、非管控区）
    --   (3) 网格表有可通行网格（确保存在数据）
    IF v_start_id IS NOT NULL
       AND v_goal_id IS NOT NULL
       AND v_grid_table IS NOT NULL THEN
        -- 所有条件满足，启用A*寻路
        EXECUTE format('
            SELECT
                EXISTS(SELECT 1 FROM %I WHERE id = $1 AND is_flyable = true AND ST_Z(geom) <= $3)
                AND EXISTS(SELECT 1 FROM %I WHERE id = $2 AND is_flyable = true AND ST_Z(geom) <= $3)
                AND EXISTS(SELECT 1 FROM %I WHERE is_flyable = true AND ST_Z(geom) <= $3)',
            v_grid_table, v_grid_table, v_grid_table)
        INTO v_use_astar
        USING v_start_id, v_goal_id, p_safe_altitude;
    ELSE
        v_use_astar := false;
    END IF;

    -- ====================== 分支1：不满足A* → 直接生成两点直线航线（兜底方案） ======================
    -- 此分支处理以下情况：网格表为空、起点或终点在禁飞区、无法匹配网格等
    IF NOT v_use_astar THEN
        IF v_grid_table IS NULL THEN
            code := 500;
            msg := format('规划失败：未找到可用网格表，无法启用A*，执行时间 %s 秒',
                          ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        ELSIF v_start_id IS NULL AND v_goal_id IS NULL THEN
            code := 400;
            msg := format('规划失败：起点和终点附近均未找到可飞网格节点，grid_table=%s，执行时间 %s 秒',
                          v_grid_table,
                          ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        ELSIF v_start_id IS NULL THEN
            code := 400;
            msg := format('规划失败：起点附近未找到可飞网格节点，grid_table=%s，执行时间 %s 秒',
                          v_grid_table,
                          ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        ELSIF v_goal_id IS NULL THEN
            code := 400;
            msg := format('规划失败：终点附近未找到可飞网格节点，grid_table=%s，执行时间 %s 秒',
                          v_grid_table,
                          ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        ELSE
            code := 500;
            msg := format('规划失败：网格数据状态不一致，A*启用校验未通过，grid_table=%s，start_id=%s，goal_id=%s，执行时间 %s 秒',
                          v_grid_table,
                          COALESCE(v_start_id::text, 'NULL'),
                          COALESCE(v_goal_id::text, 'NULL'),
                          ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        END IF;

        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
        -- 构建符合直升直降规则的3D直线航线。
        v_path_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
        v_path_line := ST_AddPoint(v_path_line, v_start_pt);
        IF p_height_mode = 0 AND abs(p_start_alt - p_safe_altitude) > 0.001 THEN
            v_path_line := ST_AddPoint(v_path_line,
                ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_safe_altitude), 4326)
            );
        END IF;
        IF p_height_mode = 0 AND abs(p_end_alt - p_safe_altitude) > 0.001 THEN
            v_path_line := ST_AddPoint(v_path_line,
                ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_safe_altitude), 4326)
            );
        END IF;
        v_path_line := ST_AddPoint(v_path_line, v_end_pt);
        v_path_line := gis_linestring_remove_duplicate_points(v_path_line);
        -- 最终路径 = 原始直线路径（未经平滑）
        v_final_path := v_path_line;
        SELECT jsonb_agg(
            jsonb_build_object('lon', ST_X((dp).geom), 'lat', ST_Y((dp).geom), 'alt', ST_Z((dp).geom))
            ORDER BY (dp).path[1]
        )
        INTO v_waypoints
        FROM ST_DumpPoints(v_path_line) AS dp;
        -- 平滑航点与原始航点一致（直线无需平滑）
        v_smooth_waypoints := v_waypoints;
        -- 只返回计算结果，不写入 gis_flight_paths。
        v_return_msg := format('规划成功：未满足A*条件，已生成直线兜底航线，执行时间 %s 秒',
                               ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        RETURN QUERY
        SELECT
            200, v_return_msg,
            NULL::integer, p_project_id::char(32), p_create_user::varchar(32), NOW()::timestamp,
            p_create_user::varchar(32), NOW()::timestamp, false,
            v_start_pt, v_end_pt, p_safe_altitude,
            v_path_line, v_final_path,
            v_waypoints, v_smooth_waypoints,
            gis_linestring_length_m(v_final_path), p_height_mode;
        RETURN; -- 提前结束函数
    END IF;
 -- ====================== 分支2：满足A*条件 → 执行三维路径规划 ======================
    -- 创建A*算法临时表（事务结束自动删除，不占用持久存储）
    -- 包含网格坐标、几何对象、可通行标志、代价和父节点信息
    CREATE TEMP TABLE tmp_grid (
        id INT PRIMARY KEY,               -- 网格节点ID
        x INT, y INT, z INT,              -- 网格三维坐标索引
        geom geometry(PointZ,4326),       -- 网格几何点（三维）
        is_walkable BOOLEAN,              -- 是否可通行（动态计算）
        g_cost FLOAT,                     -- 起点到当前节点的实际代价（距离）
        h_cost FLOAT,                     -- 当前节点到终点的启发式预估代价（3D距离）
        f_cost FLOAT,                     -- 总代价 f = g + h
        parent_id INT                     -- 父节点ID，用于路径回溯
    ) ON COMMIT DELETE ROWS;

    -- 获取起止点所在网格的X/Y索引坐标，用于限定搜索范围（缩小计算量）
    EXECUTE format('SELECT x FROM %I WHERE id = $1', v_grid_table) INTO v_min_x USING v_start_id;
    EXECUTE format('SELECT x FROM %I WHERE id = $1', v_grid_table) INTO v_max_x USING v_goal_id;
    EXECUTE format('SELECT y FROM %I WHERE id = $1', v_grid_table) INTO v_min_y USING v_start_id;
    EXECUTE format('SELECT y FROM %I WHERE id = $1', v_grid_table) INTO v_max_y USING v_goal_id;

    v_astar_segment_m := SQRT(
        POWER((p_end_lon - p_start_lon) * 111000.0 * COS(RADIANS((p_start_lat + p_end_lat) / 2.0)), 2)
        + POWER((p_end_lat - p_start_lat) * 111000.0, 2)
    );

    v_expand_grid := CASE
        WHEN v_astar_segment_m <= 1000 THEN 3
        WHEN v_astar_segment_m <= 2000 THEN 5
        WHEN v_astar_segment_m <= 5000 THEN 10
        WHEN v_astar_segment_m <= 10000 THEN 20
        WHEN v_astar_segment_m <= 20000 THEN 40
        ELSE 60
    END;

    -- 按本次A*两点距离动态扩大搜索范围，避免短线过慢、长线绕不开。
    -- 先确定原始范围（确保min <= max），再向外扩展
    SELECT least(v_min_x, v_max_x), greatest(v_min_x, v_max_x)
    INTO v_min_x, v_max_x;
    v_min_x := v_min_x - v_expand_grid;
    v_max_x := v_max_x + v_expand_grid;
    
    SELECT least(v_min_y, v_max_y), greatest(v_min_y, v_max_y)
    INTO v_min_y, v_max_y;
    v_min_y := v_min_y - v_expand_grid;
    v_max_y := v_max_y + v_expand_grid;

  -- 将搜索范围内的可飞网格数据导入临时表；is_walkable 始终为 true（WHERE 已过滤不可通行区域）
    EXECUTE format('
         INSERT INTO tmp_grid
        SELECT id, x, y, z, geom,
               true,
               0,0,0,NULL
        FROM %I
        WHERE x BETWEEN %s AND %s AND y BETWEEN %s AND %s
          AND is_flyable = true
          AND ST_Z(geom) <= %s
    ', v_grid_table, v_min_x, v_max_x, v_min_y, v_max_y, p_safe_altitude);

    CREATE INDEX idx_tmp_grid_xyz ON tmp_grid (x, y, z);
    CREATE INDEX idx_tmp_grid_geom ON tmp_grid USING GIST (geom);
    ANALYZE tmp_grid;

    SELECT COUNT(*) INTO v_debug_tmp_grid_count FROM tmp_grid;
    RAISE NOTICE '【A*调试】tmp_grid_count=%, safe_altitude=%, segment_m=%, expand_grid=%, x_range=[%,%], y_range=[%,%]',
        v_debug_tmp_grid_count,
        p_safe_altitude,
        ROUND(v_astar_segment_m::numeric, 2),
        v_expand_grid,
        v_min_x, v_max_x, v_min_y, v_max_y;
    FOR v_debug_start_node IN
        SELECT format('z=%s, alt=%s, count=%s', z, ST_Z(geom), count(*))
        FROM tmp_grid
        GROUP BY z, ST_Z(geom)
        ORDER BY z
    LOOP
        RAISE NOTICE '【A*调试】tmp_grid高度层：%', v_debug_start_node;
    END LOOP;

    -- 在临时表中重新匹配最近的起点/终点网格（确保在搜索范围内）
    SELECT g.id INTO v_start_id FROM tmp_grid g ORDER BY g.geom <-> v_start_safe_pt LIMIT 1;
    SELECT g.id INTO v_goal_id  FROM tmp_grid g ORDER BY g.geom <-> v_end_safe_pt LIMIT 1;

    SELECT format('id=%s,x=%s,y=%s,z=%s,lon=%s,lat=%s,alt=%s,dist_m=%s',
                  g.id, g.x, g.y, g.z, ST_X(g.geom), ST_Y(g.geom), ST_Z(g.geom),
                  ROUND(ST_Distance(g.geom::geography, v_start_safe_pt::geography)::numeric, 3))
    INTO v_debug_start_node
    FROM tmp_grid g
    WHERE g.id = v_start_id;
    SELECT format('id=%s,x=%s,y=%s,z=%s,lon=%s,lat=%s,alt=%s,dist_m=%s',
                  g.id, g.x, g.y, g.z, ST_X(g.geom), ST_Y(g.geom), ST_Z(g.geom),
                  ROUND(ST_Distance(g.geom::geography, v_end_safe_pt::geography)::numeric, 3))
    INTO v_debug_goal_node
    FROM tmp_grid g
    WHERE g.id = v_goal_id;
    RAISE NOTICE '【A*调试】tmp重选start：%', COALESCE(v_debug_start_node, 'NULL');
    RAISE NOTICE '【A*调试】tmp重选goal ：%', COALESCE(v_debug_goal_node, 'NULL');

    -- 初始化起点代价：g_cost = 0（起点到自身代价为0）
    -- h_cost = 起点到终点的3D直线距离（启发函数）
    -- f_cost = g_cost + h_cost
    UPDATE tmp_grid g
    SET g_cost = 0,
        h_cost = ST_3DDistance(g.geom, v_end_safe_pt),
        f_cost = 0 + ST_3DDistance(g.geom, v_end_safe_pt)
    WHERE g.id = v_start_id;

    -- ====================== A* 算法核心循环 ======================
    DECLARE
        -- 开放列表：待检查的节点ID数组
        v_open INT[] := ARRAY[v_start_id];
        -- 关闭列表：已检查的节点ID数组
        v_closed INT[] := '{}'::INT[];
        -- 当前正在处理的节点ID
        v_curr INT;
        -- 当前节点的网格坐标
        v_curr_x INT; v_curr_y INT; v_curr_z INT;
        -- 当前节点的几何对象
        v_curr_geom geometry;
        -- 当前节点的g代价
        v_curr_g FLOAT;
        -- 邻居节点ID
        v_nid INT;
        -- 邻居节点几何对象
        v_n_geom geometry;
        -- 邻居节点当前的g代价
        v_n_g FLOAT;
        -- 邻居节点是否可通行
        v_n_walk BOOLEAN;
        -- 通过当前节点到达邻居的新g代价
        new_g FLOAT;
    BEGIN
        -- 只要开放列表不为空，就继续搜索
        WHILE array_length(v_open, 1) > 0 LOOP
            -- 从开放列表中取出 f_cost 最小的节点作为当前节点
            SELECT g.id, g.x, g.y, g.z, g.geom, g.g_cost
            INTO v_curr, v_curr_x, v_curr_y, v_curr_z, v_curr_geom, v_curr_g
            FROM tmp_grid g
            WHERE g.id = ANY(v_open)
            ORDER BY g.f_cost LIMIT 1;

            -- 如果当前节点就是目标节点，则成功找到路径，退出循环
            IF v_curr = v_goal_id THEN EXIT; END IF;

            -- 将当前节点从开放列表移至关闭列表（表示已处理）
            v_open := array_remove(v_open, v_curr);
            v_closed := array_append(v_closed, v_curr);

           -- 遍历当前节点在三维空间中的26个邻域节点（3x3x3范围，排除自身）
            FOR v_nid, v_n_geom, v_n_g, v_n_walk IN
                SELECT g.id, g.geom, g.g_cost, g.is_walkable
                FROM tmp_grid g
                    WHERE g.x BETWEEN v_curr_x - 1 AND v_curr_x + 1      -- X方向相邻（经度）
                  AND g.y BETWEEN v_curr_y - 1 AND v_curr_y + 1      -- Y方向相邻（纬度）
                  AND g.z BETWEEN v_curr_z - 1 AND v_curr_z + 1      -- Z方向相邻（高度层）
                  AND g.id <> v_curr                -- 排除当前节点自身
                  AND g.is_walkable = TRUE          -- 只考虑可通行的网格
                  AND g.id <> ALL(v_closed)         -- 排除已经处理过的节点
            LOOP
                -- 计算通过当前节点到达邻居节点的新g代价 = 当前g代价 + 当前节点到邻居的3D距离
                new_g := v_curr_g + ST_3DDistance(v_n_geom, v_curr_geom);
                
                -- ======================  边相交性检查 ======================
                -- 构建当前节点到邻居节点的线段
                v_edge_line := ST_MakeLine(v_curr_geom, v_n_geom);
                -- 统一使用封装函数判断禁飞区/管控区，包含 bo_electric_fence 和项目专属国家规定围栏。
                IF gis_flight_line_intersects_fence(v_edge_line, p_project_id) THEN
                    CONTINUE;   -- 该边穿越禁飞区，不可通行，跳过此邻居
                END IF;
                -- ===============================================================

                -- 如果邻居节点不在开放列表中，或者新路径的g代价更小，则更新邻居的代价和父节点
                IF v_nid <> ALL(v_open) OR new_g < v_n_g THEN
                    UPDATE tmp_grid g
                    SET g_cost = new_g,
                        h_cost = ST_3DDistance(v_n_geom, v_end_safe_pt),
                        f_cost = new_g + ST_3DDistance(v_n_geom, v_end_safe_pt),
                        parent_id = v_curr
                    WHERE g.id = v_nid;

                    -- 如果邻居节点不在开放列表中，则将其加入开放列表
                    IF v_nid <> ALL(v_open) THEN
                        v_open := array_append(v_open, v_nid);
                    END IF;
                END IF;
            END LOOP;
        END LOOP;

        -- ====================== 从终点回溯父节点，生成路径ID数组 ======================
        -- 从目标节点开始，沿着 parent_id 链向上回溯，直到父节点为 NULL
        v_current_id := v_goal_id;
        WHILE v_current_id IS NOT NULL LOOP
            -- 将节点ID插入数组头部（保证路径从起点到终点的顺序）
            v_path_ids := array_prepend(v_current_id, v_path_ids);
            -- 获取当前节点的父节点ID
            SELECT g.parent_id INTO v_current_id FROM tmp_grid g WHERE g.id = v_current_id;
        END LOOP;
        -- 仅当路径中确实包含虚拟节点（起点ID=-1，终点ID=-2）时才移除首尾。
        -- 当前A*回溯使用真实网格节点ID，不能无条件裁掉首尾，否则两节点路径会被裁空。
        v_debug_path_ids_before_trim := v_path_ids;
        RAISE NOTICE '【A*调试】回溯裁剪前 path_ids=%', v_debug_path_ids_before_trim;
        IF array_length(v_path_ids, 1) >= 2
           AND v_path_ids[1] = -1
           AND v_path_ids[array_length(v_path_ids, 1)] = -2 THEN
            v_path_ids := v_path_ids[2:array_length(v_path_ids, 1)-1];
        END IF;
        RAISE NOTICE '【A*调试】回溯裁剪后 path_ids=%', v_path_ids;
        
        -- 输出A*路径所有节点的坐标信息
        DECLARE
            v_node_idx INT;
            v_node_lon DOUBLE PRECISION;
            v_node_lat DOUBLE PRECISION;
            v_node_alt DOUBLE PRECISION;
        BEGIN
            RAISE NOTICE '【A*路径坐标】';
            IF COALESCE(array_length(v_path_ids, 1), 0) > 0 THEN
                FOR v_node_idx IN 1..array_length(v_path_ids, 1) LOOP
                    SELECT ST_X(g.geom), ST_Y(g.geom), ST_Z(g.geom)
                    INTO v_node_lon, v_node_lat, v_node_alt
                    FROM tmp_grid g WHERE g.id = v_path_ids[v_node_idx];
                    RAISE NOTICE '节点%: (经度=%, 纬度=%, 高度=%)',
                        v_node_idx, v_node_lon, v_node_lat, v_node_alt;
                END LOOP;
            ELSE
                RAISE NOTICE '【A*路径坐标】未生成有效路径节点';
            END IF;
        END;
    END;

    -- ====================== A* 寻路失败（路径点数量 < 2）→ 降级为直线航线 ======================
    -- 路径点少于2说明没有有效路径（可能起点终点不连通，或搜索失败），此时使用直线航线
    IF COALESCE(array_length(v_path_ids, 1), 0) < 1 THEN
        DROP TABLE IF EXISTS tmp_grid;
        code := 400;
        msg := format('规划失败：A*未找到有效路径，无法生成避障航线，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
        DROP TABLE IF EXISTS tmp_grid;-- 清理临时表
        -- 生成符合直升直降规则的直线航线（与分支1逻辑相同）
        v_path_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
        v_path_line := ST_AddPoint(v_path_line, v_start_pt);
        IF p_height_mode = 0 AND abs(p_start_alt - p_safe_altitude) > 0.001 THEN
            v_path_line := ST_AddPoint(v_path_line,
                ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_safe_altitude), 4326)
            );
        END IF;
        IF p_height_mode = 0 AND abs(p_end_alt - p_safe_altitude) > 0.001 THEN
            v_path_line := ST_AddPoint(v_path_line,
                ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_safe_altitude), 4326)
            );
        END IF;
        v_path_line := ST_AddPoint(v_path_line, v_end_pt);
        v_path_line := gis_linestring_remove_duplicate_points(v_path_line);
        v_final_path := v_path_line;
        SELECT jsonb_agg(
            jsonb_build_object('lon', ST_X((dp).geom), 'lat', ST_Y((dp).geom), 'alt', ST_Z((dp).geom))
            ORDER BY (dp).path[1]
        )
        INTO v_waypoints
        FROM ST_DumpPoints(v_path_line) AS dp;
        v_smooth_waypoints := v_waypoints;

        v_return_msg := format('规划成功：A*未找到有效路径，已生成直线兜底航线，执行时间 %s 秒',
                               ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        RETURN QUERY
        SELECT
            200, v_return_msg,
            NULL::integer, p_project_id::char(32), p_create_user::varchar(32), NOW()::timestamp,
            p_create_user::varchar(32), NOW()::timestamp, false,
            v_start_pt, v_end_pt, p_safe_altitude,
            v_path_line, v_final_path,
            v_waypoints, v_smooth_waypoints,
            gis_linestring_length_m(v_final_path), p_height_mode;
        RETURN;
    END IF;

  -- ====================== 生成标准原始路径（未平滑，但包含起飞/降落过渡） ======================
    -- 初始化空的3D线几何（SRID=4326）
    v_path_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
    -- 1. 添加真实起点
    v_path_line := ST_AddPoint(v_path_line, v_start_pt);

    -- 2. 如果高度模式为直升直降（p_height_mode = 0），则在起点位置添加一个安全高度点（原地爬升）
    IF p_height_mode = 0
       AND abs(p_start_alt - p_safe_altitude) > 0.001 THEN
        v_path_line := ST_AddPoint(v_path_line,
            ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_safe_altitude), 4326)
        );
    END IF;

    -- 3. 循环添加A*路径所有网格点（高度统一为安全高度）
    FOR i IN 1..array_length(v_path_ids, 1) LOOP
        v_path_line := ST_AddPoint(v_path_line,
            ST_SetSRID(ST_MakePoint(
                ST_X((SELECT g.geom FROM tmp_grid g WHERE g.id = v_path_ids[i])),
                ST_Y((SELECT g.geom FROM tmp_grid g WHERE g.id = v_path_ids[i])),
                p_safe_altitude), 4326)
        );
    END LOOP;

    -- 4. 如果高度模式为直升直降，则在终点位置添加一个安全高度点（终点上空悬停）
    IF p_height_mode = 0
       AND abs(p_end_alt - p_safe_altitude) > 0.001 THEN
        v_path_line := ST_AddPoint(v_path_line,
            ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_safe_altitude), 4326)
        );
    END IF;

    -- 5. 添加真实终点
    v_path_line := ST_AddPoint(v_path_line, v_end_pt);
    v_raw_path_line := v_path_line;
    v_raw_path_line := gis_linestring_remove_duplicate_points(v_raw_path_line);

    -- ====================== 原始路径可视连线简化 ======================
    -- 规则：
    -- 1. 起点高度与安全高度不一致时保留起点原地升降段；一致时起点参与简化。
    -- 2. 终点高度与安全高度不一致时保留终点原地升降段；一致时终点参与简化。
    -- 3. 判断“当前点 -> 下下个点”的直连线是否穿越禁飞区/管控区，不穿越则删除中间点。
    -- 4. 删除后继续用当前点向新的下下个点校验；若穿越则保留中间点并移动到下一个点。
    DECLARE
        v_simplify_idx INT := 2;                 -- 默认跳过起点原地升降段，从第二个点开始校验
        v_simplify_end_offset INT := 3;          -- 默认保留终点原地升降段
        v_min_simplify_points INT := 3;          -- 无起降垂直段时，允许3点压缩为2点
        v_has_start_vertical BOOLEAN := (p_height_mode = 0 AND abs(p_start_alt - p_safe_altitude) > 0.001);
        v_has_end_vertical BOOLEAN := (p_height_mode = 0 AND abs(p_end_alt - p_safe_altitude) > 0.001);
        v_direct_line geometry(LineStringZ,4326);-- 当前点到下下个点的直连线
        v_blocked BOOLEAN;                       -- 直连线是否穿越禁飞区/管控区
    BEGIN
        IF NOT v_has_start_vertical THEN
            v_simplify_idx := 1;
        ELSE
            v_min_simplify_points := 4;
        END IF;

        IF NOT v_has_end_vertical THEN
            v_simplify_end_offset := 2;
        ELSE
            v_min_simplify_points := 4;
        END IF;

        WHILE ST_NumPoints(v_path_line) >= v_min_simplify_points
              AND v_simplify_idx <= ST_NumPoints(v_path_line) - v_simplify_end_offset LOOP

            v_direct_line := ST_MakeLine(
                ST_PointN(v_path_line, v_simplify_idx),
                ST_PointN(v_path_line, v_simplify_idx + 2)
            );

            -- 仅当直连线不穿越禁飞区/管控区时才允许删除中间点。
            v_blocked := gis_flight_line_intersects_fence(v_direct_line, p_project_id);

            IF NOT v_blocked THEN
                -- PostGIS点序号是1-based，ST_RemovePoint索引是0-based；删除中间点 idx+1。
                v_path_line := ST_RemovePoint(v_path_line, v_simplify_idx);
            ELSE
                v_simplify_idx := v_simplify_idx + 1;
            END IF;
        END LOOP;
    END;

    v_path_line := gis_linestring_remove_duplicate_points(v_path_line);
    -- 平滑路径当前直接使用简化后的 v_path_line。
    v_final_path := v_path_line;

    -- ====================== 生成原始航点JSON数组 ======================
    -- 将A*初始路径（v_raw_path_line）中的每个点转换为JSON对象，包含经度、纬度、高度
    SELECT jsonb_agg(
        jsonb_build_object('lon', ST_X(pt), 'lat', ST_Y(pt), 'alt', ST_Z(pt))
        ORDER BY idx
    ) INTO v_waypoints
    FROM (
        SELECT (ST_DumpPoints(v_raw_path_line)).geom AS pt,
               generate_series(1, ST_NumPoints(v_raw_path_line)) AS idx
    ) t;

    -- ====================== 生成平滑航点JSON数组 ======================
    -- 将简化路径（v_path_line）中的每个点转换为JSON对象
    SELECT jsonb_agg(jsonb_build_object('lon', ST_X(p), 'lat', ST_Y(p), 'alt', ST_Z(p)))
    INTO v_smooth_waypoints
    FROM (SELECT (ST_DumpPoints(v_path_line)).geom AS p) AS t;

    -- 单段核心函数只返回计算结果，最终入库由 gis_flight_paths_plan 汇总后处理。
    DROP TABLE IF EXISTS tmp_grid;

    -- 返回最终生成的航线数据
    v_return_msg := format('规划成功：A*路径规划完成，执行时间 %s 秒',
                           ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    RETURN QUERY
    SELECT
        200, v_return_msg,
        NULL::integer, p_project_id::char(32), p_create_user::varchar(32), NOW()::timestamp,
        p_create_user::varchar(32), NOW()::timestamp, false,
        v_start_pt, v_end_pt, p_safe_altitude,
        v_path_line, v_final_path,
        v_waypoints, v_smooth_waypoints,
        gis_linestring_length_m(v_final_path), p_height_mode;

-- ====================== 全局异常捕获：任何错误都返回直线航线（保证服务不崩溃） ======================
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE '【调试】规划异常，拒绝直线兜底，触发原因：%（SQLSTATE=%）', SQLERRM, SQLSTATE;
    DROP TABLE IF EXISTS tmp_grid;
    code := 500;
    msg := format('执行异常：%s，已拒绝生成直线兜底航线，执行时间 %s 秒',
                  SQLERRM,
                  ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (code, msg, v_log_sql);
    RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
    RETURN;
      -- 确保临时表被删除（如果存在）
    RAISE NOTICE '【调试】自动返回直线兜底航线，触发原因：%（SQLSTATE=%）', SQLERRM, SQLSTATE;
    DROP TABLE IF EXISTS tmp_grid;

    -- 异常兜底：生成符合直升直降规则的直线航线（与分支1完全相同）
    v_path_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
    v_path_line := ST_AddPoint(v_path_line, v_start_pt);
    IF p_height_mode = 0 AND abs(p_start_alt - p_safe_altitude) > 0.001 THEN
        v_path_line := ST_AddPoint(v_path_line,
            ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_safe_altitude), 4326)
        );
    END IF;
    IF p_height_mode = 0 AND abs(p_end_alt - p_safe_altitude) > 0.001 THEN
        v_path_line := ST_AddPoint(v_path_line,
            ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_safe_altitude), 4326)
        );
    END IF;
    v_path_line := ST_AddPoint(v_path_line, v_end_pt);
    v_path_line := gis_linestring_remove_duplicate_points(v_path_line);
    v_final_path := v_path_line;

    SELECT jsonb_agg(
        jsonb_build_object('lon', ST_X((dp).geom), 'lat', ST_Y((dp).geom), 'alt', ST_Z((dp).geom))
        ORDER BY (dp).path[1]
    )
    INTO v_waypoints
    FROM ST_DumpPoints(v_path_line) AS dp;
    v_smooth_waypoints := v_waypoints;

    -- 异常时也只返回兜底航线，不写入 gis_flight_paths。
    v_return_msg := format('执行异常：%s，已返回直线兜底航线，执行时间 %s 秒',
                           SQLERRM,
                           ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (500, v_return_msg, v_log_sql);
    RETURN QUERY
    SELECT
        500, v_return_msg,
        NULL::integer, p_project_id::char(32), p_create_user::varchar(32), NOW()::timestamp,
        p_create_user::varchar(32), NOW()::timestamp, false,
        v_start_pt, v_end_pt, p_safe_altitude,
        v_path_line, v_final_path,
        v_waypoints, v_smooth_waypoints,
        gis_linestring_length_m(v_final_path), p_height_mode;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION gis_astar_3d_flight(
    DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION,
    DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION,
    DOUBLE PRECISION, DOUBLE PRECISION, BOOLEAN, VARCHAR, VARCHAR
) IS '规划单段三维避障航线';

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_astar_3d_flight_plan');
-- =============================================================================
-- 函数介绍：gis_astar_3d_flight_plan
-- 主要作用：对外提供单段航线规划接口，封装A*规划、结果组装和必要的业务参数转换。
-- 入参说明：传入起终点经纬高、安全高度、重算标记、项目ID、创建人和高度模式。
-- 返回说明：返回统一code/msg和航线结果，供业务系统直接发起单段自动规划。
-- 注意事项：5km内直接调用gis_astar_3d_flight，超过5km交给gis_flight_paths_plan分段处理。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_astar_3d_flight_plan(
    p_start_lon        DOUBLE PRECISION,
    p_start_lat        DOUBLE PRECISION,
    p_start_alt        DOUBLE PRECISION,
    p_end_lon          DOUBLE PRECISION,
    p_end_lat          DOUBLE PRECISION,
    p_end_alt          DOUBLE PRECISION,
    p_safe_altitude    DOUBLE PRECISION DEFAULT 120,
    p_height_mode      DOUBLE PRECISION DEFAULT 0,
    p_force_gen        BOOLEAN DEFAULT FALSE,
    p_project_id       VARCHAR DEFAULT NULL,
    p_create_user      VARCHAR DEFAULT NULL
) RETURNS TABLE (
    code integer,
    msg text,
    id integer,
    project_id char(32),
    create_user varchar(32),
    create_time timestamp,
    update_user varchar(32),
    update_time timestamp,
    del_flag boolean,
    start_point geometry(PointZ,4326),
    end_point geometry(PointZ,4326),
    safe_altitude double precision,
    path_line geometry(LineStringZ,4326),
    smooth_path_line geometry(LineStringZ,4326),
    waypoints jsonb,
    smooth_waypoints jsonb,
    total_distance double precision,
    smooth_ratio double precision
) AS $$
DECLARE
    v_start_time timestamptz := clock_timestamp();
    v_segment_m DOUBLE PRECISION;
    v_start_pt geometry(PointZ,4326);
    v_end_pt geometry(PointZ,4326);
    v_direct_line geometry(LineStringZ,4326);
    v_waypoints jsonb;
    v_path_id integer;
    v_return_msg text;
    v_calc record;
    v_log_sql      text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_astar_3d_flight_plan(%s, %s, %s, %s, %s, %s, %s, %s, %L, %L, %L);',
        COALESCE(p_start_lon::text, 'NULL'), COALESCE(p_start_lat::text, 'NULL'), COALESCE(p_start_alt::text, 'NULL'),
        COALESCE(p_end_lon::text, 'NULL'), COALESCE(p_end_lat::text, 'NULL'), COALESCE(p_end_alt::text, 'NULL'),
        COALESCE(p_safe_altitude::text, 'NULL'), COALESCE(p_height_mode::text, 'NULL'),
        p_force_gen, p_project_id, p_create_user);

    IF p_start_lon IS NULL OR p_start_lat IS NULL OR p_start_alt IS NULL
       OR p_end_lon IS NULL OR p_end_lat IS NULL OR p_end_alt IS NULL THEN
        RETURN QUERY
        SELECT *
        FROM gis_astar_3d_flight(
            p_start_lon, p_start_lat, p_start_alt,
            p_end_lon, p_end_lat, p_end_alt,
            p_safe_altitude, p_height_mode, p_force_gen,
            p_project_id, p_create_user
        );
        RETURN;
    END IF;

    v_segment_m := SQRT(
        POWER((p_end_lon - p_start_lon) * 111000.0 * COS(RADIANS((p_start_lat + p_end_lat) / 2.0)), 2)
        + POWER((p_end_lat - p_start_lat) * 111000.0, 2)
    );

    IF v_segment_m <= 5000.0 THEN
        SELECT *
        INTO v_calc
        FROM gis_astar_3d_flight(
            p_start_lon, p_start_lat, p_start_alt,
            p_end_lon, p_end_lat, p_end_alt,
            p_safe_altitude, p_height_mode, p_force_gen,
            p_project_id, p_create_user
        )
        LIMIT 1;

        IF NOT FOUND THEN
            RETURN QUERY SELECT
                500,
                '规划失败：gis_astar_3d_flight 未返回任何结果',
                (NULL::gis_flight_paths).*;
            RETURN;
        END IF;

        IF v_calc.code IS DISTINCT FROM 200
           OR v_calc.id IS NOT NULL
           OR v_calc.path_line IS NULL
           OR v_calc.smooth_path_line IS NULL THEN
            RETURN QUERY SELECT
                v_calc.code, v_calc.msg,
                v_calc.id, v_calc.project_id, v_calc.create_user, v_calc.create_time,
                v_calc.update_user, v_calc.update_time, v_calc.del_flag,
                v_calc.start_point, v_calc.end_point, v_calc.safe_altitude,
                v_calc.path_line, v_calc.smooth_path_line,
                v_calc.waypoints, v_calc.smooth_waypoints,
                v_calc.total_distance, v_calc.smooth_ratio;
            RETURN;
        END IF;

        INSERT INTO gis_flight_paths (
            project_id, create_user, update_user,
            start_point, end_point, safe_altitude,
            path_line, smooth_path_line,
            waypoints, smooth_waypoints, total_distance, smooth_ratio
        ) VALUES (
            p_project_id, p_create_user, p_create_user,
            v_calc.start_point, v_calc.end_point, v_calc.safe_altitude,
            v_calc.path_line, v_calc.smooth_path_line,
            v_calc.waypoints, v_calc.smooth_waypoints,
            v_calc.total_distance, v_calc.smooth_ratio
        ) RETURNING gis_flight_paths.id INTO v_path_id;

        v_return_msg := format('规划成功：5km内单段航线已生成并保存，距离 %s 米', ROUND(v_segment_m::numeric, 2));
        RETURN QUERY
        SELECT 200, v_return_msg, p.*
        FROM gis_flight_paths p
        WHERE p.id = v_path_id;
        RETURN;
    END IF;

    v_start_pt := ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_start_alt), 4326);
    v_end_pt := ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_end_alt), 4326);

    IF gis_flight_point_in_fence(v_start_pt, p_project_id) THEN
        code := 400;
        msg := format('参数错误：起点在禁飞区或管控区内，start=(%s,%s,%s)，执行时间 %s 秒',
                      p_start_lon, p_start_lat, p_start_alt,
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    IF gis_flight_point_in_fence(v_end_pt, p_project_id) THEN
        code := 400;
        msg := format('参数错误：终点在禁飞区或管控区内，end=(%s,%s,%s)，执行时间 %s 秒',
                      p_end_lon, p_end_lat, p_end_alt,
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    v_direct_line := ST_MakeLine(v_start_pt, v_end_pt);

    -- 长距离但整条直线不经过禁飞区/管控区时，直接返回一条总航线，避免进入 5km 循环。
    IF NOT gis_flight_line_intersects_fence(v_direct_line, p_project_id) THEN
        v_direct_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
        v_direct_line := ST_AddPoint(v_direct_line, v_start_pt);
        IF p_height_mode = 0 AND abs(p_start_alt - p_safe_altitude) > 0.001 THEN
            v_direct_line := ST_AddPoint(v_direct_line,
                ST_SetSRID(ST_MakePoint(p_start_lon, p_start_lat, p_safe_altitude), 4326)
            );
        END IF;
        IF p_height_mode = 0 AND abs(p_end_alt - p_safe_altitude) > 0.001 THEN
            v_direct_line := ST_AddPoint(v_direct_line,
                ST_SetSRID(ST_MakePoint(p_end_lon, p_end_lat, p_safe_altitude), 4326)
            );
        END IF;
        v_direct_line := ST_AddPoint(v_direct_line, v_end_pt);
        v_direct_line := gis_linestring_remove_duplicate_points(v_direct_line);

        SELECT jsonb_agg(
            jsonb_build_object('lon', ST_X((dp).geom), 'lat', ST_Y((dp).geom), 'alt', ST_Z((dp).geom))
            ORDER BY (dp).path[1]
        )
        INTO v_waypoints
        FROM ST_DumpPoints(v_direct_line) AS dp;

        INSERT INTO gis_flight_paths (
            project_id, create_user, update_user,
            start_point, end_point, safe_altitude,
            path_line, smooth_path_line,
            waypoints, smooth_waypoints, total_distance, smooth_ratio
        ) VALUES (
            p_project_id, p_create_user, p_create_user,
            v_start_pt, v_end_pt, p_safe_altitude,
            v_direct_line, v_direct_line,
            v_waypoints, v_waypoints,
            gis_linestring_length_m(v_direct_line),
            p_height_mode
        ) RETURNING gis_flight_paths.id INTO v_path_id;

        v_return_msg := format('规划成功：长距离直线无围栏冲突，已快速生成直线航线，距离 %s 米', ROUND(v_segment_m::numeric, 2));
        RETURN QUERY SELECT 200, v_return_msg, p.* FROM gis_flight_paths p WHERE p.id = v_path_id;
        RETURN;
    END IF;

    -- 超过 5km 再走汇总函数：
    -- 沿直线按 5km 探测，安全段直接合并，遇禁飞区/管控区才调用 A*；最终只插入并返回一条总航线。
    RETURN QUERY
    SELECT *
    FROM gis_flight_paths_plan(
        jsonb_build_array(
            jsonb_build_object('lon', p_start_lon, 'lat', p_start_lat, 'alt', p_start_alt),
            jsonb_build_object('lon', p_end_lon, 'lat', p_end_lat, 'alt', p_end_alt)
        ),
        p_safe_altitude,
        p_force_gen,
        p_project_id,
        p_create_user,
        p_height_mode
    );
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION gis_astar_3d_flight_plan(
    DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION,
    DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION,
    DOUBLE PRECISION, DOUBLE PRECISION, BOOLEAN, VARCHAR, VARCHAR
) IS '两点自动航线规划入口';

-- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_flight_paths_plan');
-- =============================================================================
-- 函数介绍：gis_flight_paths_plan
-- 主要作用：对多个航点按顺序拆分成多段，逐段调用航线规划并汇总成完整航线。
-- 入参说明：p_points 支持对象数组或坐标数组；p_safe_altitude 为安全高度；p_force_gen 控制是否强制重算。
-- 返回说明：返回多段规划后的整体结果、分段结果、合并航点和总距离等信息。
-- 注意事项：适合多航点任务；任一分段失败时需结合返回code/msg判断是否继续使用结果。
-- =============================================================================
CREATE OR REPLACE FUNCTION gis_flight_paths_plan(
    p_points         JSONB,
    p_safe_altitude  DOUBLE PRECISION DEFAULT 120,
    p_force_gen      BOOLEAN DEFAULT FALSE,
    p_project_id     VARCHAR DEFAULT NULL,
    p_create_user    VARCHAR DEFAULT NULL,
    p_height_mode    DOUBLE PRECISION DEFAULT 0
) RETURNS TABLE (
    code integer,
    msg text,
    id integer,
    project_id char(32),
    create_user varchar(32),
    create_time timestamp,
    update_user varchar(32),
    update_time timestamp,
    del_flag boolean,
    start_point geometry(PointZ,4326),
    end_point geometry(PointZ,4326),
    safe_altitude double precision,
    path_line geometry(LineStringZ,4326),
    smooth_path_line geometry(LineStringZ,4326),
    waypoints jsonb,
    smooth_waypoints jsonb,
    total_distance double precision,
    smooth_ratio double precision
) AS $$
DECLARE
    v_start_time timestamptz := clock_timestamp();
    v_return_msg TEXT;

    v_input_count INT;
    v_segment_m DOUBLE PRECISION;
    v_input_idx INT;
    v_ratio1 DOUBLE PRECISION;
    v_ratio2 DOUBLE PRECISION;
    v_anchor_m DOUBLE PRECISION;
    v_probe_m DOUBLE PRECISION;
    v_last_safe_m DOUBLE PRECISION;
    v_exit_m DOUBLE PRECISION;
    v_anchor_point geometry(PointZ,4326);
    v_probe_point geometry(PointZ,4326);
    v_probe_line geometry(LineStringZ,4326);
    v_probe_point_blocked boolean;
    v_probe_line_blocked boolean;
    v_scan_m DOUBLE PRECISION;
    v_scan_limit_m DOUBLE PRECISION;
    v_seen_blocked boolean;

    v_lon1 DOUBLE PRECISION;
    v_lat1 DOUBLE PRECISION;
    v_alt1 DOUBLE PRECISION;
    v_lon2 DOUBLE PRECISION;
    v_lat2 DOUBLE PRECISION;
    v_alt2 DOUBLE PRECISION;

    v_seg_start_lon DOUBLE PRECISION;
    v_seg_start_lat DOUBLE PRECISION;
    v_seg_start_alt DOUBLE PRECISION;
    v_seg_end_lon DOUBLE PRECISION;
    v_seg_end_lat DOUBLE PRECISION;
    v_seg_end_alt DOUBLE PRECISION;

    v_part gis_flight_paths%ROWTYPE;
    v_part_count INT := 0;
    v_path_id INT;
    v_direct_line geometry(LineStringZ,4326);

    v_start_pt geometry(PointZ,4326);
    v_end_pt geometry(PointZ,4326);
    v_merged_path_line geometry(LineStringZ,4326) := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
    v_merged_smooth_line geometry(LineStringZ,4326) := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
    v_waypoints JSONB;
    v_smooth_waypoints JSONB;

    v_point_idx INT;
    v_point_count INT;
    v_append_start INT;
    v_bad_point_seq INT;
    v_bad_point_lon DOUBLE PRECISION;
    v_bad_point_lat DOUBLE PRECISION;
    v_bad_point_alt DOUBLE PRECISION;
    v_log_sql      text;                 -- 当前函数调用SQL，用于错误日志
BEGIN
    v_log_sql := format('SELECT * FROM public.gis_flight_paths_plan(%L, %s, %L, %L, %L, %s);',
        p_points::text, COALESCE(p_safe_altitude::text, 'NULL'), p_force_gen, p_project_id, p_create_user, COALESCE(p_height_mode::text, 'NULL'));

    IF p_points IS NULL OR jsonb_typeof(p_points) <> 'array' THEN
        code := 400;
        msg := format('参数错误：p_points 必须是 JSONB 数组，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    IF p_safe_altitude IS NULL OR p_safe_altitude <= 0 THEN
        code := 400;
        msg := format('参数错误：安全高度必须大于0，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    DROP TABLE IF EXISTS tmp_flight_plan_input_points;
    CREATE TEMP TABLE tmp_flight_plan_input_points ON COMMIT DROP AS
    SELECT
        ord::INT AS seq,
        (
            CASE
                WHEN jsonb_typeof(elem) = 'array' THEN elem->>0
                ELSE elem->>'lon'
            END
        )::DOUBLE PRECISION AS lon,
        (
            CASE
                WHEN jsonb_typeof(elem) = 'array' THEN elem->>1
                ELSE elem->>'lat'
            END
        )::DOUBLE PRECISION AS lat,
        COALESCE(
            NULLIF(
                CASE
                    WHEN jsonb_typeof(elem) = 'array' THEN elem->>2
                    ELSE elem->>'alt'
                END,
                ''
            )::DOUBLE PRECISION,
            p_safe_altitude
        ) AS alt
    FROM jsonb_array_elements(p_points) WITH ORDINALITY AS t(elem, ord);

    SELECT COUNT(*) INTO v_input_count FROM tmp_flight_plan_input_points;
    IF v_input_count < 2 THEN
        code := 400;
        msg := format('参数错误：p_points 至少需要包含 2 个坐标点，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM tmp_flight_plan_input_points
        WHERE lon IS NULL OR lat IS NULL OR alt IS NULL
    ) THEN
        code := 400;
        msg := format('参数错误：p_points 中存在无效坐标点，必须包含 lon/lat/alt 或 [lon,lat,alt]，执行时间 %s 秒',
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    SELECT seq, lon, lat, alt
    INTO v_bad_point_seq, v_bad_point_lon, v_bad_point_lat, v_bad_point_alt
    FROM tmp_flight_plan_input_points
    WHERE gis_flight_point_in_fence(
        ST_SetSRID(ST_MakePoint(lon, lat, alt), 4326),
        p_project_id
    )
    ORDER BY seq
    LIMIT 1;

    IF v_bad_point_seq IS NOT NULL THEN
        code := 400;
        msg := format('参数错误：规划点 seq=%s 在禁飞区或管控区内，point=(%s,%s,%s)，执行时间 %s 秒',
                      v_bad_point_seq, v_bad_point_lon, v_bad_point_lat, v_bad_point_alt,
                      ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
        INSERT INTO public.gis_error_log(code, msg, sqlstring)
        VALUES (code, msg, v_log_sql);
        RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
        RETURN;
    END IF;

    SELECT ST_SetSRID(ST_MakePoint(lon, lat, alt), 4326)
    INTO v_start_pt
    FROM tmp_flight_plan_input_points
    WHERE seq = 1;

    SELECT ST_SetSRID(ST_MakePoint(lon, lat, alt), 4326)
    INTO v_end_pt
    FROM tmp_flight_plan_input_points
    WHERE seq = v_input_count;

    -- 相邻输入点逐段处理：沿直线按 5km 探测，安全段合并，遇障碍段才调用 A*。
    -- gis_astar_3d_flight 只负责计算障碍段并返回数据，不写入 gis_flight_paths。
    -- 本函数统一把所有分段结果合并后，只插入一条总航线。
    FOR v_input_idx IN 1..v_input_count - 1 LOOP
        SELECT lon, lat, alt INTO v_lon1, v_lat1, v_alt1
        FROM tmp_flight_plan_input_points WHERE seq = v_input_idx;

        SELECT lon, lat, alt INTO v_lon2, v_lat2, v_alt2
        FROM tmp_flight_plan_input_points WHERE seq = v_input_idx + 1;

        v_segment_m := SQRT(
            POWER((v_lon2 - v_lon1) * 111000.0 * COS(RADIANS((v_lat1 + v_lat2) / 2.0)), 2)
            + POWER((v_lat2 - v_lat1) * 111000.0, 2)
        );

        IF v_segment_m <= 0.001 THEN
            v_direct_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
            v_direct_line := ST_AddPoint(v_direct_line, ST_SetSRID(ST_MakePoint(v_lon1, v_lat1, v_alt1), 4326));
            IF p_height_mode = 0 AND abs(v_alt1 - p_safe_altitude) > 0.001 THEN
                v_direct_line := ST_AddPoint(v_direct_line,
                    ST_SetSRID(ST_MakePoint(v_lon1, v_lat1, p_safe_altitude), 4326)
                );
            END IF;
            IF p_height_mode = 0 AND abs(v_alt2 - p_safe_altitude) > 0.001 THEN
                v_direct_line := ST_AddPoint(v_direct_line,
                    ST_SetSRID(ST_MakePoint(v_lon2, v_lat2, p_safe_altitude), 4326)
                );
            END IF;
            v_direct_line := ST_AddPoint(v_direct_line, ST_SetSRID(ST_MakePoint(v_lon2, v_lat2, v_alt2), 4326));
            v_direct_line := gis_linestring_remove_duplicate_points(v_direct_line);

            v_point_count := ST_NumPoints(v_direct_line);
            v_append_start := CASE WHEN ST_NumPoints(v_merged_path_line) = 0 THEN 1 ELSE 2 END;
            FOR v_point_idx IN v_append_start..v_point_count LOOP
                v_merged_path_line := ST_AddPoint(v_merged_path_line, ST_PointN(v_direct_line, v_point_idx));
            END LOOP;

            v_point_count := ST_NumPoints(v_direct_line);
            v_append_start := CASE WHEN ST_NumPoints(v_merged_smooth_line) = 0 THEN 1 ELSE 2 END;
            FOR v_point_idx IN v_append_start..v_point_count LOOP
                v_merged_smooth_line := ST_AddPoint(v_merged_smooth_line, ST_PointN(v_direct_line, v_point_idx));
            END LOOP;

            v_part_count := v_part_count + 1;
            CONTINUE;
        END IF;

        v_anchor_m := 0;

        WHILE v_anchor_m < v_segment_m LOOP
            v_last_safe_m := v_anchor_m;

            LOOP
                v_probe_m := LEAST(v_last_safe_m + 5000.0, v_segment_m);
                v_ratio1 := CASE WHEN v_segment_m = 0 THEN 0 ELSE v_anchor_m / v_segment_m END;
                v_ratio2 := CASE WHEN v_segment_m = 0 THEN 1 ELSE v_probe_m / v_segment_m END;

                v_seg_start_lon := v_lon1 + (v_lon2 - v_lon1) * v_ratio1;
                v_seg_start_lat := v_lat1 + (v_lat2 - v_lat1) * v_ratio1;
                v_seg_start_alt := CASE WHEN v_anchor_m = 0 THEN v_alt1 ELSE p_safe_altitude END;

                v_seg_end_lon := v_lon1 + (v_lon2 - v_lon1) * v_ratio2;
                v_seg_end_lat := v_lat1 + (v_lat2 - v_lat1) * v_ratio2;
                v_seg_end_alt := CASE WHEN v_probe_m >= v_segment_m THEN v_alt2 ELSE p_safe_altitude END;

                v_anchor_point := ST_SetSRID(ST_MakePoint(v_seg_start_lon, v_seg_start_lat, v_seg_start_alt), 4326);
                v_probe_point := ST_SetSRID(ST_MakePoint(v_seg_end_lon, v_seg_end_lat, v_seg_end_alt), 4326);
                v_probe_line := ST_MakeLine(v_anchor_point, v_probe_point);

                v_probe_point_blocked := gis_flight_point_in_fence(v_probe_point, p_project_id);
                v_probe_line_blocked := gis_flight_line_intersects_fence(v_probe_line, p_project_id);

                IF NOT v_probe_point_blocked AND NOT v_probe_line_blocked THEN
                    v_last_safe_m := v_probe_m;

                    IF v_last_safe_m >= v_segment_m THEN
                        v_direct_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
                        v_direct_line := ST_AddPoint(v_direct_line, v_anchor_point);
                        IF p_height_mode = 0
                           AND v_anchor_m = 0
                           AND abs(v_seg_start_alt - p_safe_altitude) > 0.001 THEN
                            v_direct_line := ST_AddPoint(v_direct_line,
                                ST_SetSRID(ST_MakePoint(v_seg_start_lon, v_seg_start_lat, p_safe_altitude), 4326)
                            );
                        END IF;
                        IF p_height_mode = 0
                           AND v_probe_m >= v_segment_m
                           AND abs(v_seg_end_alt - p_safe_altitude) > 0.001 THEN
                            v_direct_line := ST_AddPoint(v_direct_line,
                                ST_SetSRID(ST_MakePoint(v_seg_end_lon, v_seg_end_lat, p_safe_altitude), 4326)
                            );
                        END IF;
                        v_direct_line := ST_AddPoint(v_direct_line, v_probe_point);
                        v_direct_line := gis_linestring_remove_duplicate_points(v_direct_line);

                        v_point_count := ST_NumPoints(v_direct_line);
                        v_append_start := CASE WHEN ST_NumPoints(v_merged_path_line) = 0 THEN 1 ELSE 2 END;
                        FOR v_point_idx IN v_append_start..v_point_count LOOP
                            v_merged_path_line := ST_AddPoint(v_merged_path_line, ST_PointN(v_direct_line, v_point_idx));
                        END LOOP;

                        v_point_count := ST_NumPoints(v_direct_line);
                        v_append_start := CASE WHEN ST_NumPoints(v_merged_smooth_line) = 0 THEN 1 ELSE 2 END;
                        FOR v_point_idx IN v_append_start..v_point_count LOOP
                            v_merged_smooth_line := ST_AddPoint(v_merged_smooth_line, ST_PointN(v_direct_line, v_point_idx));
                        END LOOP;

                        v_part_count := v_part_count + 1;
                        v_anchor_m := v_segment_m;
                        EXIT;
                    END IF;

                    CONTINUE;
                END IF;

                IF v_last_safe_m > v_anchor_m THEN
                    v_ratio2 := v_last_safe_m / v_segment_m;
                    v_seg_end_lon := v_lon1 + (v_lon2 - v_lon1) * v_ratio2;
                    v_seg_end_lat := v_lat1 + (v_lat2 - v_lat1) * v_ratio2;
                    v_seg_end_alt := p_safe_altitude;
                    v_probe_point := ST_SetSRID(ST_MakePoint(v_seg_end_lon, v_seg_end_lat, v_seg_end_alt), 4326);
                    v_direct_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
                    v_direct_line := ST_AddPoint(v_direct_line, v_anchor_point);
                    IF p_height_mode = 0
                       AND v_anchor_m = 0
                       AND abs(v_seg_start_alt - p_safe_altitude) > 0.001 THEN
                        v_direct_line := ST_AddPoint(v_direct_line,
                            ST_SetSRID(ST_MakePoint(v_seg_start_lon, v_seg_start_lat, p_safe_altitude), 4326)
                        );
                    END IF;
                    v_direct_line := ST_AddPoint(v_direct_line, v_probe_point);
                    v_direct_line := gis_linestring_remove_duplicate_points(v_direct_line);

                    v_point_count := ST_NumPoints(v_direct_line);
                    v_append_start := CASE WHEN ST_NumPoints(v_merged_path_line) = 0 THEN 1 ELSE 2 END;
                    FOR v_point_idx IN v_append_start..v_point_count LOOP
                        v_merged_path_line := ST_AddPoint(v_merged_path_line, ST_PointN(v_direct_line, v_point_idx));
                    END LOOP;

                    v_point_count := ST_NumPoints(v_direct_line);
                    v_append_start := CASE WHEN ST_NumPoints(v_merged_smooth_line) = 0 THEN 1 ELSE 2 END;
                    FOR v_point_idx IN v_append_start..v_point_count LOOP
                        v_merged_smooth_line := ST_AddPoint(v_merged_smooth_line, ST_PointN(v_direct_line, v_point_idx));
                    END LOOP;

                    v_part_count := v_part_count + 1;
                    v_anchor_m := v_last_safe_m;
                    EXIT;
                END IF;

                IF v_probe_point_blocked OR v_probe_line_blocked THEN
                    RAISE NOTICE '【分段探测】input_seq=%, 5km探测命中禁飞/管控，开始从1km递增探测，anchor_m=%, first_probe_m=%, point_blocked=%, line_blocked=%',
                        v_input_idx,
                        ROUND(v_anchor_m::numeric, 2),
                        ROUND(v_probe_m::numeric, 2),
                        v_probe_point_blocked,
                        v_probe_line_blocked;

                    v_seen_blocked := false;
                    v_exit_m := NULL;
                    v_scan_limit_m := LEAST(v_anchor_m + 30000.0, v_segment_m);
                    v_scan_m := LEAST(v_anchor_m + 1000.0, v_segment_m);

                    WHILE v_scan_m <= v_scan_limit_m LOOP
                        v_ratio2 := v_scan_m / v_segment_m;
                        v_seg_end_lon := v_lon1 + (v_lon2 - v_lon1) * v_ratio2;
                        v_seg_end_lat := v_lat1 + (v_lat2 - v_lat1) * v_ratio2;
                        v_seg_end_alt := CASE WHEN v_scan_m >= v_segment_m THEN v_alt2 ELSE p_safe_altitude END;
                        v_probe_point := ST_SetSRID(ST_MakePoint(v_seg_end_lon, v_seg_end_lat, v_seg_end_alt), 4326);
                        v_probe_line := ST_MakeLine(v_anchor_point, v_probe_point);

                        v_probe_point_blocked := gis_flight_point_in_fence(v_probe_point, p_project_id);
                        v_probe_line_blocked := gis_flight_line_intersects_fence(v_probe_line, p_project_id);

                        RAISE NOTICE '【分段探测】input_seq=%, anchor_m=%, scan_m=%, lon=%, lat=%, alt=%, point_blocked=%, line_blocked=%',
                            v_input_idx,
                            ROUND(v_anchor_m::numeric, 2),
                            ROUND(v_scan_m::numeric, 2),
                            v_seg_end_lon,
                            v_seg_end_lat,
                            v_seg_end_alt,
                            v_probe_point_blocked,
                            v_probe_line_blocked;

                        IF NOT v_seen_blocked AND NOT v_probe_point_blocked AND NOT v_probe_line_blocked THEN
                            v_last_safe_m := v_scan_m;
                        ELSE
                            v_seen_blocked := true;
                        END IF;

                        IF v_seen_blocked AND NOT v_probe_point_blocked THEN
                            v_exit_m := v_scan_m;
                            RAISE NOTICE '【分段探测】input_seq=%, 找到出口点 exit_m=%, last_safe_m=%',
                                v_input_idx,
                                ROUND(v_exit_m::numeric, 2),
                                ROUND(v_last_safe_m::numeric, 2);
                            EXIT;
                        END IF;

                        IF v_scan_m >= v_scan_limit_m THEN
                            EXIT;
                        END IF;
                        v_scan_m := LEAST(v_scan_m + 1000.0, v_segment_m);
                    END LOOP;

                    IF v_last_safe_m > v_anchor_m THEN
                        v_ratio2 := v_last_safe_m / v_segment_m;
                        v_seg_end_lon := v_lon1 + (v_lon2 - v_lon1) * v_ratio2;
                        v_seg_end_lat := v_lat1 + (v_lat2 - v_lat1) * v_ratio2;
                        v_seg_end_alt := p_safe_altitude;
                        v_probe_point := ST_SetSRID(ST_MakePoint(v_seg_end_lon, v_seg_end_lat, v_seg_end_alt), 4326);
                        v_direct_line := ST_SetSRID('LINESTRING Z EMPTY'::geometry, 4326);
                        v_direct_line := ST_AddPoint(v_direct_line, v_anchor_point);
                        v_direct_line := ST_AddPoint(v_direct_line, v_probe_point);
                        v_direct_line := gis_linestring_remove_duplicate_points(v_direct_line);

                        v_point_count := ST_NumPoints(v_direct_line);
                        v_append_start := CASE WHEN ST_NumPoints(v_merged_path_line) = 0 THEN 1 ELSE 2 END;
                        FOR v_point_idx IN v_append_start..v_point_count LOOP
                            v_merged_path_line := ST_AddPoint(v_merged_path_line, ST_PointN(v_direct_line, v_point_idx));
                        END LOOP;

                        v_point_count := ST_NumPoints(v_direct_line);
                        v_append_start := CASE WHEN ST_NumPoints(v_merged_smooth_line) = 0 THEN 1 ELSE 2 END;
                        FOR v_point_idx IN v_append_start..v_point_count LOOP
                            v_merged_smooth_line := ST_AddPoint(v_merged_smooth_line, ST_PointN(v_direct_line, v_point_idx));
                        END LOOP;

                        v_part_count := v_part_count + 1;
                        v_anchor_m := v_last_safe_m;
                        EXIT;
                    END IF;

                    IF v_exit_m IS NULL THEN
                        RAISE NOTICE '【分段探测】input_seq=%, 未找到出口点，anchor_m=%, scan_limit_m=%',
                            v_input_idx,
                            ROUND(v_anchor_m::numeric, 2),
                            ROUND(v_scan_limit_m::numeric, 2);
                        RAISE EXCEPTION '分段路径规划失败：input_seq=%, anchor_m=%, scan_limit_m=%，按1km探测至30km未找到禁飞/管控出口点',
                            v_input_idx,
                            ROUND(v_anchor_m::numeric, 2),
                            ROUND(v_scan_limit_m::numeric, 2);
                    END IF;

                    v_probe_m := v_exit_m;
                END IF;

                v_ratio1 := v_anchor_m / v_segment_m;
                v_ratio2 := v_probe_m / v_segment_m;

                v_seg_start_lon := v_lon1 + (v_lon2 - v_lon1) * v_ratio1;
                v_seg_start_lat := v_lat1 + (v_lat2 - v_lat1) * v_ratio1;
                v_seg_start_alt := CASE WHEN v_anchor_m = 0 THEN v_alt1 ELSE p_safe_altitude END;
                v_seg_end_lon := v_lon1 + (v_lon2 - v_lon1) * v_ratio2;
                v_seg_end_lat := v_lat1 + (v_lat2 - v_lat1) * v_ratio2;
                v_seg_end_alt := CASE WHEN v_probe_m >= v_segment_m THEN v_alt2 ELSE p_safe_altitude END;

                IF (v_probe_m - v_anchor_m) <= 5000.0 THEN
                    SELECT
                        r.id, r.project_id, r.create_user, r.create_time,
                        r.update_user, r.update_time, r.del_flag,
                        r.start_point, r.end_point, r.safe_altitude,
                        r.path_line, r.smooth_path_line,
                        r.waypoints, r.smooth_waypoints,
                        r.total_distance, r.smooth_ratio
                    INTO v_part
                    FROM gis_astar_3d_flight_plan(
                        v_seg_start_lon, v_seg_start_lat, v_seg_start_alt,
                        v_seg_end_lon, v_seg_end_lat, v_seg_end_alt,
                        p_safe_altitude,
                        p_height_mode,
                        TRUE,
                        p_project_id,
                        p_create_user
                    ) r
                    LIMIT 1;
                ELSE
                    -- 点落入较长围栏时，离开点可能超过 5km；这里直接调用核心函数，避免两点入口再次回到本函数形成递归。
                    SELECT
                        r.id, r.project_id, r.create_user, r.create_time,
                        r.update_user, r.update_time, r.del_flag,
                        r.start_point, r.end_point, r.safe_altitude,
                        r.path_line, r.smooth_path_line,
                        r.waypoints, r.smooth_waypoints,
                        r.total_distance, r.smooth_ratio
                    INTO v_part
                    FROM gis_astar_3d_flight(
                        v_seg_start_lon, v_seg_start_lat, v_seg_start_alt,
                        v_seg_end_lon, v_seg_end_lat, v_seg_end_alt,
                        p_safe_altitude,
                        p_height_mode,
                        TRUE,
                        p_project_id,
                        p_create_user
                    ) r
                    LIMIT 1;
                END IF;

                IF v_part.path_line IS NULL OR v_part.smooth_path_line IS NULL THEN
                    RAISE EXCEPTION '分段路径规划失败：input_seq=%, anchor_m=%, probe_m=%, segment_m=%',
                        v_input_idx,
                        ROUND(v_anchor_m::numeric, 2),
                        ROUND(v_probe_m::numeric, 2),
                        ROUND((v_probe_m - v_anchor_m)::numeric, 2);
                END IF;

                v_part_count := v_part_count + 1;

                v_point_count := ST_NumPoints(v_part.path_line);
                v_append_start := CASE WHEN ST_NumPoints(v_merged_path_line) = 0 THEN 1 ELSE 2 END;
                FOR v_point_idx IN v_append_start..v_point_count LOOP
                    v_merged_path_line := ST_AddPoint(v_merged_path_line, ST_PointN(v_part.path_line, v_point_idx));
                END LOOP;

                v_point_count := ST_NumPoints(v_part.smooth_path_line);
                v_append_start := CASE WHEN ST_NumPoints(v_merged_smooth_line) = 0 THEN 1 ELSE 2 END;
                FOR v_point_idx IN v_append_start..v_point_count LOOP
                    v_merged_smooth_line := ST_AddPoint(v_merged_smooth_line, ST_PointN(v_part.smooth_path_line, v_point_idx));
                END LOOP;

                v_anchor_m := v_probe_m;
                EXIT;
            END LOOP;
        END LOOP;
    END LOOP;

    v_merged_path_line := gis_linestring_remove_duplicate_points(v_merged_path_line);
    v_merged_smooth_line := gis_linestring_remove_duplicate_points(v_merged_smooth_line);

    SELECT jsonb_agg(
        jsonb_build_object('lon', ST_X((dp).geom), 'lat', ST_Y((dp).geom), 'alt', ST_Z((dp).geom))
        ORDER BY (dp).path[1]
    )
    INTO v_waypoints
    FROM ST_DumpPoints(v_merged_path_line) AS dp;

    SELECT jsonb_agg(
        jsonb_build_object('lon', ST_X((dp).geom), 'lat', ST_Y((dp).geom), 'alt', ST_Z((dp).geom))
        ORDER BY (dp).path[1]
    )
    INTO v_smooth_waypoints
    FROM ST_DumpPoints(v_merged_smooth_line) AS dp;

    -- 所有分段点已经合并到 v_merged_path_line / v_merged_smooth_line。
    -- 这里只插入一条总航线记录，最终返回的也是这一条记录。
    INSERT INTO gis_flight_paths (
        project_id, create_user, update_user,
        start_point, end_point, safe_altitude,
        path_line, smooth_path_line,
        waypoints, smooth_waypoints, total_distance, smooth_ratio
    ) VALUES (
        p_project_id, p_create_user, p_create_user,
        v_start_pt, v_end_pt, p_safe_altitude,
        v_merged_path_line, v_merged_smooth_line,
        v_waypoints, v_smooth_waypoints,
        gis_linestring_length_m(v_merged_smooth_line),
        p_height_mode
    ) RETURNING gis_flight_paths.id INTO v_path_id;

    -- 子分段只在内存中参与合并，不产生分段航线记录。
    v_return_msg := format('规划成功：多点/长距离探测规划完成，共处理 %s 个航段，执行时间 %s 秒',
                           v_part_count,
                           ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    RETURN QUERY SELECT 200, v_return_msg, p.* FROM gis_flight_paths p WHERE p.id = v_path_id;

EXCEPTION WHEN OTHERS THEN
    code := 500;
    msg := format('执行异常：%s，执行时间 %s 秒',
                  SQLERRM,
                  ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3));
    INSERT INTO public.gis_error_log(code, msg, sqlstring)
    VALUES (code, msg, v_log_sql);
    RETURN QUERY SELECT code, msg, (NULL::gis_flight_paths).*;
END;
$$ LANGUAGE plpgsql;
COMMENT ON FUNCTION gis_flight_paths_plan(JSONB, DOUBLE PRECISION, BOOLEAN, VARCHAR, VARCHAR, DOUBLE PRECISION) IS '多点航线自动分段规划';

 -- =============================================================================
-- 删除函数
-- =============================================================================
SELECT gis_drop_function('gis_check_point_in_polygon');

-- =============================================================================
-- 函数介绍：gis_check_point_in_polygon
-- 主要作用：判断一个或多个点是否落入给定面或立体高度范围。
-- 入参说明：p_polygon_text 为面WKT/GeoJSON文本；p_point_array 为单点或多点坐标数组JSON。
-- 返回说明：返回每个点的命中状态、判断类型、点几何和面几何，供临时校验或接口联调用。
-- 注意事项：有有效高度时做平面+高度判断；无有效高度时只做平面判断。
-- =============================================================================
CREATE OR REPLACE FUNCTION public.gis_check_point_in_polygon(
    p_polygon_text text,
    p_point_array text
)
RETURNS TABLE (
    code integer,
    msg varchar,
    ischeck boolean,
    check_type varchar,
    point_geom geometry,
    polygon_geom geometry,
    point_geom_json json,
    polygon_geom_json json
)
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
    v_polygon geometry;
    v_polygon_json jsonb;
    v_point_json jsonb;
    v_min_z double precision;
    v_max_z double precision;
    v_geom_min_z double precision;
    v_geom_max_z double precision;
    v_has_height boolean := false;
    v_start_time timestamptz := clock_timestamp();
BEGIN
    -- 先校验面参数，支持 WKT 或 GeoJSON。
    IF p_polygon_text IS NULL OR btrim(p_polygon_text) = '' THEN
        RETURN QUERY SELECT
            400,
            format('面参数不能为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false,
            'invalid_param'::varchar,
            NULL::geometry,
            NULL::geometry,
            NULL::json,
            NULL::json;
        RETURN;
    END IF;

    -- 校验点参数，必须是 JSON 文本。
    IF p_point_array IS NULL OR btrim(p_point_array) = '' THEN
        RETURN QUERY SELECT
            400,
            format('点数组不能为空，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false,
            'invalid_param'::varchar,
            NULL::geometry,
            NULL::geometry,
            NULL::json,
            NULL::json;
        RETURN;
    END IF;

    -- 解析面参数：以 "{" 开头按 GeoJSON 处理，否则按 WKT 处理。
    BEGIN
        IF left(btrim(p_polygon_text), 1) = '{' THEN
            v_polygon_json := p_polygon_text::jsonb;

            IF v_polygon_json ->> 'type' = 'Feature' THEN
                v_polygon := ST_SetSRID(ST_GeomFromGeoJSON((v_polygon_json -> 'geometry')::text), 4326);
                v_min_z := COALESCE(
                    (v_polygon_json -> 'properties' ->> 'min_alt')::double precision,
                    (v_polygon_json -> 'properties' ->> 'min_height')::double precision,
                    0
                );
                v_max_z := COALESCE(
                    (v_polygon_json -> 'properties' ->> 'max_alt')::double precision,
                    (v_polygon_json -> 'properties' ->> 'max_height')::double precision,
                    (v_polygon_json -> 'properties' ->> 'height')::double precision
                );
            ELSE
                v_polygon := ST_SetSRID(ST_GeomFromGeoJSON(p_polygon_text), 4326);
                v_min_z := COALESCE(
                    (v_polygon_json ->> 'min_alt')::double precision,
                    (v_polygon_json ->> 'min_height')::double precision,
                    0
                );
                v_max_z := COALESCE(
                    (v_polygon_json ->> 'max_alt')::double precision,
                    (v_polygon_json ->> 'max_height')::double precision,
                    (v_polygon_json ->> 'height')::double precision
                );
            END IF;
        ELSE
            v_polygon := ST_SetSRID(ST_GeomFromText(p_polygon_text), 4326);
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN QUERY SELECT
                400,
                format('面参数解析失败：%s，执行时间 %s 秒',
                    SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
                false,
                'invalid_param'::varchar,
                NULL::geometry,
                NULL::geometry,
                NULL::json,
                NULL::json;
            RETURN;
    END;

    -- 点面校验只允许 Polygon/MultiPolygon 面几何。
    IF ST_GeometryType(v_polygon) NOT IN ('ST_Polygon', 'ST_MultiPolygon') THEN
        RETURN QUERY SELECT
            400,
            format('面参数必须是Polygon或MultiPolygon，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false,
            'invalid_param'::varchar,
            NULL::geometry,
            v_polygon,
            NULL::json,
            ST_AsGeoJSON(v_polygon)::json;
        RETURN;
    END IF;

    -- 从面坐标 Z 值中读取高度范围；如果 properties 已提供高度，则优先使用 properties。
    SELECT
        MIN(ST_Z((dp).geom)),
        MAX(ST_Z((dp).geom))
    INTO v_geom_min_z, v_geom_max_z
    FROM ST_DumpPoints(v_polygon) AS dp
    WHERE ST_Z((dp).geom) IS NOT NULL;

    v_min_z := COALESCE(v_min_z, v_geom_min_z, 0);
    v_max_z := COALESCE(v_max_z, v_geom_max_z, 0);
    v_has_height := COALESCE(v_max_z, 0) > 0;

    -- 面参数合法后再解析点数组 JSON。
    BEGIN
        v_point_json := p_point_array::jsonb;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN QUERY SELECT
                400,
                format('点数组解析失败：%s，执行时间 %s 秒',
                    SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
                false,
                'invalid_param'::varchar,
                NULL::geometry,
                v_polygon,
                NULL::json,
                ST_AsGeoJSON(v_polygon)::json;
            RETURN;
    END;

    -- 顶层必须是单点坐标数组，或多点坐标数组。
    IF jsonb_typeof(v_point_json) <> 'array' OR jsonb_array_length(v_point_json) = 0 THEN
        RETURN QUERY SELECT
            400,
            format('点数组必须是 [lng,lat,alt] 或 [[lng,lat,alt],...]，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false,
            'invalid_param'::varchar,
            NULL::geometry,
            v_polygon,
            NULL::json,
            ST_AsGeoJSON(v_polygon)::json;
        RETURN;
    END IF;

    RETURN QUERY
    WITH point_items AS (
        -- 单点输入：[lng, lat, alt]。
        SELECT
            1 AS item_index,
            v_point_json AS point_item
        WHERE jsonb_typeof(v_point_json -> 0) <> 'array'

        UNION ALL

        -- 多点输入：[[lng, lat, alt], ...]。
        SELECT
            p.ord::integer AS item_index,
            p.value AS point_item
        FROM jsonb_array_elements(v_point_json) WITH ORDINALITY AS p(value, ord)
        WHERE jsonb_typeof(v_point_json -> 0) = 'array'
    ),
    parsed_points AS (
        -- 将每个合法坐标数组转换为 SRID=4326 的 Point 几何。
        SELECT
            item_index,
            CASE
                WHEN jsonb_typeof(point_item) = 'array'
                 AND jsonb_array_length(point_item) >= 2
                THEN ST_SetSRID(ST_MakePoint(
                    (point_item ->> 0)::double precision,
                    (point_item ->> 1)::double precision,
                    COALESCE((point_item ->> 2)::double precision, 0)
                ), 4326)
                ELSE NULL::geometry
            END AS item_geom
        FROM point_items
    ),
    checked_points AS (
        -- 面有高度时，同时判断平面命中和高度范围；面无高度时，只判断平面命中。
        SELECT
            item_index,
            item_geom,
            CASE
                WHEN item_geom IS NULL THEN false
                WHEN NOT ST_Covers(ST_Force2D(v_polygon), ST_Force2D(item_geom)) THEN false
                WHEN NOT v_has_height THEN true
                WHEN v_max_z > v_min_z THEN COALESCE(ST_Z(item_geom), 0) BETWEEN v_min_z AND v_max_z
                ELSE COALESCE(ST_Z(item_geom), 0) BETWEEN 0 AND v_max_z
            END AS is_inside,
            CASE
                WHEN item_geom IS NULL THEN false
                ELSE ST_Covers(ST_Force2D(v_polygon), ST_Force2D(item_geom))
            END AS is_horizontal_inside,
            CASE
                WHEN item_geom IS NULL THEN false
                WHEN NOT v_has_height THEN true
                WHEN v_max_z > v_min_z THEN COALESCE(ST_Z(item_geom), 0) BETWEEN v_min_z AND v_max_z
                ELSE COALESCE(ST_Z(item_geom), 0) BETWEEN 0 AND v_max_z
            END AS is_height_inside
        FROM parsed_points
    )
    SELECT
        CASE WHEN item_geom IS NULL THEN 400 ELSE 200 END AS code,
        CASE
            WHEN item_geom IS NULL THEN format('点坐标项非法，check_type=invalid_param，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
            WHEN is_inside AND v_has_height THEN format('点在面内或边界上，且高度在范围内，check_type=p_inner_3d，高度范围[%s,%s]，执行时间 %s 秒',
                v_min_z, v_max_z, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
            WHEN is_inside THEN format('点在面内或边界上，check_type=p_inner，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
            WHEN v_has_height AND is_horizontal_inside AND NOT is_height_inside THEN format('点平面位置在面内或边界上，但高度超出范围，check_type=p_outer_height，高度范围[%s,%s]，执行时间 %s 秒',
                v_min_z, v_max_z, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
            ELSE format('点在面外，check_type=p_outer，执行时间 %s 秒',
                ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))
        END::varchar AS msg,
        is_inside AS ischeck,
        CASE
            WHEN item_geom IS NULL THEN 'invalid_param'
            WHEN is_inside AND v_has_height THEN 'p_inner_3d'
            WHEN is_inside THEN 'p_inner'
            WHEN v_has_height AND is_horizontal_inside AND NOT is_height_inside THEN 'p_outer_height'
            ELSE 'p_outer'
        END::varchar AS check_type,
        item_geom AS point_geom,
        v_polygon AS polygon_geom,
        CASE WHEN item_geom IS NULL THEN NULL::json ELSE ST_AsGeoJSON(item_geom)::json END AS point_geom_json,
        ST_AsGeoJSON(v_polygon)::json AS polygon_geom_json
    FROM checked_points
    ORDER BY item_index;

EXCEPTION
    WHEN OTHERS THEN
        RETURN QUERY SELECT
            500,
            format('服务异常：%s，执行时间 %s 秒',
                SQLERRM, ROUND(EXTRACT(epoch FROM clock_timestamp() - v_start_time)::numeric, 3))::varchar,
            false,
            'error'::varchar,
            NULL::geometry,
            NULL::geometry,
            NULL::json,
            NULL::json;
END;
$$;

COMMENT ON FUNCTION public.gis_check_point_in_polygon(text, text)
IS '判断一个或多个 [经度,纬度,高度] 点是否位于 Polygon/MultiPolygon 面内、边界上或立体高度范围内。';



